import type { BankQuestion } from "@/lib/bank";

/** Time, Speed and Distance (Quantitative Aptitude): 208 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-tsd-1","question":"72 km/h is equal to:","options":["18 m/s","20 m/s","25 m/s","36 m/s"],"answer":1,"explanation":"Multiply km/h by 5/18 to get m/s: 72 × 5/18 = 20 m/s. 36 m/s just halves 72, and 18 or 25 m/s are slips in the 5/18 factor.","difficulty":"easy","questionHi":"72 km/h बराबर है:","optionsHi":["18 m/s","20 m/s","25 m/s","36 m/s"],"explanationHi":"km/h को m/s में बदलने के लिए 5/18 से गुणा करें: 72 × 5/18 = 20 m/s। 36 m/s में 72 को बस आधा कर दिया गया है, और 18 या 25 m/s 5/18 गुणक में हुई चूकें हैं।","subtopic":"basic-speed"},
  {"id":"quant-tsd-2","question":"A 150 m long train passes a pole in 9 seconds. Its speed is:","options":["50 km/h","54 km/h","60 km/h","72 km/h"],"answer":2,"explanation":"Passing a pole, the train covers only its own length: 150/9 = 50/3 m/s, and × 18/5 = 60 km/h. 50 km/h forgets the unit conversion and reads 50/3 as 50.","difficulty":"moderate","questionHi":"150 m लंबी एक रेलगाड़ी एक खंभे को 9 सेकंड में पार करती है। उसकी चाल है:","optionsHi":["50 km/h","54 km/h","60 km/h","72 km/h"],"explanationHi":"खंभे को पार करते समय रेलगाड़ी केवल अपनी लंबाई के बराबर दूरी तय करती है: 150/9 = 50/3 m/s, और × 18/5 = 60 km/h। 50 km/h इकाई-परिवर्तन भूलकर 50/3 को 50 पढ़ लेना है।","subtopic":"trains"},
  {"id":"quant-tsd-3","question":"Trains 120 m and 180 m long run in opposite directions at 40 km/h and 50 km/h. How long do they take to cross each other?","options":["10 seconds","12 seconds","15 seconds","18 seconds"],"answer":1,"explanation":"Relative speed = 90 km/h = 25 m/s; distance = 300 m; time = 12 s.","difficulty":"hard","questionHi":"120 m और 180 m लंबी दो रेलगाड़ियाँ विपरीत दिशाओं में क्रमशः 40 km/h और 50 km/h की चाल से चल रही हैं। वे एक-दूसरे को कितने समय में पार करेंगी?","optionsHi":["10 सेकंड","12 सेकंड","15 सेकंड","18 सेकंड"],"explanationHi":"सापेक्ष चाल = 90 km/h = 25 m/s; दूरी = 300 m; समय = 12 s।","subtopic":"trains"},
  {"id":"quant-tsd-4","question":"A boat goes 24 km downstream in 2 hours and returns upstream in 3 hours. What is the speed of the stream?","options":["1 km/h","2 km/h","3 km/h","4 km/h"],"answer":1,"explanation":"Downstream 12 km/h, upstream 8 km/h; stream = (12 − 8) ÷ 2 = 2 km/h.","difficulty":"very-hard","questionHi":"एक नाव 24 km धारा के अनुकूल 2 घंटे में जाती है और धारा के प्रतिकूल 3 घंटे में लौटती है। धारा की चाल क्या है?","optionsHi":["1 km/h","2 km/h","3 km/h","4 km/h"],"explanationHi":"धारा के अनुकूल 12 km/h, प्रतिकूल 8 km/h; धारा की चाल = (12 − 8) ÷ 2 = 2 km/h।","subtopic":"boats-streams"},
  {"id":"quant-tsd-5","question":"A man walking at 5 km/h covers 2.5 km in:","options":["25 minutes","30 minutes","40 minutes","50 minutes"],"answer":1,"explanation":"Time = distance/speed = 2.5/5 = 0.5 hour = 30 minutes. 25 or 50 minutes come from misconverting 0.5 hour as if 1 hour had 100 minutes.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"5 km/h की चाल से चलने वाला एक आदमी 2.5 km की दूरी कितने समय में तय करता है?","optionsHi":["25 मिनट","30 मिनट","40 मिनट","50 मिनट"],"explanationHi":"समय = दूरी/चाल = 2.5/5 = 0.5 घंटा = 30 मिनट। 25 या 50 मिनट 0.5 घंटे को ऐसे बदलने से आते हैं मानो 1 घंटे में 100 मिनट होते हों।","subtopic":"basic-speed"},
  {"id":"quant-tsd-6","question":"A 200 m long train running at 72 km/h passes a man standing on the platform in:","options":["10 s","20 s","12 s","8 s"],"answer":0,"explanation":"72 km/h = 20 m/s, and passing a standing man means covering just the train's 200 m: 200/20 = 10 s. 20 s confuses the speed in m/s with the time.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"72 km/h की चाल से चलती 200 m लंबी रेलगाड़ी प्लेटफ़ॉर्म पर खड़े एक आदमी को कितने समय में पार करती है?","optionsHi":["10 s","20 s","12 s","8 s"],"explanationHi":"72 km/h = 20 m/s, और खड़े आदमी को पार करने का अर्थ है केवल रेलगाड़ी की 200 m लंबाई तय करना: 200/20 = 10 s। 20 s m/s में दी गई चाल को समय समझ लेना है।","subtopic":"trains"},
  {"id":"quant-tsd-7","question":"A 240 m long train crosses a 360 m long platform in 30 seconds. Its speed is:","options":["54 km/h","60 km/h","72 km/h","80 km/h"],"answer":2,"explanation":"Distance = 240 + 360 = 600 m in 30 s = 20 m/s = 72 km/h. Using only the platform length gives 43.2 km/h.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"240 m लंबी एक रेलगाड़ी 360 m लंबे प्लेटफ़ॉर्म को 30 सेकंड में पार करती है। उसकी चाल है:","optionsHi":["54 km/h","60 km/h","72 km/h","80 km/h"],"explanationHi":"दूरी = 240 + 360 = 600 m, 30 s में = 20 m/s = 72 km/h। केवल प्लेटफ़ॉर्म की लंबाई लेने पर 43.2 km/h आता है।","subtopic":"trains"},
  {"id":"quant-tsd-8","question":"A car covers the first half of a distance at 40 km/h and the second half at 60 km/h. Its average speed is:","options":["45 km/h","48 km/h","52 km/h","50 km/h"],"answer":1,"explanation":"Equal distances: 2 × 40 × 60/(40 + 60) = 4,800/100 = 48 km/h.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"एक कार दूरी का पहला आधा भाग 40 km/h की चाल से और दूसरा आधा भाग 60 km/h की चाल से तय करती है। उसकी औसत चाल है:","optionsHi":["45 km/h","48 km/h","52 km/h","50 km/h"],"explanationHi":"समान दूरियों के लिए: 2 × 40 × 60/(40 + 60) = 4,800/100 = 48 km/h।","subtopic":"average-speed"},
  {"id":"quant-tsd-9","question":"Walking at 3/4 of his usual speed a man reaches office 10 minutes late. His usual time is:","options":["30 minutes","20 minutes","45 minutes","40 minutes"],"answer":0,"explanation":"At 3/4 speed the time becomes 4/3 of usual; the extra 1/3 of the usual time = 10 min, so the usual time = 30 min.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"अपनी सामान्य चाल की 3/4 चाल से चलने पर एक आदमी कार्यालय 10 मिनट देर से पहुँचता है। उसका सामान्य समय है:","optionsHi":["30 मिनट","20 मिनट","45 मिनट","40 मिनट"],"explanationHi":"3/4 चाल पर समय सामान्य का 4/3 हो जाता है; सामान्य समय का अतिरिक्त 1/3 भाग = 10 मिनट, इसलिए सामान्य समय = 30 मिनट।","subtopic":"late-early"},
  {"id":"quant-tsd-10","question":"A boat's speed in still water is 10 km/h and the stream flows at 2 km/h. The total time to go 24 km downstream and return is:","options":["4.8 hours","5 hours","6 hours","4 hours"],"answer":1,"explanation":"Downstream 24/12 = 2 h; upstream 24/8 = 3 h; total 5 h. 4.8 h wrongly uses 10 km/h both ways.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"स्थिर जल में एक नाव की चाल 10 km/h है और धारा 2 km/h की चाल से बहती है। 24 km धारा के अनुकूल जाने और लौटने का कुल समय है:","optionsHi":["4.8 घंटे","5 घंटे","6 घंटे","4 घंटे"],"explanationHi":"धारा के अनुकूल 24/12 = 2 घंटे; प्रतिकूल 24/8 = 3 घंटे; कुल 5 घंटे। 4.8 घंटे दोनों ओर गलती से 10 km/h लेने से आता है।","subtopic":"boats-streams"},
  {"id":"quant-tsd-11","question":"Two trains start at the same time from P and Q, 450 km apart, towards each other at 40 km/h and 50 km/h. When they meet, the faster train has travelled how much more than the slower?","options":["25 km","45 km","50 km","60 km"],"answer":2,"explanation":"They meet after 450/90 = 5 h, having covered 200 km and 250 km, a difference of 50 km.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"दो रेलगाड़ियाँ एक-दूसरे की ओर P और Q से एक ही समय चलती हैं, जो 450 km दूर हैं, और उनकी चाल 40 km/h और 50 km/h है। मिलने पर तेज़ रेलगाड़ी ने धीमी से कितनी अधिक दूरी तय की होगी?","optionsHi":["25 km","45 km","50 km","60 km"],"explanationHi":"वे 450/90 = 5 घंटे बाद मिलती हैं, और क्रमशः 200 km तथा 250 km चली होती हैं, अंतर 50 km।","subtopic":"relative-speed"},
  {"id":"quant-tsd-12","question":"A bus averages 60 km/h excluding stoppages and 45 km/h including stoppages. For how many minutes per hour does it stop?","options":["15 minutes","20 minutes","12 minutes","10 minutes"],"answer":0,"explanation":"Each hour it loses 15 km, which takes 15/60 h = 15 minutes at the running speed.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक बस की औसत चाल रुकने के समय को छोड़कर 60 km/h और रुकने के समय सहित 45 km/h है। वह प्रति घंटा कितने मिनट रुकती है?","optionsHi":["15 मिनट","20 मिनट","12 मिनट","10 मिनट"],"explanationHi":"प्रत्येक घंटे में वह 15 km पीछे रह जाती है, जिसे चलने की चाल पर तय करने में 15/60 घंटा = 15 मिनट लगते हैं।","subtopic":"average-speed"},
  {"id":"quant-tsd-13","question":"A train crosses a pole in 12 seconds and a 300 m long platform in 27 seconds. The length of the train is:","options":["300 m","240 m","200 m","360 m"],"answer":1,"explanation":"Speed = L/12 = (L + 300)/27 → 27L = 12L + 3,600 → L = 240 m.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक रेलगाड़ी एक खंभे को 12 सेकंड में और 300 m लंबे प्लेटफ़ॉर्म को 27 सेकंड में पार करती है। रेलगाड़ी की लंबाई है:","optionsHi":["300 m","240 m","200 m","360 m"],"explanationHi":"चाल = L/12 = (L + 300)/27 → 27L = 12L + 3,600 → L = 240 m।","subtopic":"trains"},
  {"id":"quant-tsd-14","question":"A boat takes 5 hours to go 30 km upstream and 3 hours to come back. Its speed in still water is:","options":["10 km/h","2 km/h","6 km/h","8 km/h"],"answer":3,"explanation":"Upstream speed 6 km/h, downstream 10 km/h. Still-water speed = (6 + 10)/2 = 8 km/h; the stream is 2 km/h.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक नाव 30 km धारा के प्रतिकूल जाने में 5 घंटे और वापस आने में 3 घंटे लेती है। स्थिर जल में उसकी चाल है:","optionsHi":["10 km/h","2 km/h","6 km/h","8 km/h"],"explanationHi":"प्रतिकूल चाल 6 km/h, अनुकूल 10 km/h। स्थिर जल में चाल = (6 + 10)/2 = 8 km/h; धारा की चाल 2 km/h है।","subtopic":"boats-streams"},
  {"id":"quant-tsd-15","question":"A thief running at 10 km/h has a 100 m head start when a policeman starts chasing him at 12 km/h. The policeman catches him in:","options":["3 minutes","6 minutes","4 minutes","5 minutes"],"answer":0,"explanation":"Relative speed 2 km/h; gap 0.1 km; time = 0.1/2 h = 0.05 h = 3 minutes.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"10 km/h की चाल से भागते एक चोर को 100 m की बढ़त मिली हुई है, तभी एक पुलिसकर्मी 12 km/h की चाल से उसका पीछा शुरू करता है। पुलिसकर्मी उसे कितने समय में पकड़ लेगा?","optionsHi":["3 मिनट","6 मिनट","4 मिनट","5 मिनट"],"explanationHi":"सापेक्ष चाल 2 km/h; अंतर 0.1 km; समय = 0.1/2 घंटा = 0.05 घंटा = 3 मिनट।","subtopic":"relative-speed"},
  {"id":"quant-tsd-16","question":"A and B run on a circular track of 600 m in the same direction at 6 m/s and 4 m/s from the same point. They first meet again after:","options":["150 s","60 s","120 s","300 s"],"answer":3,"explanation":"Same direction: relative speed 2 m/s; A must gain one full lap of 600 m, taking 300 s. (In opposite directions it would be 600/10 = 60 s.)","difficulty":"hard","source":"SSC CGL · CDS","questionHi":"A और B 600 m की वृत्ताकार पटरी पर एक ही बिंदु से एक ही दिशा में क्रमशः 6 m/s और 4 m/s की चाल से दौड़ते हैं। वे पहली बार फिर कब मिलेंगे?","optionsHi":["150 s","60 s","120 s","300 s"],"explanationHi":"एक ही दिशा में: सापेक्ष चाल 2 m/s; A को 600 m का एक पूरा चक्कर बढ़त बनानी है, जिसमें 300 s लगते हैं। (विपरीत दिशाओं में यह 600/10 = 60 s होता।)","subtopic":"circular-track"},
  {"id":"quant-tsd-17","question":"Two trains, each 120 m long, run at 60 km/h and 48 km/h in the same direction. The faster train takes how long to pass the slower one completely?","options":["72 s","60 s","8 s","36 s"],"answer":0,"explanation":"Relative speed 12 km/h = 10/3 m/s; distance = 240 m; time = 240 ÷ 10/3 = 72 s. 8 s is the opposite-direction answer.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"120 m लंबी दो रेलगाड़ियाँ एक ही दिशा में 60 km/h और 48 km/h की चाल से चल रही हैं। तेज़ रेलगाड़ी को धीमी को पूरी तरह पार करने में कितना समय लगेगा?","optionsHi":["72 s","60 s","8 s","36 s"],"explanationHi":"सापेक्ष चाल 12 km/h = 10/3 m/s; दूरी = 240 m; समय = 240 ÷ 10/3 = 72 s। 8 s विपरीत दिशा का उत्तर है।","subtopic":"trains"},
  {"id":"quant-tsd-18","question":"A man covers 60 km at a uniform speed. Had his speed been 3 km/h more, he would have taken 1 hour less. His speed is:","options":["10 km/h","12 km/h","9 km/h","15 km/h"],"answer":1,"explanation":"60/v − 60/(v + 3) = 1 → 180 = v² + 3v → v² + 3v − 180 = 0 → (v + 15)(v − 12) = 0 → v = 12 km/h.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"एक आदमी एकसमान चाल से 60 km की दूरी तय करता है। यदि उसकी चाल 3 km/h अधिक होती, तो उसे 1 घंटा कम लगता। उसकी चाल है:","optionsHi":["10 km/h","12 km/h","9 km/h","15 km/h"],"explanationHi":"60/v − 60/(v + 3) = 1 → 180 = v² + 3v → v² + 3v − 180 = 0 → (v + 15)(v − 12) = 0 → v = 12 km/h।","subtopic":"late-early"},
  {"id":"quant-tsd-19","question":"A boat goes 15 km upstream and returns to the starting point in 4 hours. If the stream flows at 2 km/h, the speed of the boat in still water is:","options":["10 km/h","7.5 km/h","6 km/h","8 km/h"],"answer":3,"explanation":"15/(b − 2) + 15/(b + 2) = 4 → 30b = 4(b² − 4) → 2b² − 15b − 8 = 0 → (2b + 1)(b − 8) = 0 → b = 8 km/h. Check: 15/6 + 15/10 = 2.5 + 1.5 = 4 h.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक नाव 15 km धारा के प्रतिकूल जाती है और 4 घंटे में प्रारंभिक बिंदु पर लौट आती है। यदि धारा की चाल 2 km/h है, तो स्थिर जल में नाव की चाल है:","optionsHi":["10 km/h","7.5 km/h","6 km/h","8 km/h"],"explanationHi":"15/(b − 2) + 15/(b + 2) = 4 → 30b = 4(b² − 4) → 2b² − 15b − 8 = 0 → (2b + 1)(b − 8) = 0 → b = 8 km/h। जाँच: 15/6 + 15/10 = 2.5 + 1.5 = 4 घंटे।","subtopic":"boats-streams"},
  {"id":"quant-tsd-20","question":"A starts from P towards Q at 8 am at 20 km/h. B starts from Q towards P at 9 am at 30 km/h. If P and Q are 170 km apart, they meet at:","options":["11 am","1 pm","12 noon","11:30 am"],"answer":2,"explanation":"By 9 am A has covered 20 km, leaving 150 km. Closing speed 50 km/h gives 3 more hours, so they meet at 12 noon.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"A सुबह 8 बजे P से Q की ओर 20 km/h की चाल से चलता है। B सुबह 9 बजे Q से P की ओर 30 km/h की चाल से चलता है। यदि P और Q के बीच 170 km की दूरी है, तो वे कब मिलेंगे?","optionsHi":["सुबह 11 बजे","दोपहर 1 बजे","दोपहर 12 बजे","सुबह 11:30 बजे"],"explanationHi":"सुबह 9 बजे तक A 20 km चल चुका होता है, जिससे 150 km शेष रहते हैं। संयुक्त चाल 50 km/h पर 3 घंटे और लगते हैं, इसलिए वे दोपहर 12 बजे मिलते हैं।","subtopic":"relative-speed"},
  {"id":"quant-tsd-21","question":"A 200 m long train passes a man running at 6 km/h in the same direction in 12 seconds. The speed of the train is:","options":["54 km/h","60 km/h","66 km/h","72 km/h"],"answer":2,"explanation":"Relative speed = 200/12 m/s = 50/3 m/s = 60 km/h. Train speed = 60 + 6 = 66 km/h (same direction adds the man's speed back).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"200 m लंबी एक रेलगाड़ी उसी दिशा में 6 km/h की चाल से दौड़ते एक आदमी को 12 सेकंड में पार करती है। रेलगाड़ी की चाल है:","optionsHi":["54 km/h","60 km/h","66 km/h","72 km/h"],"explanationHi":"सापेक्ष चाल = 200/12 m/s = 50/3 m/s = 60 km/h। रेलगाड़ी की चाल = 60 + 6 = 66 km/h (समान दिशा में आदमी की चाल वापस जोड़नी पड़ती है)।","subtopic":"trains"},
  {"id":"quant-tsd-22","question":"How many of the following statements are correct?\n1. For equal distances covered at speeds u and v, the average speed is 2uv/(u + v).\n2. 1 m/s equals 5/18 km/h.\n3. A train crossing a platform travels a distance equal to its own length only.\n4. Downstream speed minus upstream speed equals the speed of the stream.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only 1 is true. 2 is false: 1 m/s = 18/5 = 3.6 km/h (5/18 converts km/h to m/s). 3 is false: the train covers its length plus the platform's. 4 is false: (b + s) − (b − s) = 2s, twice the stream's speed.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. समान दूरियाँ u और v चाल से तय करने पर औसत चाल 2uv/(u + v) होती है।\n2. 1 m/s बराबर है 5/18 km/h के।\n3. प्लेटफ़ॉर्म पार करने में रेलगाड़ी केवल अपनी लंबाई के बराबर दूरी चलती है।\n4. धारा के अनुकूल चाल में से प्रतिकूल चाल घटाने पर धारा की चाल मिलती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल 1 सही है। 2 गलत है: 1 m/s = 18/5 = 3.6 km/h (5/18 km/h को m/s में बदलता है)। 3 गलत है: रेलगाड़ी अपनी लंबाई और प्लेटफ़ॉर्म की लंबाई का योग चलती है। 4 गलत है: (b + s) − (b − s) = 2s, यानी धारा की चाल का दोगुना।","subtopic":"average-speed"},
  {"id":"quant-tsd-23","question":"A car goes from A to B at 60 km/h and returns at 40 km/h, taking 5 hours in all. The distance between A and B is:","options":["240 km","100 km","150 km","120 km"],"answer":3,"explanation":"Average speed = 2 × 60 × 40/100 = 48 km/h; total distance = 48 × 5 = 240 km, so one way = 120 km. Check: 2 h + 3 h = 5 h.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"एक कार A से B तक 60 km/h की चाल से जाती है और 40 km/h की चाल से लौटती है, कुल 5 घंटे लेकर। A और B के बीच की दूरी है:","optionsHi":["240 km","100 km","150 km","120 km"],"explanationHi":"औसत चाल = 2 × 60 × 40/100 = 48 km/h; कुल दूरी = 48 × 5 = 240 km, इसलिए एक ओर की दूरी = 120 km। जाँच: 2 घंटे + 3 घंटे = 5 घंटे।","subtopic":"average-speed"},
  {"id":"quant-tsd-24","question":"A train leaves a station at 60 km/h. Two hours later a second train leaves the same station in the same direction at 90 km/h. The second train overtakes the first at a distance from the station of:","options":["180 km","240 km","300 km","360 km"],"answer":3,"explanation":"Gap after 2 h = 120 km; closing speed 30 km/h; catch-up time 4 h; distance = 90 × 4 = 360 km.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"एक रेलगाड़ी स्टेशन से 60 km/h की चाल से चलती है। दो घंटे बाद दूसरी रेलगाड़ी उसी स्टेशन से उसी दिशा में 90 km/h की चाल से चलती है। दूसरी रेलगाड़ी पहली को स्टेशन से कितनी दूरी पर पकड़ेगी?","optionsHi":["180 km","240 km","300 km","360 km"],"explanationHi":"2 घंटे बाद अंतर = 120 km; संयुक्त चाल 30 km/h; पकड़ने का समय 4 घंटे; दूरी = 90 × 4 = 360 km।","subtopic":"relative-speed"},
  {"id":"quant-tsd-25","question":"Convert 15 m/s into km/h.","options":["4.17 km/h","54 km/h","45 km/h","60 km/h"],"answer":1,"explanation":"Multiply by 18/5: 15 × 18/5 = 54 km/h. 4.17 comes from dividing by 3.6 instead of multiplying.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"15 m/s को km/h में बदलिए।","optionsHi":["4.17 km/h","54 km/h","45 km/h","60 km/h"],"explanationHi":"18/5 से गुणा करें: 15 × 18/5 = 54 km/h। 4.17 गुणा करने के बजाय 3.6 से भाग देने से आता है।","subtopic":"basic-speed"},
  {"id":"quant-tsd-26","question":"A 300 m long train passes a pole in 15 seconds. How long will it take to cross a 450 m long bridge?","options":["37.5 s","22.5 s","30 s","45 s"],"answer":0,"explanation":"Speed = 300/15 = 20 m/s. To cross the bridge it covers 300 + 450 = 750 m: 750/20 = 37.5 s. 22.5 s forgets the train's own length.","difficulty":"moderate","source":"SSC CGL","questionHi":"300 m लंबी एक रेलगाड़ी एक खंभे को 15 सेकंड में पार करती है। वह 450 m लंबे पुल को पार करने में कितना समय लेगी?","optionsHi":["37.5 s","22.5 s","30 s","45 s"],"explanationHi":"चाल = 300/15 = 20 m/s। पुल पार करने के लिए वह 300 + 450 = 750 m चलती है: 750/20 = 37.5 s। 22.5 s रेलगाड़ी की अपनी लंबाई भूल जाता है।","subtopic":"trains"},
  {"id":"quant-tsd-27","question":"A car covers one-third of a distance at 20 km/h and the rest at 40 km/h. What is its average speed for the whole journey?","options":["33⅓ km/h","26⅔ km/h","35 km/h","30 km/h"],"answer":3,"explanation":"Take the distance as 120 km: 40 km at 20 km/h takes 2 h and 80 km at 40 km/h takes 2 h. Average = 120 ÷ 4 = 30 km/h. 33⅓ km/h averages the speeds by distance, which is wrong.","difficulty":"moderate","source":"SSC CGL","questionHi":"एक कार दूरी का एक-तिहाई भाग 20 km/h की चाल से और शेष 40 km/h की चाल से तय करती है। पूरी यात्रा के लिए उसकी औसत चाल क्या है?","optionsHi":["33⅓ km/h","26⅔ km/h","35 km/h","30 km/h"],"explanationHi":"दूरी 120 km मानें: 40 km को 20 km/h पर 2 घंटे लगते हैं और 80 km को 40 km/h पर 2 घंटे। औसत = 120 ÷ 4 = 30 km/h। 33⅓ km/h चालों का दूरी के आधार पर औसत लेना है, जो गलत है।","subtopic":"average-speed"},
  {"id":"quant-tsd-28","question":"Two trains start at the same time towards each other from stations A and B. After meeting, the faster train reaches its destination in 4 hours and the slower in 9 hours. If the faster train runs at 54 km/h, what is the speed of the slower one?","options":["24 km/h","81 km/h","36 km/h","40 km/h"],"answer":2,"explanation":"Speed ratio = √(time of slower after meeting : time of faster) = √(9/4) = 3 : 2. Slower = 54 × 2/3 = 36 km/h. 24 km/h uses 9 : 4 without the square root.","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"दो रेलगाड़ियाँ स्टेशन A और B से एक ही समय एक-दूसरे की ओर चलती हैं। मिलने के बाद तेज़ रेलगाड़ी अपने गंतव्य पर 4 घंटे में और धीमी 9 घंटे में पहुँचती है। यदि तेज़ रेलगाड़ी की चाल 54 km/h है, तो धीमी की चाल क्या है?","optionsHi":["24 km/h","81 km/h","36 km/h","40 km/h"],"explanationHi":"चालों का अनुपात = √(मिलने के बाद धीमी का समय : तेज़ का समय) = √(9/4) = 3 : 2। धीमी = 54 × 2/3 = 36 km/h। 24 km/h वर्गमूल लिए बिना 9 : 4 लेने से आता है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-29","question":"A man rows 40 km downstream in 4 hours and 24 km upstream in 4 hours. How long will he take to row 36 km downstream and come back?","options":["9 hours","9.6 hours","8 hours","10.4 hours"],"answer":1,"explanation":"Downstream speed = 10 km/h, upstream = 6 km/h. Time = 36/10 + 36/6 = 3.6 + 6 = 9.6 hours. 9 hours uses the still-water speed 8 km/h both ways.","difficulty":"hard","source":"SSC CGL","questionHi":"एक आदमी 40 km धारा के अनुकूल 4 घंटे में और 24 km धारा के प्रतिकूल 4 घंटे में नाव चलाता है। वह 36 km धारा के अनुकूल जाने और लौटने में कितना समय लेगा?","optionsHi":["9 घंटे","9.6 घंटे","8 घंटे","10.4 घंटे"],"explanationHi":"अनुकूल चाल = 10 km/h, प्रतिकूल = 6 km/h। समय = 36/10 + 36/6 = 3.6 + 6 = 9.6 घंटे। 9 घंटे दोनों ओर स्थिर जल की चाल 8 km/h लेने से आता है।","subtopic":"boats-streams"},
  {"id":"quant-tsd-30","question":"Walking at 5 km/h a student reaches school 6 minutes late; walking at 6 km/h he is 4 minutes early. How far is the school?","options":["5 km","6 km","4 km","3 km"],"answer":0,"explanation":"Time difference = 10 min = 1/6 h. d/5 − d/6 = d/30 = 1/6 → d = 5 km. 1 km comes from taking 2 minutes as the gap.","difficulty":"hard","source":"SSC CGL","questionHi":"5 km/h की चाल से चलने पर एक विद्यार्थी विद्यालय 6 मिनट देर से पहुँचता है; 6 km/h की चाल से चलने पर वह 4 मिनट पहले पहुँचता है। विद्यालय कितनी दूर है?","optionsHi":["5 km","6 km","4 km","3 km"],"explanationHi":"समय का अंतर = 10 मिनट = 1/6 घंटा। d/5 − d/6 = d/30 = 1/6 → d = 5 km। 1 km अंतर को 2 मिनट लेने से आता है।","subtopic":"late-early"},
  {"id":"quant-tsd-31","question":"A train passes a man standing on a platform in 8 seconds and passes the whole 180 m platform in 20 seconds. What are the train's length and speed?","options":["144 m; 54 km/h","120 m; 45 km/h","96 m; 43.2 km/h","120 m; 54 km/h"],"answer":3,"explanation":"L = 8v and L + 180 = 20v, so 180 = 12v → v = 15 m/s = 54 km/h and L = 8 × 15 = 120 m.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक रेलगाड़ी प्लेटफ़ॉर्म पर खड़े आदमी को 8 सेकंड में और पूरे 180 m लंबे प्लेटफ़ॉर्म को 20 सेकंड में पार करती है। रेलगाड़ी की लंबाई और चाल क्या हैं?","optionsHi":["144 m; 54 km/h","120 m; 45 km/h","96 m; 43.2 km/h","120 m; 54 km/h"],"explanationHi":"L = 8v और L + 180 = 20v, इसलिए 180 = 12v → v = 15 m/s = 54 km/h और L = 8 × 15 = 120 m।","subtopic":"trains"},
  {"id":"quant-tsd-32","question":"A and B start together from the same point on a 1.2 km circular track and run in opposite directions at 15 km/h and 21 km/h. After how long do they first meet, and after how long do they first meet at the starting point?","options":["2 min; 12 min","4.8 min; 24 min","2 min; 24 min","3 min; 24 min"],"answer":2,"explanation":"Opposite directions: relative speed 36 km/h, so first meeting after 1.2/36 h = 2 min. Lap times: A 1.2/15 h = 24/5 min, B 1.2/21 h = 24/7 min. LCM = LCM(24, 24)/HCF(5, 7) = 24 min at the start.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"A और B एक 1.2 km की वृत्ताकार पटरी पर एक ही बिंदु से एक साथ विपरीत दिशाओं में क्रमशः 15 km/h और 21 km/h की चाल से दौड़ना शुरू करते हैं। वे पहली बार कितने समय बाद मिलते हैं, और प्रारंभिक बिंदु पर पहली बार कितने समय बाद मिलते हैं?","optionsHi":["2 मिनट; 12 मिनट","4.8 मिनट; 24 मिनट","2 मिनट; 24 मिनट","3 मिनट; 24 मिनट"],"explanationHi":"विपरीत दिशाओं में: सापेक्ष चाल 36 km/h, इसलिए पहली बार मिलने में 1.2/36 घंटा = 2 मिनट लगते हैं। चक्कर के समय: A का 1.2/15 घंटा = 24/5 मिनट, B का 1.2/21 घंटा = 24/7 मिनट। लघुत्तम समापवर्त्य = LCM(24, 24)/HCF(5, 7) = प्रारंभिक बिंदु पर 24 मिनट।","subtopic":"circular-track"},
  {"id":"quant-tsd-33","question":"A thief steals a car at 1:30 pm and drives away at 40 km/h. The theft is discovered at 2:00 pm and the owner chases him at 50 km/h from the same place. When does he catch the thief?","options":["3:30 pm","4:00 pm","4:30 pm","3:00 pm"],"answer":1,"explanation":"In 30 minutes the thief is 20 km ahead. Relative speed = 10 km/h, so catching up takes 2 hours: 2:00 pm + 2 h = 4:00 pm.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक चोर दोपहर 1:30 बजे एक कार चुराकर 40 km/h की चाल से भाग जाता है। चोरी का पता दोपहर 2:00 बजे चलता है और मालिक उसी स्थान से 50 km/h की चाल से उसका पीछा करता है। वह चोर को कब पकड़ेगा?","optionsHi":["दोपहर 3:30 बजे","दोपहर 4:00 बजे","दोपहर 4:30 बजे","दोपहर 3:00 बजे"],"explanationHi":"30 मिनट में चोर 20 km आगे निकल चुका होता है। सापेक्ष चाल = 10 km/h, इसलिए पकड़ने में 2 घंटे लगते हैं: दोपहर 2:00 बजे + 2 घंटे = दोपहर 4:00 बजे।","subtopic":"relative-speed"},
  {"id":"quant-tsd-34","question":"Two trains 140 m and 160 m long run on parallel tracks. Going the same way, the faster passes the slower in 30 seconds; going opposite ways, they cross in 10 seconds. What are their speeds?","options":["72 km/h and 36 km/h","60 km/h and 30 km/h","20 km/h and 10 km/h","90 km/h and 54 km/h"],"answer":0,"explanation":"Total length 300 m. Difference of speeds = 300/30 = 10 m/s; sum = 300/10 = 30 m/s. So 20 m/s and 10 m/s = 72 km/h and 36 km/h. '20 and 10 km/h' forgets to convert from m/s.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"140 m और 160 m लंबी दो रेलगाड़ियाँ समानांतर पटरियों पर चल रही हैं। एक ही दिशा में जाने पर तेज़ वाली धीमी को 30 सेकंड में पार करती है; विपरीत दिशाओं में जाने पर वे 10 सेकंड में एक-दूसरे को पार करती हैं। उनकी चाल क्या हैं?","optionsHi":["72 km/h और 36 km/h","60 km/h और 30 km/h","20 km/h और 10 km/h","90 km/h और 54 km/h"],"explanationHi":"कुल लंबाई 300 m। चालों का अंतर = 300/30 = 10 m/s; योग = 300/10 = 30 m/s। इसलिए 20 m/s और 10 m/s = 72 km/h और 36 km/h। '20 और 10 km/h' m/s से बदलना भूल जाना है।","subtopic":"trains"},
  {"id":"quant-tsd-35","question":"A cyclist covers 9 km in 45 minutes. What is his speed in km/h?","options":["10 km/h","12 km/h","15 km/h","11.25 km/h"],"answer":1,"explanation":"45 minutes = 3/4 hour, so speed = 9 ÷ 3/4 = 12 km/h. 11.25 km/h divides by 0.8 hour (48 minutes), and 15 km/h treats 45 minutes as 0.6 hour.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"एक साइकिल सवार 45 मिनट में 9 km की दूरी तय करता है। उसकी चाल km/h में कितनी है?","optionsHi":["10 km/h","12 km/h","15 km/h","11.25 km/h"],"explanationHi":"45 मिनट = 3/4 घंटा, इसलिए चाल = 9 ÷ 3/4 = 12 km/h। 11.25 km/h 0.8 घंटे (48 मिनट) से भाग देना है, और 15 km/h 45 मिनट को 0.6 घंटा मान लेना है।","subtopic":"basic-speed"},
  {"id":"quant-tsd-36","question":"How far does a car travel in 2 hours 15 minutes at 48 km/h?","options":["96 km","112 km","108 km","103.2 km"],"answer":2,"explanation":"2 h 15 min = 2.25 h, so distance = 48 × 2.25 = 108 km. Reading 2 h 15 min as 2.15 h gives 103.2 km.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"48 km/h की चाल से एक कार 2 घंटे 15 मिनट में कितनी दूरी तय करती है?","optionsHi":["96 km","112 km","108 km","103.2 km"],"explanationHi":"2 घंटे 15 मिनट = 2.25 घंटे, इसलिए दूरी = 48 × 2.25 = 108 km। 2 घंटे 15 मिनट को 2.15 घंटे पढ़ने पर 103.2 km आता है।","subtopic":"basic-speed"},
  {"id":"quant-tsd-37","question":"Two cars take times in the ratio 3 : 4 to cover the same distance. What is the ratio of their speeds?","options":["4 : 3","3 : 4","16 : 9","9 : 16"],"answer":0,"explanation":"For a fixed distance, speed is inversely proportional to time, so the speeds are 4 : 3.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"दो कारें समान दूरी तय करने में 3 : 4 के अनुपात में समय लेती हैं। उनकी चालों का अनुपात क्या है?","optionsHi":["4 : 3","3 : 4","16 : 9","9 : 16"],"explanationHi":"निश्चित दूरी के लिए चाल समय के व्युत्क्रमानुपाती होती है, इसलिए चालें 4 : 3 हैं।","subtopic":"basic-speed"},
  {"id":"quant-tsd-38","question":"Two cyclists start from the same point at the same time and ride in opposite directions at 12 km/h and 18 km/h. How far apart are they after 2 hours 20 minutes?","options":["14 km","66 km","70 km","60 km"],"answer":2,"explanation":"They separate at 12 + 18 = 30 km/h; in 7/3 hours that is 70 km. 14 km uses the difference of speeds, which applies to the same direction.","difficulty":"moderate","source":"RRB NTPC · SSC CGL","questionHi":"दो साइकिल सवार एक ही बिंदु से एक ही समय विपरीत दिशाओं में 12 km/h और 18 km/h की चाल से चलना शुरू करते हैं। 2 घंटे 20 मिनट बाद वे एक-दूसरे से कितनी दूर होंगे?","optionsHi":["14 km","66 km","70 km","60 km"],"explanationHi":"वे 12 + 18 = 30 km/h की चाल से दूर होते हैं; 7/3 घंटे में यह 70 km है। 14 km चालों का अंतर लेता है, जो एक ही दिशा के लिए होता है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-39","question":"A 360 m long train passes a man walking at 6 km/h in the opposite direction in 18 seconds. What is the speed of the train?","options":["78 km/h","60 km/h","66 km/h","72 km/h"],"answer":2,"explanation":"Relative speed = 360/18 = 20 m/s = 72 km/h. In opposite directions this is train + man, so the train runs at 72 − 6 = 66 km/h.","difficulty":"moderate","source":"RRB NTPC · SSC CGL","questionHi":"360 m लंबी एक रेलगाड़ी विपरीत दिशा में 6 km/h की चाल से चलते एक आदमी को 18 सेकंड में पार करती है। रेलगाड़ी की चाल क्या है?","optionsHi":["78 km/h","60 km/h","66 km/h","72 km/h"],"explanationHi":"सापेक्ष चाल = 360/18 = 20 m/s = 72 km/h। विपरीत दिशाओं में यह रेलगाड़ी + आदमी की चाल है, इसलिए रेलगाड़ी की चाल 72 − 6 = 66 km/h है।","subtopic":"trains"},
  {"id":"quant-tsd-40","question":"By increasing his speed by 25%, a man reaches his office 12 minutes earlier than usual. What is his usual time?","options":["50 minutes","60 minutes","75 minutes","48 minutes"],"answer":1,"explanation":"Speed × 5/4 means time × 4/5, so he saves 1/5 of the usual time: usual time = 12 × 5 = 60 minutes.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"अपनी चाल 25% बढ़ाने पर एक आदमी कार्यालय सामान्य से 12 मिनट पहले पहुँचता है। उसका सामान्य समय क्या है?","optionsHi":["50 मिनट","60 मिनट","75 मिनट","48 मिनट"],"explanationHi":"चाल × 5/4 का अर्थ है समय × 4/5, इसलिए वह सामान्य समय का 1/5 भाग बचाता है: सामान्य समय = 12 × 5 = 60 मिनट।","subtopic":"late-early"},
  {"id":"quant-tsd-41","question":"A boat goes 30 km downstream in 2 hours. Its speed in still water is 12 km/h. How long will it take to return upstream?","options":["3 h 20 min","2 h 30 min","3 h","4 h"],"answer":0,"explanation":"Downstream speed = 15 km/h, so the stream = 3 km/h and upstream speed = 9 km/h. Time = 30/9 = 3 1/3 h = 3 h 20 min.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक नाव 30 km धारा के अनुकूल 2 घंटे में जाती है। स्थिर जल में उसकी चाल 12 km/h है। धारा के प्रतिकूल लौटने में उसे कितना समय लगेगा?","optionsHi":["3 घंटे 20 मिनट","2 घंटे 30 मिनट","3 घंटे","4 घंटे"],"explanationHi":"अनुकूल चाल = 15 km/h, इसलिए धारा = 3 km/h और प्रतिकूल चाल = 9 km/h। समय = 30/9 = 3 1/3 घंटे = 3 घंटे 20 मिनट।","subtopic":"boats-streams"},
  {"id":"quant-tsd-42","question":"A car travels at 50 km/h for 3 hours and then at 70 km/h for 2 hours. What is its average speed for the whole journey?","options":["58.33 km/h","58 km/h","60 km/h","56 km/h"],"answer":1,"explanation":"Distance = 150 + 140 = 290 km in 5 hours, so the average = 58 km/h. 60 km/h is the simple average of the speeds, valid only for equal times.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक कार 3 घंटे तक 50 km/h की चाल से और फिर 2 घंटे तक 70 km/h की चाल से चलती है। पूरी यात्रा की औसत चाल क्या है?","optionsHi":["58.33 km/h","58 km/h","60 km/h","56 km/h"],"explanationHi":"दूरी = 150 + 140 = 290 km, 5 घंटे में, इसलिए औसत = 58 km/h। 60 km/h चालों का साधारण औसत है, जो केवल समान समयों के लिए मान्य है।","subtopic":"average-speed"},
  {"id":"quant-tsd-43","question":"Two trains, each 150 m long, take 10 seconds and 15 seconds respectively to pass a pole. How long will they take to cross each other when running in opposite directions?","options":["12.5 seconds","12 seconds","25 seconds","6 seconds"],"answer":1,"explanation":"Speeds are 15 m/s and 10 m/s. Crossing in opposite directions: total length 300 m at relative speed 25 m/s takes 12 seconds.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"150 m लंबी दो रेलगाड़ियाँ एक खंभे को क्रमशः 10 सेकंड और 15 सेकंड में पार करती हैं। विपरीत दिशाओं में चलते हुए वे एक-दूसरे को कितने समय में पार करेंगी?","optionsHi":["12.5 सेकंड","12 सेकंड","25 सेकंड","6 सेकंड"],"explanationHi":"चालें 15 m/s और 10 m/s हैं। विपरीत दिशाओं में पार करना: कुल लंबाई 300 m, सापेक्ष चाल 25 m/s, इसलिए 12 सेकंड।","subtopic":"trains"},
  {"id":"quant-tsd-44","question":"A train crosses a 150 m long platform in 15 seconds and a 250 m long platform in 20 seconds. What is the length of the train?","options":["150 m","250 m","200 m","100 m"],"answer":0,"explanation":"The extra 100 m of platform takes 5 more seconds, so speed = 20 m/s. In 15 s the train covers 300 m = L + 150, so L = 150 m.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक रेलगाड़ी 150 m लंबे प्लेटफ़ॉर्म को 15 सेकंड में और 250 m लंबे प्लेटफ़ॉर्म को 20 सेकंड में पार करती है। रेलगाड़ी की लंबाई क्या है?","optionsHi":["150 m","250 m","200 m","100 m"],"explanationHi":"प्लेटफ़ॉर्म की अतिरिक्त 100 m लंबाई में 5 सेकंड अधिक लगते हैं, इसलिए चाल = 20 m/s। 15 s में रेलगाड़ी 300 m = L + 150 चलती है, इसलिए L = 150 m।","subtopic":"trains"},
  {"id":"quant-tsd-45","question":"A runs 1½ times as fast as B. If A gives B a start of 30 m, they reach the winning post together. How long is the race?","options":["120 m","90 m","45 m","60 m"],"answer":1,"explanation":"In the same time A runs L and B runs L − 30, so L/(L − 30) = 3/2, giving L = 90 m.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"A, B से 1½ गुना तेज़ दौड़ता है। यदि A, B को 30 m की बढ़त दे, तो वे दोनों एक साथ विजय-स्तंभ पर पहुँचते हैं। दौड़ कितनी लंबी है?","optionsHi":["120 m","90 m","45 m","60 m"],"explanationHi":"उतने ही समय में A, L दौड़ता है और B, L − 30 दौड़ता है, इसलिए L/(L − 30) = 3/2, जिससे L = 90 m।","subtopic":"circular-track"},
  {"id":"quant-tsd-46","question":"In a 1 km race, A beats B by 40 m or by 8 seconds. How long does A take to run the race?","options":["192 seconds","208 seconds","180 seconds","200 seconds"],"answer":0,"explanation":"B covers the last 40 m in 8 s, so B runs 5 m/s and takes 200 s for 1,000 m. A finishes 8 s earlier, in 192 seconds.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"1 km की दौड़ में A, B को 40 m से या 8 सेकंड से हराता है। A दौड़ पूरी करने में कितना समय लेता है?","optionsHi":["192 सेकंड","208 सेकंड","180 सेकंड","200 सेकंड"],"explanationHi":"B अंतिम 40 m 8 s में तय करता है, इसलिए B की चाल 5 m/s है और 1,000 m में 200 s लगते हैं। A 8 s पहले, यानी 192 सेकंड में पहुँचता है।","subtopic":"circular-track"},
  {"id":"quant-tsd-47","question":"A boat takes twice as long to go a certain distance upstream as to cover the same distance downstream. What is the ratio of the boat's speed in still water to the speed of the stream?","options":["3 : 2","1 : 3","3 : 1","2 : 1"],"answer":2,"explanation":"Downstream speed is twice the upstream speed: b + s = 2(b − s), so b = 3s and the ratio is 3 : 1.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक नाव को किसी निश्चित दूरी को धारा के प्रतिकूल जाने में उतनी ही दूरी धारा के अनुकूल जाने से दोगुना समय लगता है। स्थिर जल में नाव की चाल और धारा की चाल का अनुपात क्या है?","optionsHi":["3 : 2","1 : 3","3 : 1","2 : 1"],"explanationHi":"अनुकूल चाल प्रतिकूल चाल की दोगुनी है: b + s = 2(b − s), इसलिए b = 3s और अनुपात 3 : 1 है।","subtopic":"boats-streams"},
  {"id":"quant-tsd-48","question":"A train overtakes two people walking in the same direction as the train at 2 km/h and 4 km/h in 9 seconds and 10 seconds respectively. What is the length of the train?","options":["60 m","72 m","45 m","50 m"],"answer":3,"explanation":"9(v − 2) = 10(v − 4) gives v = 22 km/h. Length = (22 − 2) km/h × 9 s = 20 × 5/18 × 9 = 50 m.","difficulty":"hard","source":"SSC CGL Tier 2 · CDS","questionHi":"एक रेलगाड़ी अपनी ही दिशा में 2 km/h और 4 km/h की चाल से चलते दो व्यक्तियों को क्रमशः 9 सेकंड और 10 सेकंड में पार करती है। रेलगाड़ी की लंबाई क्या है?","optionsHi":["60 m","72 m","45 m","50 m"],"explanationHi":"9(v − 2) = 10(v − 4) से v = 22 km/h। लंबाई = (22 − 2) km/h × 9 s = 20 × 5/18 × 9 = 50 m।","subtopic":"trains"},
  {"id":"quant-tsd-49","question":"A car covers four successive 3 km stretches at 10 km/h, 20 km/h, 30 km/h and 60 km/h. What is its average speed over the 12 km?","options":["25 km/h","24 km/h","30 km/h","20 km/h"],"answer":3,"explanation":"Time = 3/10 + 3/20 + 3/30 + 3/60 = 0.3 + 0.15 + 0.1 + 0.05 = 0.6 h, so the average = 12/0.6 = 20 km/h. 30 km/h is the simple average of the speeds.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक कार लगातार चार 3 km के खंड क्रमशः 10 km/h, 20 km/h, 30 km/h और 60 km/h की चाल से तय करती है। 12 km में उसकी औसत चाल क्या है?","optionsHi":["25 km/h","24 km/h","30 km/h","20 km/h"],"explanationHi":"समय = 3/10 + 3/20 + 3/30 + 3/60 = 0.3 + 0.15 + 0.1 + 0.05 = 0.6 घंटा, इसलिए औसत = 12/0.6 = 20 km/h। 30 km/h चालों का साधारण औसत है।","subtopic":"average-speed"},
  {"id":"quant-tsd-50","question":"A, B and C start together from the same point on a 1.2 km circular track and run in the same direction at 4 km/h, 6 km/h and 8 km/h. After how many minutes will they all be together at the starting point for the first time?","options":["24 minutes","36 minutes","18 minutes","72 minutes"],"answer":1,"explanation":"Their lap times are 1.2/4 = 0.3 h = 18 min, 12 min and 9 min. LCM(18, 12, 9) = 36 minutes.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"A, B और C एक 1.2 km की वृत्ताकार पटरी पर एक ही बिंदु से एक साथ एक ही दिशा में क्रमशः 4 km/h, 6 km/h और 8 km/h की चाल से दौड़ना शुरू करते हैं। कितने मिनट बाद वे तीनों पहली बार प्रारंभिक बिंदु पर एक साथ होंगे?","optionsHi":["24 मिनट","36 मिनट","18 मिनट","72 मिनट"],"explanationHi":"उनके चक्कर के समय 1.2/4 = 0.3 घंटा = 18 मिनट, 12 मिनट और 9 मिनट हैं। LCM(18, 12, 9) = 36 मिनट।","subtopic":"circular-track"},
  {"id":"quant-tsd-51","question":"A boat covers 48 km upstream and 72 km downstream in 12 hours, and 72 km upstream and 48 km downstream in 13 hours. What is the speed of the stream?","options":["3 km/h","1.5 km/h","4 km/h","2 km/h"],"answer":3,"explanation":"Let u = 1/upstream speed, v = 1/downstream speed: 48u + 72v = 12 and 72u + 48v = 13. Adding gives u + v = 5/24, subtracting gives u − v = 1/24, so upstream = 8 and downstream = 12 km/h. Stream = (12 − 8)/2 = 2 km/h.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक नाव 48 km धारा के प्रतिकूल और 72 km धारा के अनुकूल 12 घंटे में, तथा 72 km प्रतिकूल और 48 km अनुकूल 13 घंटे में तय करती है। धारा की चाल क्या है?","optionsHi":["3 km/h","1.5 km/h","4 km/h","2 km/h"],"explanationHi":"मान लें u = 1/प्रतिकूल चाल, v = 1/अनुकूल चाल: 48u + 72v = 12 और 72u + 48v = 13। जोड़ने पर u + v = 5/24, घटाने पर u − v = 1/24, इसलिए प्रतिकूल = 8 और अनुकूल = 12 km/h। धारा = (12 − 8)/2 = 2 km/h।","subtopic":"boats-streams"},
  {"id":"quant-tsd-52","question":"A man takes 60 seconds to be carried up a moving escalator standing still, and 40 seconds to walk up it when it is not moving. How long will he take to walk up the escalator while it is moving?","options":["24 seconds","30 seconds","50 seconds","20 seconds"],"answer":0,"explanation":"Per second he covers 1/40 of it by walking and 1/60 by the escalator, together 1/24, so he takes 24 seconds. 50 s is the average of the two times.","difficulty":"hard","source":"SSC CGL Tier 2 · CDS","questionHi":"एक आदमी चलती हुई एस्केलेटर पर स्थिर खड़े रहने पर 60 सेकंड में ऊपर पहुँचता है, और एस्केलेटर बंद होने पर चलकर 40 सेकंड में ऊपर पहुँचता है। एस्केलेटर चलते रहने पर उस पर चलकर ऊपर पहुँचने में उसे कितना समय लगेगा?","optionsHi":["24 सेकंड","30 सेकंड","50 सेकंड","20 सेकंड"],"explanationHi":"प्रति सेकंड वह चलकर उसका 1/40 भाग और एस्केलेटर से 1/60 भाग तय करता है, कुल 1/24, इसलिए उसे 24 सेकंड लगते हैं। 50 s दोनों समयों का औसत है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-53","question":"How many of the following statements are correct?\n1. 1 km/h = 5/18 m/s.\n2. For equal times spent at speeds u and v, the average speed is (u + v)/2.\n3. A train passing a pole covers a distance equal to its own length.\n4. If a boat's upstream speed is u and downstream speed is d, the stream's speed is (d + u)/2.","options":["Only two","Only one","Only three","All four"],"answer":2,"explanation":"1, 2 and 3 are true. 4 is false: (d + u)/2 is the boat's speed in still water; the stream's speed is (d − u)/2.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. 1 km/h = 5/18 m/s।\n2. u और v चाल पर समान समय बिताने पर औसत चाल (u + v)/2 होती है।\n3. खंभे को पार करती रेलगाड़ी अपनी लंबाई के बराबर दूरी तय करती है।\n4. यदि नाव की धारा के प्रतिकूल चाल u और अनुकूल चाल d हो, तो धारा की चाल (d + u)/2 होती है।","optionsHi":["केवल दो","केवल एक","केवल तीन","सभी चार"],"explanationHi":"1, 2 और 3 सही हैं। 4 गलत है: (d + u)/2 स्थिर जल में नाव की चाल है; धारा की चाल (d − u)/2 है।","subtopic":"basic-speed"},
  {"id":"quant-tsd-54","question":"Two trains start at the same time from stations A and B, 360 km apart, towards each other, and meet after 3 hours. The faster train completes its journey 2 hours 30 minutes before the slower one. What is the speed of the faster train?","options":["80 km/h","75 km/h","72 km/h","60 km/h"],"answer":2,"explanation":"Sum of speeds = 360/3 = 120 km/h. With speeds 72 and 48, the journey times are 5 h and 7.5 h, a difference of 2.5 h. (From 360/(120 − x) − 360/x = 2.5, x² + 168x − 17,280 = 0 gives x = 72.)","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"दो रेलगाड़ियाँ स्टेशन A और B से, जो 360 km दूर हैं, एक ही समय एक-दूसरे की ओर चलती हैं और 3 घंटे बाद मिलती हैं। तेज़ रेलगाड़ी अपनी यात्रा धीमी से 2 घंटे 30 मिनट पहले पूरी करती है। तेज़ रेलगाड़ी की चाल क्या है?","optionsHi":["80 km/h","75 km/h","72 km/h","60 km/h"],"explanationHi":"चालों का योग = 360/3 = 120 km/h। चाल 72 और 48 होने पर यात्रा के समय 5 घंटे और 7.5 घंटे हैं, अंतर 2.5 घंटे। (360/(120 − x) − 360/x = 2.5 से x² + 168x − 17,280 = 0 और x = 72।)","subtopic":"relative-speed"},
  {"id":"quant-tsd-55","question":"In a 500 m race A beats B by 50 m, and in a 500 m race B beats C by 25 m. By how many metres will A beat C in a 500 m race?","options":["70 m","75 m","77.5 m","72.5 m"],"answer":3,"explanation":"When A runs 500, B runs 450; when B runs 500, C runs 475, so when B runs 450, C runs 450 × 0.95 = 427.5. A beats C by 72.5 m. Adding 50 + 25 = 75 is the trap.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"500 m की दौड़ में A, B को 50 m से हराता है, और 500 m की दौड़ में B, C को 25 m से हराता है। 500 m की दौड़ में A, C को कितने मीटर से हराएगा?","optionsHi":["70 m","75 m","77.5 m","72.5 m"],"explanationHi":"जब A 500 दौड़ता है, B 450 दौड़ता है; जब B 500 दौड़ता है, C 475 दौड़ता है, इसलिए जब B 450 दौड़ता है, C 450 × 0.95 = 427.5 दौड़ता है। A, C को 72.5 m से हराता है। 50 + 25 = 75 जोड़ना जाल है।","subtopic":"circular-track"},
  {"id":"quant-tsd-56","question":"A man rows to a place 48 km away and back in 14 hours. He finds that he can row 4 km with the stream in the same time as 3 km against it. What is the speed of the stream?","options":["1.5 km/h","0.5 km/h","2 km/h","1 km/h"],"answer":3,"explanation":"Downstream : upstream speed = 4 : 3, say 4k and 3k. 48/(4k) + 48/(3k) = 28/k = 14, so k = 2: speeds 8 and 6 km/h. Stream = (8 − 6)/2 = 1 km/h.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक आदमी 48 km दूर किसी स्थान तक नाव चलाकर जाता है और वापस 14 घंटे में आता है। वह पाता है कि धारा के अनुकूल 4 km नाव चलाने में उतना ही समय लगता है जितना धारा के प्रतिकूल 3 km में। धारा की चाल क्या है?","optionsHi":["1.5 km/h","0.5 km/h","2 km/h","1 km/h"],"explanationHi":"अनुकूल : प्रतिकूल चाल = 4 : 3, मान लें 4k और 3k। 48/(4k) + 48/(3k) = 28/k = 14, इसलिए k = 2: चालें 8 और 6 km/h। धारा = (8 − 6)/2 = 1 km/h।","subtopic":"boats-streams"},
  {"id":"quant-tsd-57","question":"One hour after starting, a train has a breakdown and continues at 3/4 of its former speed, arriving 1.5 hours late. Had the breakdown occurred 60 km further on, it would have arrived only 1 hour late. What is the length of the journey?","options":["240 km","220 km","200 km","180 km"],"answer":1,"explanation":"At 3/4 speed, a stretch x takes x/(3v) extra time. So (D − v)/(3v) = 1.5 and (D − v − 60)/(3v) = 1. Subtracting: 60/(3v) = 0.5, so v = 40 km/h and D − 40 = 180, D = 220 km.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"चलना शुरू करने के एक घंटे बाद एक रेलगाड़ी खराब हो जाती है और अपनी पहले की चाल की 3/4 चाल से चलती है, जिससे वह 1.5 घंटे देर से पहुँचती है। यदि खराबी 60 km और आगे आती, तो वह केवल 1 घंटा देर से पहुँचती। यात्रा की लंबाई कितनी है?","optionsHi":["240 km","220 km","200 km","180 km"],"explanationHi":"3/4 चाल पर किसी खंड x में x/(3v) अतिरिक्त समय लगता है। इसलिए (D − v)/(3v) = 1.5 और (D − v − 60)/(3v) = 1। घटाने पर: 60/(3v) = 0.5, इसलिए v = 40 km/h और D − 40 = 180, D = 220 km।","subtopic":"late-early"},
  {"id":"quant-tsd-58","question":"A and B run round a circular track in opposite directions, starting together from the same point, with speeds in the ratio 3 : 2. At how many distinct points on the track will they meet?","options":["1","6","3","5"],"answer":3,"explanation":"In opposite directions the number of distinct meeting points is the sum of the ratio terms in lowest form, 3 + 2 = 5. (In the same direction it would be 3 − 2 = 1.)","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"A और B एक वृत्ताकार पटरी पर एक ही बिंदु से एक साथ विपरीत दिशाओं में चलना शुरू करते हैं, और उनकी चालों का अनुपात 3 : 2 है। वे पटरी पर कितने भिन्न बिंदुओं पर मिलेंगे?","optionsHi":["1","6","3","5"],"explanationHi":"विपरीत दिशाओं में भिन्न मिलन-बिंदुओं की संख्या अनुपात के सरलतम रूप के पदों का योग होती है, 3 + 2 = 5। (एक ही दिशा में यह 3 − 2 = 1 होती।)","subtopic":"circular-track"},
  {"id":"quant-tsd-59","question":"Assertion (A): Two trains, each 100 m long, running in the same direction at 50 km/h and 40 km/h, take 72 seconds to pass each other completely.\nReason (R): For bodies moving in the same direction, the relative speed is the difference of their speeds.","options":["Both A and R are true, and R is the correct explanation of A","A is false but R is true","Both A and R are true, but R is not the correct explanation of A","A is true but R is false"],"answer":0,"explanation":"Relative speed = 10 km/h = 25/9 m/s and the distance is 200 m, so the time is 200 × 9/25 = 72 s. A is computed exactly by using R.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"अभिकथन (A): 100 m लंबी दो रेलगाड़ियाँ, जो एक ही दिशा में 50 km/h और 40 km/h की चाल से चल रही हैं, एक-दूसरे को पूरी तरह पार करने में 72 सेकंड लेती हैं।\nकारण (R): एक ही दिशा में गतिमान पिंडों की सापेक्ष चाल उनकी चालों का अंतर होती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A असत्य है लेकिन R सत्य है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है लेकिन R असत्य है"],"explanationHi":"सापेक्ष चाल = 10 km/h = 25/9 m/s और दूरी 200 m है, इसलिए समय 200 × 9/25 = 72 s है। A की गणना ठीक R के प्रयोग से होती है।","subtopic":"trains"},
  {"id":"quant-tsd-60","question":"A man covers 34 km in 4 hours, partly on foot at 5 km/h and the rest by cycle at 15 km/h. How far does he cycle?","options":["24 km","13 km","17 km","21 km"],"answer":3,"explanation":"w + c = 34 and w/5 + c/15 = 4, i.e. 3w + c = 60. Subtracting, 2w = 26, so w = 13 km and c = 21 km.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"एक आदमी 4 घंटे में 34 km की दूरी तय करता है, कुछ पैदल 5 km/h की चाल से और शेष साइकिल से 15 km/h की चाल से। वह साइकिल से कितनी दूरी तय करता है?","optionsHi":["24 km","13 km","17 km","21 km"],"explanationHi":"w + c = 34 और w/5 + c/15 = 4, यानी 3w + c = 60। घटाने पर 2w = 26, इसलिए w = 13 km और c = 21 km।","subtopic":"basic-speed"},
  {"id":"quant-tsd-61","question":"Buses leave a depot at regular intervals in both directions along a road and all run at the same speed. A man walking along the road meets an oncoming bus every 10 minutes and is overtaken by a bus every 15 minutes. At what interval do the buses leave the depot?","options":["12 minutes","12.5 minutes","10 minutes","15 minutes"],"answer":0,"explanation":"Let the gap between buses be d. d/(b + w) = 10 and d/(b − w) = 15, so 2b = d/10 + d/15 = d/6 and b = d/12. The buses are 12 minutes apart (the harmonic mean of 10 and 15). 12.5 is the simple average.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"एक डिपो से बसें सड़क पर दोनों दिशाओं में नियमित अंतराल पर निकलती हैं और सभी की चाल समान है। सड़क पर चलता एक आदमी हर 10 मिनट में सामने से आती एक बस से मिलता है और हर 15 मिनट में एक बस उसे पीछे से पार करती है। डिपो से बसें कितने अंतराल पर निकलती हैं?","optionsHi":["12 मिनट","12.5 मिनट","10 मिनट","15 मिनट"],"explanationHi":"मान लें बसों के बीच की दूरी d है। d/(b + w) = 10 और d/(b − w) = 15, इसलिए 2b = d/10 + d/15 = d/6 और b = d/12। बसें 12 मिनट के अंतर पर हैं (10 और 15 का हरात्मक माध्य)। 12.5 साधारण औसत है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-62","question":"A train running at 54 km/h passes a motorcyclist coming from the opposite direction at 18 km/h in 9 seconds. At the same speed, it crosses a platform in 30 seconds. How long is the platform?","options":["300 m","180 m","270 m","330 m"],"answer":2,"explanation":"Relative speed = 72 km/h = 20 m/s, so the train is 20 × 9 = 180 m long. At 15 m/s it covers 450 m in 30 s, so the platform is 450 − 180 = 270 m.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"54 km/h की चाल से चलती एक रेलगाड़ी विपरीत दिशा से 18 km/h की चाल से आते एक मोटरसाइकिल सवार को 9 सेकंड में पार करती है। उसी चाल से वह एक प्लेटफ़ॉर्म को 30 सेकंड में पार करती है। प्लेटफ़ॉर्म कितना लंबा है?","optionsHi":["300 m","180 m","270 m","330 m"],"explanationHi":"सापेक्ष चाल = 72 km/h = 20 m/s, इसलिए रेलगाड़ी की लंबाई 20 × 9 = 180 m है। 15 m/s पर वह 30 s में 450 m चलती है, इसलिए प्लेटफ़ॉर्म = 450 − 180 = 270 m।","subtopic":"trains"},
  {"id":"quant-tsd-63","question":"Car X leaves P for Q, 300 km away, at 9 am. Car Y leaves Q for P at 10 am. They meet at 1 pm at a point 180 km from P. What is Y's speed?","options":["30 km/h","40 km/h","45 km/h","60 km/h"],"answer":1,"explanation":"Y has covered 300 − 180 = 120 km between 10 am and 1 pm, i.e. in 3 hours, so its speed is 40 km/h. Dividing by 4 hours (30 km/h) uses X's travel time.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"कार X सुबह 9 बजे P से Q के लिए चलती है, जो 300 km दूर है। कार Y सुबह 10 बजे Q से P के लिए चलती है। वे दोपहर 1 बजे P से 180 km दूर एक बिंदु पर मिलती हैं। Y की चाल क्या है?","optionsHi":["30 km/h","40 km/h","45 km/h","60 km/h"],"explanationHi":"सुबह 10 बजे से दोपहर 1 बजे के बीच, यानी 3 घंटे में, Y 300 − 180 = 120 km चली है, इसलिए उसकी चाल 40 km/h है। 4 घंटे से भाग देना (30 km/h) X का यात्रा-समय लेना है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-64","question":"Walking at 4/5 of his usual speed, a man is 15 minutes late. How early will he be if he walks at 5/4 of his usual speed?","options":["12 minutes","10 minutes","18.75 minutes","15 minutes"],"answer":0,"explanation":"At 4/5 speed the time is 5/4 of usual, so the extra 1/4 = 15 minutes and the usual time is 60 minutes. At 5/4 speed he takes 48 minutes, i.e. 12 minutes early.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"अपनी सामान्य चाल की 4/5 चाल से चलने पर एक आदमी 15 मिनट देर हो जाता है। यदि वह अपनी सामान्य चाल की 5/4 चाल से चले, तो वह कितना जल्दी पहुँचेगा?","optionsHi":["12 मिनट","10 मिनट","18.75 मिनट","15 मिनट"],"explanationHi":"4/5 चाल पर समय सामान्य का 5/4 होता है, इसलिए अतिरिक्त 1/4 = 15 मिनट और सामान्य समय 60 मिनट है। 5/4 चाल पर वह 48 मिनट लेता है, यानी 12 मिनट जल्दी।","subtopic":"late-early"},
  {"id":"quant-tsd-65","question":"A car covers 540 m in 18 seconds. What is its speed in km/h?","options":["30 km/h","108 km/h","100 km/h","120 km/h"],"answer":1,"explanation":"Speed = 540/18 = 30 m/s, and 30 × 18/5 = 108 km/h. 30 km/h forgets the unit conversion, the most common slip here.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"एक कार 18 सेकंड में 540 m की दूरी तय करती है। उसकी चाल km/h में कितनी है?","optionsHi":["30 km/h","108 km/h","100 km/h","120 km/h"],"explanationHi":"चाल = 540/18 = 30 m/s, और 30 × 18/5 = 108 km/h। 30 km/h इकाई-परिवर्तन भूलना है, जो यहाँ सबसे आम भूल है।","subtopic":"basic-speed"},
  {"id":"quant-tsd-66","question":"A train covers 285 km in 3 hours 48 minutes. What is its average speed?","options":["75 km/h","76 km/h","74 km/h","80 km/h"],"answer":0,"explanation":"3 h 48 min = 3.8 h. Speed = 285 ÷ 3.8 = 75 km/h. Reading 48 minutes as 0.48 h is the trap.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"एक रेलगाड़ी 3 घंटे 48 मिनट में 285 km की दूरी तय करती है। उसकी औसत चाल क्या है?","optionsHi":["75 km/h","76 km/h","74 km/h","80 km/h"],"explanationHi":"3 घंटे 48 मिनट = 3.8 घंटे। चाल = 285 ÷ 3.8 = 75 km/h। 48 मिनट को 0.48 घंटा पढ़ना जाल है।","subtopic":"basic-speed"},
  {"id":"quant-tsd-67","question":"The speeds of two cyclists are in the ratio 4 : 5. If the faster one takes 40 minutes for a ride, how long does the slower one take for the same ride?","options":["32 minutes","45 minutes","60 minutes","50 minutes"],"answer":3,"explanation":"For the same distance, time is inversely proportional to speed: 40 × 5/4 = 50 minutes.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"दो साइकिल सवारों की चालों का अनुपात 4 : 5 है। यदि तेज़ वाला किसी सवारी में 40 मिनट लेता है, तो धीमा उसी सवारी में कितना समय लेगा?","optionsHi":["32 मिनट","45 मिनट","60 मिनट","50 मिनट"],"explanationHi":"समान दूरी के लिए समय चाल के व्युत्क्रमानुपाती होता है: 40 × 5/4 = 50 मिनट।","subtopic":"basic-speed"},
  {"id":"quant-tsd-68","question":"An athlete runs 5 laps of a 400 m track in 12 minutes. What is his speed in km/h?","options":["12 km/h","2 km/h","10 km/h","9 km/h"],"answer":2,"explanation":"Distance = 2 km in 12 min = 0.2 h. Speed = 2 ÷ 0.2 = 10 km/h.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"एक एथलीट 400 m की ट्रैक के 5 चक्कर 12 मिनट में दौड़ता है। उसकी चाल km/h में कितनी है?","optionsHi":["12 km/h","2 km/h","10 km/h","9 km/h"],"explanationHi":"दूरी = 2 km, 12 मिनट = 0.2 घंटे में। चाल = 2 ÷ 0.2 = 10 km/h।","subtopic":"basic-speed"},
  {"id":"quant-tsd-69","question":"Thunder is heard 6 seconds after a lightning flash. If sound travels at 330 m/s, how far away was the lightning?","options":["1.8 km","2.2 km","1.98 km","0.55 km"],"answer":2,"explanation":"Distance = 330 × 6 = 1,980 m = 1.98 km (light arrives almost instantly).","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"बिजली की चमक के 6 सेकंड बाद बादल की गड़गड़ाहट सुनाई देती है। यदि ध्वनि की चाल 330 m/s है, तो बिजली कितनी दूर थी?","optionsHi":["1.8 km","2.2 km","1.98 km","0.55 km"],"explanationHi":"दूरी = 330 × 6 = 1,980 m = 1.98 km (प्रकाश लगभग तुरंत पहुँच जाता है)।","subtopic":"basic-speed"},
  {"id":"quant-tsd-70","question":"A bus covers 210 km in 3.5 hours. At the same speed, how long will it take to cover 330 km?","options":["5 hours","5.5 hours","6 hours","5.25 hours"],"answer":1,"explanation":"Speed = 210/3.5 = 60 km/h, so 330 km takes 330/60 = 5.5 hours. 6 hours or 5.25 hours come from a wrong speed (55 or about 63 km/h).","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"एक बस 3.5 घंटे में 210 km की दूरी तय करती है। उसी चाल से 330 km तय करने में उसे कितना समय लगेगा?","optionsHi":["5 घंटे","5.5 घंटे","6 घंटे","5.25 घंटे"],"explanationHi":"चाल = 210/3.5 = 60 km/h, इसलिए 330 km में 330/60 = 5.5 घंटे लगते हैं। 6 घंटे या 5.25 घंटे गलत चाल (55 या लगभग 63 km/h) से आते हैं।","subtopic":"basic-speed"},
  {"id":"quant-tsd-71","question":"A man walks the 2.4 km between two stations in 20 minutes. What is his speed in km/h?","options":["7.2 km/h","8 km/h","12 km/h","4.8 km/h"],"answer":0,"explanation":"20 minutes = 1/3 hour, so speed = 2.4 × 3 = 7.2 km/h. 4.8 km/h doubles the distance instead of tripling, and 12 km/h divides 2.4 by 0.2.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"एक आदमी दो स्टेशनों के बीच की 2.4 km की दूरी 20 मिनट में पैदल चलता है। उसकी चाल km/h में कितनी है?","optionsHi":["7.2 km/h","8 km/h","12 km/h","4.8 km/h"],"explanationHi":"20 मिनट = 1/3 घंटा, इसलिए चाल = 2.4 × 3 = 7.2 km/h। 4.8 km/h तिगुना करने के बजाय दूरी को दोगुना करना है, और 12 km/h 2.4 को 0.2 से भाग देना है।","subtopic":"basic-speed"},
  {"id":"quant-tsd-72","question":"A boat moves at 15 km/h in still water and the stream flows at 3 km/h. What is its speed downstream?","options":["12 km/h","15 km/h","9 km/h","18 km/h"],"answer":3,"explanation":"Downstream the stream helps: 15 + 3 = 18 km/h (upstream it would be 12 km/h).","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"एक नाव स्थिर जल में 15 km/h की चाल से चलती है और धारा 3 km/h की चाल से बहती है। धारा के अनुकूल उसकी चाल क्या है?","optionsHi":["12 km/h","15 km/h","9 km/h","18 km/h"],"explanationHi":"धारा के अनुकूल धारा सहायता करती है: 15 + 3 = 18 km/h (प्रतिकूल यह 12 km/h होती)।","subtopic":"boats-streams"},
  {"id":"quant-tsd-73","question":"A 180 m long train running at 54 km/h crosses a bridge in 40 seconds. How long is the bridge?","options":["600 m","360 m","400 m","420 m"],"answer":3,"explanation":"54 km/h = 15 m/s. In 40 s the train covers 600 m = train + bridge, so the bridge = 600 − 180 = 420 m.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"54 km/h की चाल से चलती 180 m लंबी एक रेलगाड़ी एक पुल को 40 सेकंड में पार करती है। पुल कितना लंबा है?","optionsHi":["600 m","360 m","400 m","420 m"],"explanationHi":"54 km/h = 15 m/s। 40 s में रेलगाड़ी 600 m = रेलगाड़ी + पुल चलती है, इसलिए पुल = 600 − 180 = 420 m।","subtopic":"trains"},
  {"id":"quant-tsd-74","question":"A man covers a distance in 2 hours at 30 km/h. At what speed must he travel to cover it in 1.5 hours?","options":["45 km/h","35 km/h","40 km/h","37.5 km/h"],"answer":2,"explanation":"Distance = 30 × 2 = 60 km, so in 1.5 hours he needs 60/1.5 = 40 km/h. 45 km/h scales the speed by 1.5 instead of by 2/1.5, and 37.5 by 1.25.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"एक आदमी 30 km/h की चाल से 2 घंटे में एक दूरी तय करता है। उसे वही दूरी 1.5 घंटे में तय करने के लिए किस चाल से चलना होगा?","optionsHi":["45 km/h","35 km/h","40 km/h","37.5 km/h"],"explanationHi":"दूरी = 30 × 2 = 60 km, इसलिए 1.5 घंटे में उसे 60/1.5 = 40 km/h चाहिए। 45 km/h चाल को 2/1.5 के बजाय 1.5 से गुणा करता है, और 37.5 उसे 1.25 से।","subtopic":"basic-speed"},
  {"id":"quant-tsd-75","question":"Two cars start from the same point at the same time and travel in opposite directions at 45 km/h and 55 km/h. How far apart are they after 2 hours 24 minutes?","options":["224 km","240 km","250 km","24 km"],"answer":1,"explanation":"They separate at 45 + 55 = 100 km/h. 2 h 24 min = 2.4 h, so 240 km. Their difference in speed (10 km/h) would give only 24 km.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"दो कारें एक ही बिंदु से एक ही समय चलना शुरू करती हैं और विपरीत दिशाओं में 45 km/h और 55 km/h की चाल से जाती हैं। 2 घंटे 24 मिनट बाद वे एक-दूसरे से कितनी दूर होंगी?","optionsHi":["224 km","240 km","250 km","24 km"],"explanationHi":"वे 45 + 55 = 100 km/h की दर से दूर होती हैं। 2 घंटे 24 मिनट = 2.4 घंटे, इसलिए 240 km। चालों का अंतर (10 km/h) लेने पर केवल 24 km आता।","subtopic":"relative-speed"},
  {"id":"quant-tsd-76","question":"A car covers 35 km in the first hour and its speed increases by 2 km/h every hour after that. How far does it travel in 12 hours?","options":["552 km","420 km","546 km","564 km"],"answer":0,"explanation":"Distances form an AP: 35, 37, …, 57. Sum = 12 × (35 + 57)/2 = 552 km.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक कार पहले घंटे में 35 km चलती है और उसके बाद हर घंटे उसकी चाल 2 km/h बढ़ती जाती है। वह 12 घंटे में कितनी दूरी तय करती है?","optionsHi":["552 km","420 km","546 km","564 km"],"explanationHi":"दूरियाँ समांतर श्रेणी बनाती हैं: 35, 37, …, 57। योग = 12 × (35 + 57)/2 = 552 km।","subtopic":"basic-speed"},
  {"id":"quant-tsd-77","question":"A boat that moves at 20 km/h in still water covers 48 km downstream in 2 hours. What is its speed upstream?","options":["16 km/h","24 km/h","12 km/h","18 km/h"],"answer":0,"explanation":"Downstream speed = 24 km/h, so the stream = 4 km/h and upstream = 20 − 4 = 16 km/h.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"स्थिर जल में 20 km/h की चाल से चलने वाली एक नाव धारा के अनुकूल 48 km 2 घंटे में तय करती है। धारा के प्रतिकूल उसकी चाल क्या है?","optionsHi":["16 km/h","24 km/h","12 km/h","18 km/h"],"explanationHi":"अनुकूल चाल = 24 km/h, इसलिए धारा = 4 km/h और प्रतिकूल = 20 − 4 = 16 km/h।","subtopic":"boats-streams"},
  {"id":"quant-tsd-78","question":"A man walks 4 km in 50 minutes and then cycles 11 km in 40 minutes. What is his average speed for the whole trip?","options":["12.6 km/h","9.5 km/h","11 km/h","10 km/h"],"answer":3,"explanation":"Total = 15 km in 90 min = 1.5 h, so 10 km/h. Averaging the two speeds (4.8 and 16.5) is wrong.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"एक आदमी 50 मिनट में 4 km पैदल चलता है और फिर 40 मिनट में 11 km साइकिल चलाता है। पूरी यात्रा की औसत चाल क्या है?","optionsHi":["12.6 km/h","9.5 km/h","11 km/h","10 km/h"],"explanationHi":"कुल = 90 मिनट = 1.5 घंटे में 15 km, इसलिए 10 km/h। दोनों चालों (4.8 और 16.5) का औसत लेना गलत है।","subtopic":"average-speed"},
  {"id":"quant-tsd-79","question":"A 250 m long train running at 66 km/h passes through a 300 m long tunnel. How long does it take to clear the tunnel completely?","options":["16.4 seconds","13.6 seconds","30 seconds","25 seconds"],"answer":2,"explanation":"Distance = 250 + 300 = 550 m; speed = 66 × 5/18 = 55/3 m/s. Time = 550 × 3/55 = 30 s.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"66 km/h की चाल से चलती 250 m लंबी एक रेलगाड़ी 300 m लंबी सुरंग से गुज़रती है। सुरंग को पूरी तरह पार करने में उसे कितना समय लगता है?","optionsHi":["16.4 सेकंड","13.6 सेकंड","30 सेकंड","25 सेकंड"],"explanationHi":"दूरी = 250 + 300 = 550 m; चाल = 66 × 5/18 = 55/3 m/s। समय = 550 × 3/55 = 30 s।","subtopic":"trains"},
  {"id":"quant-tsd-80","question":"The speeds of A and B are in the ratio 3 : 4, and A takes 30 minutes more than B to cover a certain distance. How long does B take?","options":["120 minutes","90 minutes","60 minutes","40 minutes"],"answer":1,"explanation":"Times are in the ratio 4 : 3; the difference of 1 part = 30 min. B takes 3 parts = 90 minutes.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"A और B की चालों का अनुपात 3 : 4 है, और A किसी दूरी को तय करने में B से 30 मिनट अधिक लेता है। B कितना समय लेता है?","optionsHi":["120 मिनट","90 मिनट","60 मिनट","40 मिनट"],"explanationHi":"समयों का अनुपात 4 : 3 है; 1 भाग का अंतर = 30 मिनट। B 3 भाग लेता है = 90 मिनट।","subtopic":"late-early"},
  {"id":"quant-tsd-81","question":"In a 100 m race, A beats B by 10 m. What is the ratio of their speeds?","options":["9 : 10","10 : 9","11 : 10","10 : 1"],"answer":1,"explanation":"When A runs 100 m, B runs 90 m in the same time. Speeds are 100 : 90 = 10 : 9.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"100 m की दौड़ में A, B को 10 m से हराता है। उनकी चालों का अनुपात क्या है?","optionsHi":["9 : 10","10 : 9","11 : 10","10 : 1"],"explanationHi":"जब A 100 m दौड़ता है, तब उतने ही समय में B 90 m दौड़ता है। चालें 100 : 90 = 10 : 9 हैं।","subtopic":"circular-track"},
  {"id":"quant-tsd-82","question":"A rider travels at 15 km/h for 40 minutes and then covers 12 km at 18 km/h. What is his average speed?","options":["16.5 km/h","16 km/h","17 km/h","15.5 km/h"],"answer":0,"explanation":"First leg: 10 km in 40 min; second: 12 km in 40 min. Total 22 km in 80 min = 22 × 60/80 = 16.5 km/h.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"एक सवार 40 मिनट तक 15 km/h की चाल से चलता है और फिर 18 km/h की चाल से 12 km तय करता है। उसकी औसत चाल क्या है?","optionsHi":["16.5 km/h","16 km/h","17 km/h","15.5 km/h"],"explanationHi":"पहला चरण: 40 मिनट में 10 km; दूसरा: 40 मिनट में 12 km। कुल 80 मिनट में 22 km = 22 × 60/80 = 16.5 km/h।","subtopic":"average-speed"},
  {"id":"quant-tsd-83","question":"A man travels half a distance by bus at 60 km/h and the other half on foot at 6 km/h, taking 5.5 hours in all. What is the total distance?","options":["66 km","55 km","72 km","60 km"],"answer":3,"explanation":"Each half is d/2: d/120 + d/12 = 11d/120 = 5.5, so d = 60 km. 66 km and 55 km multiply 5.5 hours by one wrong speed (12 or 10 km/h) instead of splitting the halves.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक आदमी आधी दूरी बस से 60 km/h की चाल से और शेष आधी दूरी पैदल 6 km/h की चाल से तय करता है, कुल 5.5 घंटे में। कुल दूरी क्या है?","optionsHi":["66 km","55 km","72 km","60 km"],"explanationHi":"प्रत्येक आधा भाग d/2 है: d/120 + d/12 = 11d/120 = 5.5, इसलिए d = 60 km। 66 km और 55 km आधे-आधे भाग करने के बजाय 5.5 घंटे को एक गलत चाल (12 या 10 km/h) से गुणा करने से आते हैं।","subtopic":"basic-speed"},
  {"id":"quant-tsd-84","question":"A truck's speed is 3/5 of a car's speed. The car covers 450 km in 6 hours. How far will the truck go in 5 hours?","options":["270 km","250 km","225 km","375 km"],"answer":2,"explanation":"Car = 450/6 = 75 km/h, so truck = 3/5 × 75 = 45 km/h and covers 225 km in 5 hours. 270 km applies 3/5 to the car's 450 km, and 375 km is the car's distance in 5 hours.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"एक ट्रक की चाल कार की चाल की 3/5 है। कार 6 घंटे में 450 km की दूरी तय करती है। ट्रक 5 घंटे में कितनी दूर जाएगा?","optionsHi":["270 km","250 km","225 km","375 km"],"explanationHi":"कार = 450/6 = 75 km/h, इसलिए ट्रक = 3/5 × 75 = 45 km/h और 5 घंटे में 225 km चलेगा। 270 km कार के 450 km पर 3/5 लगाना है, और 375 km 5 घंटे में कार की तय की गई दूरी है।","subtopic":"basic-speed"},
  {"id":"quant-tsd-85","question":"Two trains 180 m and 120 m long, running in opposite directions, cross each other in 12 seconds. If one runs at 40 km/h, what is the speed of the other?","options":["90 km/h","60 km/h","50 km/h","45 km/h"],"answer":2,"explanation":"Relative speed = 300/12 = 25 m/s = 90 km/h. The other train runs at 90 − 40 = 50 km/h.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"180 m और 120 m लंबी दो रेलगाड़ियाँ विपरीत दिशाओं में चलते हुए एक-दूसरे को 12 सेकंड में पार करती हैं। यदि एक की चाल 40 km/h है, तो दूसरी की चाल क्या है?","optionsHi":["90 km/h","60 km/h","50 km/h","45 km/h"],"explanationHi":"सापेक्ष चाल = 300/12 = 25 m/s = 90 km/h। दूसरी रेलगाड़ी 90 − 40 = 50 km/h की चाल से चलती है।","subtopic":"trains"},
  {"id":"quant-tsd-86","question":"A car goes from P to Q at 40 km/h and its average speed for the round trip is 48 km/h. What was its speed from Q to P?","options":["56 km/h","60 km/h","52 km/h","64 km/h"],"answer":1,"explanation":"2 × 40 × v/(40 + v) = 48 gives 80v = 1,920 + 48v, so v = 60 km/h. 56 km/h assumes the simple average.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक कार P से Q तक 40 km/h की चाल से जाती है और पूरी आने-जाने की यात्रा की उसकी औसत चाल 48 km/h है। Q से P तक उसकी चाल क्या थी?","optionsHi":["56 km/h","60 km/h","52 km/h","64 km/h"],"explanationHi":"2 × 40 × v/(40 + v) = 48 से 80v = 1,920 + 48v, इसलिए v = 60 km/h। 56 km/h साधारण औसत मान लेने से आता है।","subtopic":"average-speed"},
  {"id":"quant-tsd-87","question":"A man fires a gun facing a cliff and hears the echo 3 seconds later. If sound travels at 340 m/s, how far is the cliff?","options":["510 m","1,020 m","340 m","680 m"],"answer":0,"explanation":"Sound goes to the cliff and back: 2d = 340 × 3 = 1,020 m, so d = 510 m.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"एक आदमी चट्टान की ओर मुँह करके बंदूक चलाता है और 3 सेकंड बाद प्रतिध्वनि सुनता है। यदि ध्वनि की चाल 340 m/s है, तो चट्टान कितनी दूर है?","optionsHi":["510 m","1,020 m","340 m","680 m"],"explanationHi":"ध्वनि चट्टान तक जाती है और लौटती है: 2d = 340 × 3 = 1,020 m, इसलिए d = 510 m।","subtopic":"basic-speed"},
  {"id":"quant-tsd-88","question":"Fog cuts a train's speed to 80% of normal, and a 240 km run takes 1 hour longer. What is its normal speed?","options":["48 km/h","75 km/h","80 km/h","60 km/h"],"answer":3,"explanation":"At 80% speed the time is 1.25 times normal, so the extra 0.25 × normal time = 1 h, giving normal time 4 h and speed 240/4 = 60 km/h.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"कोहरे के कारण एक रेलगाड़ी की चाल सामान्य की 80% रह जाती है, और 240 km की यात्रा में 1 घंटा अधिक लगता है। उसकी सामान्य चाल क्या है?","optionsHi":["48 km/h","75 km/h","80 km/h","60 km/h"],"explanationHi":"80% चाल पर समय सामान्य का 1.25 गुना होता है, इसलिए अतिरिक्त 0.25 × सामान्य समय = 1 घंटा, जिससे सामान्य समय 4 घंटे और चाल 240/4 = 60 km/h।","subtopic":"late-early"},
  {"id":"quant-tsd-89","question":"A swimmer covers 2 km against the current in 40 minutes and returns in 20 minutes. What is the speed of the current?","options":["3 km/h","4.5 km/h","1 km/h","1.5 km/h"],"answer":3,"explanation":"Upstream = 2/(2/3) = 3 km/h; downstream = 2/(1/3) = 6 km/h. Current = (6 − 3)/2 = 1.5 km/h.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"एक तैराक धारा के विरुद्ध 2 km 40 मिनट में तैरता है और 20 मिनट में लौट आता है। धारा की चाल क्या है?","optionsHi":["3 km/h","4.5 km/h","1 km/h","1.5 km/h"],"explanationHi":"प्रतिकूल = 2/(2/3) = 3 km/h; अनुकूल = 2/(1/3) = 6 km/h। धारा = (6 − 3)/2 = 1.5 km/h।","subtopic":"boats-streams"},
  {"id":"quant-tsd-90","question":"A covers a distance in 4 hours and B in 6 hours. They start at the same time from opposite ends and walk towards each other. What fraction of the distance has A covered when they meet?","options":["2/3","2/5","3/5","1/2"],"answer":2,"explanation":"Speeds are in the ratio 1/4 : 1/6 = 3 : 2, so A covers 3/5 of the distance.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"A किसी दूरी को 4 घंटे में और B 6 घंटे में तय करता है। वे एक ही समय विपरीत सिरों से एक-दूसरे की ओर चलना शुरू करते हैं। मिलने पर A ने दूरी का कितना भाग तय किया होगा?","optionsHi":["2/3","2/5","3/5","1/2"],"explanationHi":"चालों का अनुपात 1/4 : 1/6 = 3 : 2 है, इसलिए A दूरी का 3/5 भाग तय करता है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-91","question":"The speeds of three cars are in the ratio 2 : 3 : 4. What is the ratio of the times they take to cover the same distance?","options":["4 : 3 : 2","6 : 4 : 3","2 : 3 : 4","3 : 4 : 6"],"answer":1,"explanation":"Times ∝ 1/speed: 1/2 : 1/3 : 1/4 = 6 : 4 : 3 (multiplying by 12).","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"तीन कारों की चालों का अनुपात 2 : 3 : 4 है। समान दूरी तय करने में उनके द्वारा लिए गए समयों का अनुपात क्या है?","optionsHi":["4 : 3 : 2","6 : 4 : 3","2 : 3 : 4","3 : 4 : 6"],"explanationHi":"समय ∝ 1/चाल: 1/2 : 1/3 : 1/4 = 6 : 4 : 3 (12 से गुणा करने पर)।","subtopic":"basic-speed"},
  {"id":"quant-tsd-92","question":"A man must cover 15 km in 1.5 hours. He walks the first 5 km at 5 km/h. At what speed must he cover the rest?","options":["20 km/h","10 km/h","15 km/h","12 km/h"],"answer":0,"explanation":"The first 5 km take 1 hour, leaving 0.5 hour for 10 km: 20 km/h. 10 km/h divides 15 km by 1.5 hours, ignoring the slow first part.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"एक आदमी को 1.5 घंटे में 15 km की दूरी तय करनी है। वह पहले 5 km 5 km/h की चाल से चलता है। शेष दूरी उसे किस चाल से तय करनी होगी?","optionsHi":["20 km/h","10 km/h","15 km/h","12 km/h"],"explanationHi":"पहले 5 km में 1 घंटा लगता है, इसलिए 10 km के लिए 0.5 घंटा बचता है: 20 km/h। 10 km/h 15 km को 1.5 घंटे से भाग देता है, जो धीमे पहले भाग को अनदेखा करता है।","subtopic":"late-early"},
  {"id":"quant-tsd-93","question":"A train passes a 120 m platform in 18 seconds and a man walking at 6 km/h in the same direction in 12 seconds. How long is the train?","options":["200 m","180 m","240 m","150 m"],"answer":1,"explanation":"With speed v m/s: L + 120 = 18v and L = 12(v − 5/3). So 18v − 120 = 12v − 20, v = 50/3 m/s (60 km/h) and L = 300 − 120 = 180 m.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक रेलगाड़ी 120 m लंबे प्लेटफ़ॉर्म को 18 सेकंड में और उसी दिशा में 6 km/h की चाल से चलते एक आदमी को 12 सेकंड में पार करती है। रेलगाड़ी कितनी लंबी है?","optionsHi":["200 m","180 m","240 m","150 m"],"explanationHi":"चाल v m/s मानें: L + 120 = 18v और L = 12(v − 5/3)। इसलिए 18v − 120 = 12v − 20, v = 50/3 m/s (60 km/h) और L = 300 − 120 = 180 m।","subtopic":"trains"},
  {"id":"quant-tsd-94","question":"Train A (150 m) passes a pole in 10 seconds and train B (200 m) passes it in 8 seconds. How long will they take to cross each other when running in opposite directions?","options":["8.75 seconds","9 seconds","35 seconds","10 seconds"],"answer":0,"explanation":"Speeds: 150/10 = 15 m/s and 200/8 = 25 m/s. Opposite directions: 350/(15 + 25) = 8.75 s.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"रेलगाड़ी A (150 m) एक खंभे को 10 सेकंड में और रेलगाड़ी B (200 m) 8 सेकंड में पार करती है। विपरीत दिशाओं में चलते हुए वे एक-दूसरे को कितने समय में पार करेंगी?","optionsHi":["8.75 सेकंड","9 सेकंड","35 सेकंड","10 सेकंड"],"explanationHi":"चालें: 150/10 = 15 m/s और 200/8 = 25 m/s। विपरीत दिशाओं में: 350/(15 + 25) = 8.75 s।","subtopic":"trains"},
  {"id":"quant-tsd-95","question":"A 300 m long train overtakes a cyclist riding at 18 km/h in 30 seconds. How long will it take to pass a car coming towards it at 36 km/h?","options":["15 seconds","20 seconds","10 seconds","12 seconds"],"answer":3,"explanation":"Relative speed with the cyclist = 10 m/s, so the train runs at 10 + 5 = 15 m/s. With the car: 15 + 10 = 25 m/s, so 300/25 = 12 s.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"300 m लंबी एक रेलगाड़ी 18 km/h की चाल से चलते एक साइकिल सवार को 30 सेकंड में पार करती है। सामने से 36 km/h की चाल से आती एक कार को पार करने में उसे कितना समय लगेगा?","optionsHi":["15 सेकंड","20 सेकंड","10 सेकंड","12 सेकंड"],"explanationHi":"साइकिल सवार के साथ सापेक्ष चाल = 10 m/s, इसलिए रेलगाड़ी की चाल 10 + 5 = 15 m/s है। कार के साथ: 15 + 10 = 25 m/s, इसलिए 300/25 = 12 s।","subtopic":"trains"},
  {"id":"quant-tsd-96","question":"Car P leaves a town at 9:00 am at 40 km/h. Car Q leaves the same town on the same road at 9:30 am at 50 km/h, and car R at 10:00 am at 60 km/h. Which car does R overtake first, and when?","options":["Q, at 12:30 pm","P, at 12:30 pm","P, at 12 noon","Q, at 12 noon"],"answer":2,"explanation":"At 10 am P is 40 km ahead and Q 25 km ahead. R gains 20 km/h on P (2 h, i.e. 12 noon) but only 10 km/h on Q (2.5 h, 12:30 pm). So P is overtaken first, at noon.","difficulty":"hard","source":"SSC CGL · SSC CPO","questionHi":"कार P सुबह 9:00 बजे एक शहर से 40 km/h की चाल से निकलती है। कार Q उसी शहर से उसी सड़क पर सुबह 9:30 बजे 50 km/h की चाल से निकलती है, और कार R सुबह 10:00 बजे 60 km/h की चाल से। R किस कार को पहले पार करेगी, और कब?","optionsHi":["Q को, दोपहर 12:30 बजे","P को, दोपहर 12:30 बजे","P को, दोपहर 12 बजे","Q को, दोपहर 12 बजे"],"explanationHi":"सुबह 10 बजे P 40 km आगे और Q 25 km आगे है। R, P पर 20 km/h की बढ़त बनाता है (2 घंटे, यानी दोपहर 12 बजे) पर Q पर केवल 10 km/h की (2.5 घंटे, दोपहर 12:30 बजे)। इसलिए P को पहले, दोपहर 12 बजे पार किया जाता है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-97","question":"A 200 m long train passes a 300 m platform in 25 seconds. How long will it take to pass a 150 m long train coming from the opposite direction at 54 km/h?","options":["7 seconds","17.5 seconds","10 seconds","14 seconds"],"answer":2,"explanation":"Train speed = 500/25 = 20 m/s; the other runs at 15 m/s. Relative speed 35 m/s, distance 350 m, so 10 s.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"200 m लंबी एक रेलगाड़ी 300 m लंबे प्लेटफ़ॉर्म को 25 सेकंड में पार करती है। विपरीत दिशा से 54 km/h की चाल से आती 150 m लंबी रेलगाड़ी को पार करने में उसे कितना समय लगेगा?","optionsHi":["7 सेकंड","17.5 सेकंड","10 सेकंड","14 सेकंड"],"explanationHi":"रेलगाड़ी की चाल = 500/25 = 20 m/s; दूसरी 15 m/s से चलती है। सापेक्ष चाल 35 m/s, दूरी 350 m, इसलिए 10 s।","subtopic":"trains"},
  {"id":"quant-tsd-98","question":"A boat's speed in still water is three times the stream's speed. It covers 32 km downstream in 2 hours. How long will it take to go 24 km upstream?","options":["2 hours","3 hours","4 hours","1.5 hours"],"answer":1,"explanation":"Downstream = 4s = 16 km/h, so s = 4 and the boat = 12 km/h. Upstream = 8 km/h, so 24 km takes 3 hours.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"स्थिर जल में नाव की चाल धारा की चाल की तीन गुनी है। वह धारा के अनुकूल 32 km 2 घंटे में तय करती है। धारा के प्रतिकूल 24 km जाने में उसे कितना समय लगेगा?","optionsHi":["2 घंटे","3 घंटे","4 घंटे","1.5 घंटे"],"explanationHi":"अनुकूल = 4s = 16 km/h, इसलिए s = 4 और नाव = 12 km/h। प्रतिकूल = 8 km/h, इसलिए 24 km में 3 घंटे लगते हैं।","subtopic":"boats-streams"},
  {"id":"quant-tsd-99","question":"At 40 km/h a train reaches its destination 11 minutes late; at 50 km/h it is only 5 minutes late. How long is the journey?","options":["20 km","25 km","30 km","16 km"],"answer":0,"explanation":"The two times differ by 6 minutes: d/40 − d/50 = d/200 = 1/10 h, so d = 20 km.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"40 km/h की चाल से चलने पर एक रेलगाड़ी अपने गंतव्य पर 11 मिनट देर से पहुँचती है; 50 km/h की चाल से वह केवल 5 मिनट देर से पहुँचती है। यात्रा की दूरी कितनी है?","optionsHi":["20 km","25 km","30 km","16 km"],"explanationHi":"दोनों समयों में 6 मिनट का अंतर है: d/40 − d/50 = d/200 = 1/10 घंटा, इसलिए d = 20 km।","subtopic":"late-early"},
  {"id":"quant-tsd-100","question":"A motorcycle leaves town A for town B at 9 am at 40 km/h. A car leaves A at 10 am at 60 km/h and reaches B one hour before the motorcycle. How far is B from A?","options":["180 km","200 km","120 km","240 km"],"answer":3,"explanation":"If the motorcycle takes t hours, the car takes t − 2 (it starts 1 h later and arrives 1 h earlier). 40t = 60(t − 2) gives t = 6, so the distance is 240 km.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक मोटरसाइकिल शहर A से शहर B के लिए सुबह 9 बजे 40 km/h की चाल से चलती है। एक कार A से सुबह 10 बजे 60 km/h की चाल से चलती है और B पर मोटरसाइकिल से एक घंटा पहले पहुँचती है। B, A से कितनी दूर है?","optionsHi":["180 km","200 km","120 km","240 km"],"explanationHi":"यदि मोटरसाइकिल को t घंटे लगते हैं, तो कार को t − 2 लगते हैं (वह 1 घंटा बाद चलती है और 1 घंटा पहले पहुँचती है)। 40t = 60(t − 2) से t = 6, इसलिए दूरी 240 km है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-101","question":"A train passes a standing man in 18 seconds and a man walking towards it at 6 km/h in 16 seconds. What is the speed of the train?","options":["54 km/h","45 km/h","60 km/h","48 km/h"],"answer":3,"explanation":"Length = 18v = 16(v + 5/3), so 2v = 80/3 and v = 40/3 m/s = 48 km/h (train length 240 m).","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक रेलगाड़ी खड़े आदमी को 18 सेकंड में और अपनी ओर 6 km/h की चाल से चलकर आते आदमी को 16 सेकंड में पार करती है। रेलगाड़ी की चाल क्या है?","optionsHi":["54 km/h","45 km/h","60 km/h","48 km/h"],"explanationHi":"लंबाई = 18v = 16(v + 5/3), इसलिए 2v = 80/3 और v = 40/3 m/s = 48 km/h (रेलगाड़ी की लंबाई 240 m)।","subtopic":"trains"},
  {"id":"quant-tsd-102","question":"A car's speed is 80% of a train's speed. The car starts 30 minutes before the train from the same place, and the train catches it 2 hours after starting, 160 km from the start. What is the car's speed?","options":["80 km/h","60 km/h","64 km/h","72 km/h"],"answer":2,"explanation":"The car has been driving 2.5 hours when caught, so its speed = 160/2.5 = 64 km/h (and the train's 160/2 = 80 km/h, consistent with 80%).","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक कार की चाल एक रेलगाड़ी की चाल की 80% है। कार उसी स्थान से रेलगाड़ी से 30 मिनट पहले चलती है, और रेलगाड़ी चलने के 2 घंटे बाद, शुरुआत से 160 km पर उसे पकड़ लेती है। कार की चाल क्या है?","optionsHi":["80 km/h","60 km/h","64 km/h","72 km/h"],"explanationHi":"पकड़े जाने तक कार 2.5 घंटे चल चुकी होती है, इसलिए उसकी चाल = 160/2.5 = 64 km/h (और रेलगाड़ी की 160/2 = 80 km/h, जो 80% से मेल खाती है)।","subtopic":"relative-speed"},
  {"id":"quant-tsd-103","question":"With a tailwind a plane covers 1,200 km in 2 hours; against the same wind it takes 2.5 hours. What is the wind speed?","options":["120 km/h","60 km/h","40 km/h","540 km/h"],"answer":1,"explanation":"Speeds: 600 km/h with the wind and 480 km/h against. Wind = (600 − 480)/2 = 60 km/h (plane 540 km/h).","difficulty":"hard","source":"SSC CGL · CDS","questionHi":"पीछे की हवा के साथ एक विमान 2 घंटे में 1,200 km की दूरी तय करता है; उसी हवा के विरुद्ध उसे 2.5 घंटे लगते हैं। हवा की चाल क्या है?","optionsHi":["120 km/h","60 km/h","40 km/h","540 km/h"],"explanationHi":"चालें: हवा के साथ 600 km/h और हवा के विरुद्ध 480 km/h। हवा = (600 − 480)/2 = 60 km/h (विमान 540 km/h)।","subtopic":"boats-streams"},
  {"id":"quant-tsd-104","question":"Car A is 20% faster than car B. B leaves first, and A follows 30 minutes later on the same road, catching B 180 km from the start. What is A's speed?","options":["72 km/h","60 km/h","75 km/h","80 km/h"],"answer":0,"explanation":"B drives t hours and A t − 0.5 at 1.2 times the speed: t = 1.2(t − 0.5), so t = 3. B = 60 km/h and A = 180/2.5 = 72 km/h.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"कार A, कार B से 20% तेज़ है। B पहले निकलती है, और A उसी सड़क पर 30 मिनट बाद चलकर शुरुआत से 180 km पर B को पकड़ लेती है। A की चाल क्या है?","optionsHi":["72 km/h","60 km/h","75 km/h","80 km/h"],"explanationHi":"B, t घंटे और A, t − 0.5 घंटे चलती है, A की चाल B की 1.2 गुनी है: t = 1.2(t − 0.5), इसलिए t = 3। B = 60 km/h और A = 180/2.5 = 72 km/h।","subtopic":"relative-speed"},
  {"id":"quant-tsd-105","question":"A train covers 420 km in 8 hours, including 6 halts of 10 minutes each. What is its average speed while running?","options":["60 km/h","52.5 km/h","56 km/h","65 km/h"],"answer":0,"explanation":"Halts take 60 minutes, so running time = 7 hours. 420/7 = 60 km/h. 52.5 km/h includes the halts.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"एक रेलगाड़ी 8 घंटे में 420 km की दूरी तय करती है, जिसमें 10-10 मिनट के 6 ठहराव शामिल हैं। चलते समय उसकी औसत चाल क्या है?","optionsHi":["60 km/h","52.5 km/h","56 km/h","65 km/h"],"explanationHi":"ठहराव में 60 मिनट लगते हैं, इसलिए चलने का समय = 7 घंटे। 420/7 = 60 km/h। 52.5 km/h में ठहराव शामिल हैं।","subtopic":"average-speed"},
  {"id":"quant-tsd-106","question":"Two trains whose lengths are in the ratio 3 : 2 run in opposite directions at 54 km/h and 36 km/h, and cross each other in 12 seconds. How long is the longer train?","options":["120 m","150 m","200 m","180 m"],"answer":3,"explanation":"Relative speed = 90 km/h = 25 m/s, so the lengths add to 300 m. Longer = 3/5 × 300 = 180 m.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"दो रेलगाड़ियाँ, जिनकी लंबाइयों का अनुपात 3 : 2 है, विपरीत दिशाओं में 54 km/h और 36 km/h की चाल से चलती हैं और एक-दूसरे को 12 सेकंड में पार करती हैं। लंबी रेलगाड़ी कितनी लंबी है?","optionsHi":["120 m","150 m","200 m","180 m"],"explanationHi":"सापेक्ष चाल = 90 km/h = 25 m/s, इसलिए लंबाइयों का योग 300 m है। लंबी = 3/5 × 300 = 180 m।","subtopic":"trains"},
  {"id":"quant-tsd-107","question":"A car covers 60 km in the first hour, and its speed drops by 5 km/h every hour after that. How far does it go in 6 hours?","options":["300 km","270 km","285 km","330 km"],"answer":2,"explanation":"60 + 55 + 50 + 45 + 40 + 35 = 285 km (an AP: 6 × (60 + 35)/2).","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक कार पहले घंटे में 60 km चलती है, और उसके बाद हर घंटे उसकी चाल 5 km/h घटती जाती है। वह 6 घंटे में कितनी दूर जाती है?","optionsHi":["300 km","270 km","285 km","330 km"],"explanationHi":"60 + 55 + 50 + 45 + 40 + 35 = 285 km (समांतर श्रेणी: 6 × (60 + 35)/2)।","subtopic":"basic-speed"},
  {"id":"quant-tsd-108","question":"A rectangular field is 80 m by 60 m. By walking along the diagonal instead of along two adjacent sides, by what percent does a person shorten the walk?","options":["40%","28.57%","20%","25%"],"answer":1,"explanation":"Two sides = 140 m; the diagonal = √(80² + 60²) = 100 m. Saving = 40/140 ≈ 28.57%.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक आयताकार खेत 80 m × 60 m का है। दो आसन्न भुजाओं के साथ चलने के बजाय विकर्ण के साथ चलने से कोई व्यक्ति अपनी दूरी कितने प्रतिशत कम कर लेता है?","optionsHi":["40%","28.57%","20%","25%"],"explanationHi":"दो भुजाएँ = 140 m; विकर्ण = √(80² + 60²) = 100 m। बचत = 40/140 ≈ 28.57%।","subtopic":"basic-speed"},
  {"id":"quant-tsd-109","question":"A man sitting in a train running at 72 km/h sees a 280 m long goods train going the other way pass him in 9 seconds. What is the speed of the goods train?","options":["112 km/h","40 km/h","48 km/h","32 km/h"],"answer":1,"explanation":"Relative speed = 280/9 m/s = 112 km/h. Goods train = 112 − 72 = 40 km/h. Only the goods train's length matters, as the man is a point.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"72 km/h की चाल से चलती रेलगाड़ी में बैठा एक आदमी देखता है कि विपरीत दिशा में जाती 280 m लंबी एक मालगाड़ी उसके सामने से 9 सेकंड में गुज़र जाती है। मालगाड़ी की चाल क्या है?","optionsHi":["112 km/h","40 km/h","48 km/h","32 km/h"],"explanationHi":"सापेक्ष चाल = 280/9 m/s = 112 km/h। मालगाड़ी = 112 − 72 = 40 km/h। केवल मालगाड़ी की लंबाई मायने रखती है, क्योंकि आदमी एक बिंदु है।","subtopic":"trains"},
  {"id":"quant-tsd-110","question":"A boat goes 40 km upstream in 8 hours and 36 km downstream in 6 hours. What is the speed of the stream?","options":["0.5 km/h","1 km/h","5.5 km/h","1.5 km/h"],"answer":0,"explanation":"Upstream = 5 km/h, downstream = 6 km/h. Stream = (6 − 5)/2 = 0.5 km/h; boat = 5.5 km/h.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"एक नाव 40 km धारा के प्रतिकूल 8 घंटे में और 36 km धारा के अनुकूल 6 घंटे में जाती है। धारा की चाल क्या है?","optionsHi":["0.5 km/h","1 km/h","5.5 km/h","1.5 km/h"],"explanationHi":"प्रतिकूल = 5 km/h, अनुकूल = 6 km/h। धारा = (6 − 5)/2 = 0.5 km/h; नाव = 5.5 km/h।","subtopic":"boats-streams"},
  {"id":"quant-tsd-111","question":"A man can row three times as fast downstream as upstream. What is the ratio of his speed in still water to the speed of the stream?","options":["3 : 1","1 : 2","4 : 1","2 : 1"],"answer":3,"explanation":"Take upstream 1 and downstream 3: boat = (3 + 1)/2 = 2 and stream = (3 − 1)/2 = 1. Ratio 2 : 1.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक आदमी धारा के अनुकूल प्रतिकूल से तीन गुना तेज़ नाव चला सकता है। स्थिर जल में उसकी चाल और धारा की चाल का अनुपात क्या है?","optionsHi":["3 : 1","1 : 2","4 : 1","2 : 1"],"explanationHi":"प्रतिकूल 1 और अनुकूल 3 लें: नाव = (3 + 1)/2 = 2 और धारा = (3 − 1)/2 = 1। अनुपात 2 : 1।","subtopic":"boats-streams"},
  {"id":"quant-tsd-112","question":"A man walks from A to B at 5 km/h and cycles back at 15 km/h, taking 1 hour 20 minutes in all. How far is A from B?","options":["6 km","4 km","5 km","7.5 km"],"answer":2,"explanation":"d/5 + d/15 = 4d/15 = 4/3 hour, so d = 5 km. 7.5 is the average speed in km/h for the round trip, not the distance; 4 and 6 km fail the check d/5 + d/15 = 4/3.","difficulty":"hard","source":"SSC CHSL · RRB NTPC","questionHi":"एक आदमी A से B तक 5 km/h की चाल से पैदल जाता है और 15 km/h की चाल से साइकिल से लौटता है, कुल 1 घंटा 20 मिनट लेकर। A से B कितनी दूर है?","optionsHi":["6 km","4 km","5 km","7.5 km"],"explanationHi":"d/5 + d/15 = 4d/15 = 4/3 घंटा, इसलिए d = 5 km। 7.5 आने-जाने की औसत चाल km/h में है, दूरी नहीं; 4 और 6 km जाँच d/5 + d/15 = 4/3 में विफल होते हैं।","subtopic":"basic-speed"},
  {"id":"quant-tsd-113","question":"A sets out walking at 4 km/h. Four hours later B starts cycling after him from the same point at 12 km/h. How far from the start does B catch A?","options":["16 km","20 km","24 km","32 km"],"answer":2,"explanation":"A's lead = 16 km; B gains 8 km/h, so he takes 2 hours and is 24 km from the start.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"A 4 km/h की चाल से पैदल चल पड़ता है। चार घंटे बाद B उसी बिंदु से 12 km/h की चाल से साइकिल से उसका पीछा शुरू करता है। B, A को शुरुआती बिंदु से कितनी दूरी पर पकड़ेगा?","optionsHi":["16 km","20 km","24 km","32 km"],"explanationHi":"A की बढ़त = 16 km; B 8 km/h की बढ़त बनाता है, इसलिए उसे 2 घंटे लगते हैं और वह शुरुआती बिंदु से 24 km पर होता है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-114","question":"A car averages 60 km/h on a journey. Had it gone 10 km/h faster, it would have taken 1 hour less. How long is the journey?","options":["360 km","420 km","600 km","480 km"],"answer":1,"explanation":"d/60 − d/70 = d/420 = 1 hour, so d = 420 km. 360 and 480 km fail the check (they save about 0.86 and 1.14 hours), and 600 km wrongly multiplies 60 by 10.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक कार किसी यात्रा में औसतन 60 km/h की चाल से चलती है। यदि वह 10 km/h अधिक तेज़ चलती, तो उसे 1 घंटा कम लगता। यात्रा कितनी लंबी है?","optionsHi":["360 km","420 km","600 km","480 km"],"explanationHi":"d/60 − d/70 = d/420 = 1 घंटा, इसलिए d = 420 km। 360 और 480 km जाँच में विफल होते हैं (वे लगभग 0.86 और 1.14 घंटे बचाते हैं), और 600 km गलती से 60 को 10 से गुणा करता है।","subtopic":"late-early"},
  {"id":"quant-tsd-115","question":"Two motorcyclists start from the same crossing at the same time, one going north at 30 km/h and the other east at 40 km/h. How far apart are they after 2 hours?","options":["100 km","140 km","20 km","50 km"],"answer":0,"explanation":"After 2 hours they are 60 km and 80 km from the crossing at right angles: √(60² + 80²) = 100 km.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"दो मोटरसाइकिल सवार एक ही चौराहे से एक ही समय चलना शुरू करते हैं, एक उत्तर की ओर 30 km/h की चाल से और दूसरा पूर्व की ओर 40 km/h की चाल से। 2 घंटे बाद वे एक-दूसरे से कितनी दूर होंगे?","optionsHi":["100 km","140 km","20 km","50 km"],"explanationHi":"2 घंटे बाद वे चौराहे से लंब दिशाओं में 60 km और 80 km दूर होते हैं: √(60² + 80²) = 100 km।","subtopic":"relative-speed"},
  {"id":"quant-tsd-116","question":"Two cyclists 60 km apart ride towards each other at 12 km/h and 18 km/h. A bee starts from one cyclist and flies at 40 km/h back and forth between them until they meet. How far does the bee fly in all?","options":["80 km","60 km","40 km","120 km"],"answer":0,"explanation":"The cyclists meet after 60/30 = 2 hours. The bee flies non-stop for those 2 hours: 40 × 2 = 80 km. No need to add up the legs.","difficulty":"very-hard","source":"SSC CGL · CAT-style","questionHi":"दो साइकिल सवार 60 km की दूरी पर हैं और 12 km/h तथा 18 km/h की चाल से एक-दूसरे की ओर चलते हैं। एक मधुमक्खी एक साइकिल सवार से चलना शुरू करती है और 40 km/h की चाल से उनके बीच आगे-पीछे उड़ती रहती है जब तक वे मिल नहीं जाते। मधुमक्खी कुल कितनी दूरी उड़ती है?","optionsHi":["80 km","60 km","40 km","120 km"],"explanationHi":"साइकिल सवार 60/30 = 2 घंटे बाद मिलते हैं। मधुमक्खी उन 2 घंटों तक लगातार उड़ती है: 40 × 2 = 80 km। खंडों को जोड़ने की कोई आवश्यकता नहीं।","subtopic":"relative-speed"},
  {"id":"quant-tsd-117","question":"Two people start from opposite ends of a 30 km road at the same time, walking towards each other at 4 km/h and 6 km/h. Each walks to the far end and immediately turns back. When do they meet for the second time?","options":["6 hours after starting","3 hours after starting","12 hours after starting","9 hours after starting"],"answer":3,"explanation":"By the first meeting they cover 30 km together (3 h). By the second meeting they cover 3 × 30 = 90 km together, which takes 9 hours.","difficulty":"very-hard","source":"SSC CGL · CAT-style","questionHi":"दो व्यक्ति 30 km लंबी सड़क के विपरीत सिरों से एक ही समय एक-दूसरे की ओर 4 km/h और 6 km/h की चाल से चलना शुरू करते हैं। प्रत्येक दूसरे सिरे तक जाकर तुरंत लौट पड़ता है। वे दूसरी बार कब मिलते हैं?","optionsHi":["चलने के 6 घंटे बाद","चलने के 3 घंटे बाद","चलने के 12 घंटे बाद","चलने के 9 घंटे बाद"],"explanationHi":"पहली बार मिलने तक वे साथ में 30 km तय करते हैं (3 घंटे)। दूसरी बार मिलने तक वे साथ में 3 × 30 = 90 km तय करते हैं, जिसमें 9 घंटे लगते हैं।","subtopic":"relative-speed"},
  {"id":"quant-tsd-118","question":"A man rowing upstream drops his hat into the river. He notices 10 minutes later, turns round and rows downstream at the same rowing effort. How long after turning does he reach the hat?","options":["20 minutes","It depends on the stream's speed","10 minutes","5 minutes"],"answer":2,"explanation":"In the water's frame the hat is still and the man rows away and back at the same speed, so he returns in the same 10 minutes. The stream's speed cancels out.","difficulty":"very-hard","source":"SSC CGL · CAT-style","questionHi":"धारा के प्रतिकूल नाव चलाता एक आदमी अपनी टोपी नदी में गिरा देता है। उसे 10 मिनट बाद पता चलता है, वह मुड़ता है और उतने ही प्रयास से धारा के अनुकूल नाव चलाता है। मुड़ने के कितनी देर बाद वह टोपी तक पहुँचता है?","optionsHi":["20 मिनट","यह धारा की चाल पर निर्भर करता है","10 मिनट","5 मिनट"],"explanationHi":"पानी के संदर्भ तंत्र में टोपी स्थिर है और आदमी उसी चाल से दूर जाता है और लौटता है, इसलिए वह उसी 10 मिनट में लौट आता है। धारा की चाल कट जाती है।","subtopic":"boats-streams"},
  {"id":"quant-tsd-119","question":"A boat's speed in still water is 9 km/h. It takes 3 hours longer to go 36 km upstream than to go 36 km downstream. What is the speed of the stream?","options":["4 km/h","3 km/h","2 km/h","4.5 km/h"],"answer":1,"explanation":"36/(9 − s) − 36/(9 + s) = 72s/(81 − s²) = 3, so s² + 24s − 81 = 0 and s = 3 km/h.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"स्थिर जल में एक नाव की चाल 9 km/h है। उसे धारा के प्रतिकूल 36 km जाने में अनुकूल 36 km जाने से 3 घंटे अधिक लगते हैं। धारा की चाल क्या है?","optionsHi":["4 km/h","3 km/h","2 km/h","4.5 km/h"],"explanationHi":"36/(9 − s) − 36/(9 + s) = 72s/(81 − s²) = 3, इसलिए s² + 24s − 81 = 0 और s = 3 km/h।","subtopic":"boats-streams"},
  {"id":"quant-tsd-120","question":"A car covers the three equal thirds of a journey at x, 2x and 3x km/h. If its average speed is 36 km/h, what is x?","options":["18","22","24","20"],"answer":1,"explanation":"Average = 3/(1/x + 1/2x + 1/3x) = 3x/(11/6) = 18x/11 = 36, so x = 22.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"एक कार यात्रा के तीन बराबर तिहाई भाग x, 2x और 3x km/h की चाल से तय करती है। यदि उसकी औसत चाल 36 km/h है, तो x क्या है?","optionsHi":["18","22","24","20"],"explanationHi":"औसत = 3/(1/x + 1/2x + 1/3x) = 3x/(11/6) = 18x/11 = 36, इसलिए x = 22।","subtopic":"average-speed"},
  {"id":"quant-tsd-121","question":"Car A takes 2 hours more than car B to cover 360 km. If A doubled its speed, it would take 1 hour less than B. What is B's speed?","options":["90 km/h","60 km/h","120 km/h","72 km/h"],"answer":0,"explanation":"Let A take x hours and B y hours: x − y = 2 and y − x/2 = 1. So x/2 = 3, x = 6 and y = 4. B's speed = 360/4 = 90 km/h.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"कार A को 360 km की दूरी तय करने में कार B से 2 घंटे अधिक लगते हैं। यदि A अपनी चाल दोगुनी कर ले, तो उसे B से 1 घंटा कम लगेगा। B की चाल क्या है?","optionsHi":["90 km/h","60 km/h","120 km/h","72 km/h"],"explanationHi":"मान लें A को x घंटे और B को y घंटे लगते हैं: x − y = 2 और y − x/2 = 1। इसलिए x/2 = 3, x = 6 और y = 4। B की चाल = 360/4 = 90 km/h।","subtopic":"late-early"},
  {"id":"quant-tsd-122","question":"A boat that moves at 15 km/h in still water goes 36 km upstream, halts for 1 hour and returns. The whole trip takes 6 hours. What is the speed of the stream?","options":["2 km/h","4 km/h","5 km/h","3 km/h"],"answer":3,"explanation":"Moving time = 5 h: 36/(15 − s) + 36/(15 + s) = 1,080/(225 − s²) = 5, so 225 − s² = 216 and s = 3 km/h.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"स्थिर जल में 15 km/h की चाल से चलने वाली एक नाव धारा के प्रतिकूल 36 km जाती है, 1 घंटा रुकती है और लौटती है। पूरी यात्रा में 6 घंटे लगते हैं। धारा की चाल क्या है?","optionsHi":["2 km/h","4 km/h","5 km/h","3 km/h"],"explanationHi":"चलने का समय = 5 घंटे: 36/(15 − s) + 36/(15 + s) = 1,080/(225 − s²) = 5, इसलिए 225 − s² = 216 और s = 3 km/h।","subtopic":"boats-streams"},
  {"id":"quant-tsd-123","question":"Train P passes a pole in 9 seconds and train Q in 12 seconds. Running in opposite directions, they cross each other in 10.5 seconds. What is the ratio of their speeds?","options":["4 : 3","3 : 4","1 : 1","3 : 2"],"answer":2,"explanation":"Lengths are 9a and 12b. (9a + 12b)/(a + b) = 10.5 gives 1.5b = 1.5a, so a = b. Their speeds are equal; only the lengths differ.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"रेलगाड़ी P एक खंभे को 9 सेकंड में और रेलगाड़ी Q 12 सेकंड में पार करती है। विपरीत दिशाओं में चलते हुए वे एक-दूसरे को 10.5 सेकंड में पार करती हैं। उनकी चालों का अनुपात क्या है?","optionsHi":["4 : 3","3 : 4","1 : 1","3 : 2"],"explanationHi":"लंबाइयाँ 9a और 12b हैं। (9a + 12b)/(a + b) = 10.5 से 1.5b = 1.5a, इसलिए a = b। उनकी चालें बराबर हैं; केवल लंबाइयाँ भिन्न हैं।","subtopic":"trains"},
  {"id":"quant-tsd-124","question":"A train leaves X at 6 am and reaches Y at 12 noon. Another train leaves Y at 8 am and reaches X at 11 am. At what time do they meet?","options":["9:00 am","9:40 am","9:20 am","10:00 am"],"answer":2,"explanation":"Speeds are D/6 and D/3. By 8 am the first train has done D/3, leaving 2D/3, closed at D/6 + D/3 = D/2 per hour: 4/3 h = 1 h 20 min. They meet at 9:20 am.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"एक रेलगाड़ी X से सुबह 6 बजे चलकर Y पर दोपहर 12 बजे पहुँचती है। दूसरी रेलगाड़ी Y से सुबह 8 बजे चलकर X पर सुबह 11 बजे पहुँचती है। वे किस समय मिलती हैं?","optionsHi":["सुबह 9:00 बजे","सुबह 9:40 बजे","सुबह 9:20 बजे","सुबह 10:00 बजे"],"explanationHi":"चालें D/6 और D/3 हैं। सुबह 8 बजे तक पहली रेलगाड़ी D/3 चल चुकी होती है, शेष 2D/3 है, जो D/6 + D/3 = D/2 प्रति घंटा की दर से कम होता है: 4/3 घंटा = 1 घंटा 20 मिनट। वे सुबह 9:20 बजे मिलती हैं।","subtopic":"relative-speed"},
  {"id":"quant-tsd-125","question":"A and B start at the same time from P and Q towards each other. After meeting, A takes 4 hours to reach Q and B takes 9 hours to reach P. If A's speed is 36 km/h, how far apart are P and Q?","options":["300 km","360 km","324 km","216 km"],"answer":1,"explanation":"Speeds are in the ratio √9 : √4 = 3 : 2, so B = 24 km/h. Time to meet = √(4 × 9) = 6 h. PQ = 6 × (36 + 24) = 360 km.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"A और B एक ही समय P और Q से एक-दूसरे की ओर चलना शुरू करते हैं। मिलने के बाद A को Q पहुँचने में 4 घंटे और B को P पहुँचने में 9 घंटे लगते हैं। यदि A की चाल 36 km/h है, तो P और Q के बीच की दूरी कितनी है?","optionsHi":["300 km","360 km","324 km","216 km"],"explanationHi":"चालों का अनुपात √9 : √4 = 3 : 2 है, इसलिए B = 24 km/h। मिलने का समय = √(4 × 9) = 6 घंटे। PQ = 6 × (36 + 24) = 360 km।","subtopic":"relative-speed"},
  {"id":"quant-tsd-126","question":"On a 2 km circular track, A runs three times as fast as B in the same direction, both starting together from the same point. By the time A completes 6 rounds, how many times has he overtaken B?","options":["4","6","2","3"],"answer":0,"explanation":"When A runs 6 rounds, B runs 2. A overtakes B once for every extra lap he gains: 6 − 2 = 4 times.","difficulty":"very-hard","source":"SSC CGL · CAT-style","questionHi":"2 km की वृत्ताकार पटरी पर A, B से तीन गुना तेज़ उसी दिशा में दौड़ता है, दोनों एक ही बिंदु से एक साथ शुरू करते हैं। जब तक A 6 चक्कर पूरे करता है, वह B को कितनी बार पार कर चुका होता है?","optionsHi":["4","6","2","3"],"explanationHi":"जब A 6 चक्कर दौड़ता है, B 2 दौड़ता है। A जितने अतिरिक्त चक्कर बढ़ाता है उतनी बार B को पार करता है: 6 − 2 = 4 बार।","subtopic":"circular-track"},
  {"id":"quant-tsd-127","question":"A train is held up for 30 minutes at a station. To arrive on time, it raises its speed by 10 km/h for the remaining 150 km. What was its original speed?","options":["60 km/h","40 km/h","45 km/h","50 km/h"],"answer":3,"explanation":"150/v − 150/(v + 10) = 1/2 gives v(v + 10) = 3,000, so v = 50 km/h.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"एक रेलगाड़ी किसी स्टेशन पर 30 मिनट रोक ली जाती है। समय पर पहुँचने के लिए वह शेष 150 km में अपनी चाल 10 km/h बढ़ा देती है। उसकी मूल चाल क्या थी?","optionsHi":["60 km/h","40 km/h","45 km/h","50 km/h"],"explanationHi":"150/v − 150/(v + 10) = 1/2 से v(v + 10) = 3,000, इसलिए v = 50 km/h।","subtopic":"late-early"},
  {"id":"quant-tsd-128","question":"Because of a signal problem a train runs at 20% below its usual speed and reaches 18 minutes late on a 120 km run. What is its usual speed?","options":["80 km/h","120 km/h","96 km/h","100 km/h"],"answer":3,"explanation":"At 80% speed the time is 1.25 times usual, so 0.25 × usual time = 18 min and usual time = 72 min = 1.2 h. Speed = 120/1.2 = 100 km/h.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"सिग्नल की समस्या के कारण एक रेलगाड़ी अपनी सामान्य चाल से 20% कम चाल पर चलती है और 120 km की यात्रा में 18 मिनट देर से पहुँचती है। उसकी सामान्य चाल क्या है?","optionsHi":["80 km/h","120 km/h","96 km/h","100 km/h"],"explanationHi":"80% चाल पर समय सामान्य का 1.25 गुना होता है, इसलिए 0.25 × सामान्य समय = 18 मिनट और सामान्य समय = 72 मिनट = 1.2 घंटे। चाल = 120/1.2 = 100 km/h।","subtopic":"late-early"},
  {"id":"quant-tsd-129","question":"A boatman rows 12 km downstream and back in 3 hours 12 minutes. If the stream flows at 2 km/h, what is his speed in still water?","options":["6 km/h","10 km/h","8 km/h","9 km/h"],"answer":2,"explanation":"12/(b + 2) + 12/(b − 2) = 3.2. Trying b = 8: 12/10 + 12/6 = 1.2 + 2 = 3.2 ✓.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक नाविक 12 km धारा के अनुकूल जाकर वापस आने में 3 घंटे 12 मिनट लेता है। यदि धारा 2 km/h की चाल से बहती है, तो स्थिर जल में उसकी चाल क्या है?","optionsHi":["6 km/h","10 km/h","8 km/h","9 km/h"],"explanationHi":"12/(b + 2) + 12/(b − 2) = 3.2। b = 8 आज़माने पर: 12/10 + 12/6 = 1.2 + 2 = 3.2 ✓।","subtopic":"boats-streams"},
  {"id":"quant-tsd-130","question":"Two friends set out together from P for Q, 24 km away, at 4 km/h and 6 km/h. The faster one reaches Q, turns back at once and meets the other. How far from Q do they meet?","options":["4 km","4.8 km","6 km","5.2 km"],"answer":1,"explanation":"Together they cover 2 × 24 = 48 km by the meeting, at 10 km/h combined: 4.8 hours. The slower one has walked 19.2 km, so they meet 4.8 km from Q.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"दो मित्र P से Q के लिए, जो 24 km दूर है, एक साथ क्रमशः 4 km/h और 6 km/h की चाल से चलते हैं। तेज़ चलने वाला Q पहुँचकर तुरंत लौटता है और दूसरे से मिलता है। वे Q से कितनी दूरी पर मिलते हैं?","optionsHi":["4 km","4.8 km","6 km","5.2 km"],"explanationHi":"मिलने तक वे साथ में 2 × 24 = 48 km तय करते हैं, संयुक्त चाल 10 km/h पर: 4.8 घंटे। धीमा 19.2 km चल चुका होता है, इसलिए वे Q से 4.8 km पर मिलते हैं।","subtopic":"late-early"},
  {"id":"quant-tsd-131","question":"Two cars start together from the same point on a 6 km circular track and run in the same direction at 36 km/h and 54 km/h. How many times does the faster car pass the slower one in 2 hours?","options":["6","5","18","3"],"answer":0,"explanation":"The faster car gains 18 km/h, i.e. 36 km in 2 hours = 6 laps of the track. Each lap gained is one pass, so 6 times.","difficulty":"very-hard","source":"SSC CGL · CAT-style","questionHi":"दो कारें 6 km की वृत्ताकार पटरी पर एक ही बिंदु से एक साथ एक ही दिशा में 36 km/h और 54 km/h की चाल से चलना शुरू करती हैं। 2 घंटे में तेज़ कार धीमी को कितनी बार पार करती है?","optionsHi":["6","5","18","3"],"explanationHi":"तेज़ कार 18 km/h की बढ़त बनाती है, यानी 2 घंटे में 36 km = पटरी के 6 चक्कर। प्रत्येक बढ़ा हुआ चक्कर एक बार पार करना है, इसलिए 6 बार।","subtopic":"circular-track"},
  {"id":"quant-tsd-132","question":"On a 400 m track, A runs at 8 m/s and B at 5 m/s in the same direction, starting together. How far has B run when A laps him for the first time?","options":["666.67 m","400 m","1,066.67 m","500 m"],"answer":0,"explanation":"A gains 3 m/s and needs 400 m to lap B: 400/3 s. B runs 5 × 400/3 ≈ 666.67 m in that time.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"400 m की पटरी पर A 8 m/s और B 5 m/s की चाल से एक ही दिशा में एक साथ दौड़ना शुरू करते हैं। जब A पहली बार B को एक पूरा चक्कर पीछे छोड़ता है, तब तक B कितनी दूर दौड़ चुका होता है?","optionsHi":["666.67 m","400 m","1,066.67 m","500 m"],"explanationHi":"A 3 m/s की बढ़त बनाता है और B से एक चक्कर आगे होने के लिए उसे 400 m चाहिए: 400/3 s। उस समय में B 5 × 400/3 ≈ 666.67 m दौड़ता है।","subtopic":"circular-track"},
  {"id":"quant-tsd-133","question":"A river is 300 m wide and flows at 3 km/h. A swimmer who swims at 5 km/h in still water heads straight across. How far downstream does he land?","options":["300 m","500 m","240 m","180 m"],"answer":3,"explanation":"Crossing time = 0.3 km ÷ 5 km/h = 0.06 h. In that time the current carries him 3 × 0.06 = 0.18 km = 180 m downstream.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"एक नदी 300 m चौड़ी है और 3 km/h की चाल से बहती है। स्थिर जल में 5 km/h की चाल से तैरने वाला एक तैराक सीधे सामने की ओर तैरता है। वह धारा की दिशा में कितनी दूर उतरता है?","optionsHi":["300 m","500 m","240 m","180 m"],"explanationHi":"पार करने का समय = 0.3 km ÷ 5 km/h = 0.06 घंटा। उस समय में धारा उसे धारा की दिशा में 3 × 0.06 = 0.18 km = 180 m बहा ले जाती है।","subtopic":"boats-streams"},
  {"id":"quant-tsd-134","question":"In a 200 m race, A can give B a start of 20 m and C a start of 32 m. How much start can B give C over 200 m?","options":["12 m","14 m","13.33 m","10.67 m"],"answer":2,"explanation":"While A runs 200, B runs 180 and C 168. So when B runs 200, C runs 200 × 168/180 = 186.67 m. B can give C about 13.33 m.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"200 m की दौड़ में A, B को 20 m की और C को 32 m की बढ़त दे सकता है। 200 m में B, C को कितनी बढ़त दे सकता है?","optionsHi":["12 m","14 m","13.33 m","10.67 m"],"explanationHi":"जब A 200 दौड़ता है, तब B 180 और C 168 दौड़ता है। इसलिए जब B 200 दौड़ता है, C 200 × 168/180 = 186.67 m दौड़ता है। B, C को लगभग 13.33 m की बढ़त दे सकता है।","subtopic":"circular-track"},
  {"id":"quant-tsd-135","question":"A car's wheel has a radius of 35 cm and turns 600 times a minute. What is the car's speed? (Take π = 22/7.)","options":["39.6 km/h","79.2 km/h","132 km/h","75.6 km/h"],"answer":1,"explanation":"Circumference = 2 × 22/7 × 0.35 = 2.2 m. Distance per minute = 2.2 × 600 = 1,320 m = 79.2 km/h.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"एक कार के पहिये की त्रिज्या 35 cm है और वह प्रति मिनट 600 चक्कर लगाता है। कार की चाल क्या है? (π = 22/7 लें।)","optionsHi":["39.6 km/h","79.2 km/h","132 km/h","75.6 km/h"],"explanationHi":"परिधि = 2 × 22/7 × 0.35 = 2.2 m। प्रति मिनट दूरी = 2.2 × 600 = 1,320 m = 79.2 km/h।","subtopic":"basic-speed"},
  {"id":"quant-tsd-136","question":"A car covers three equal stretches of a road at 30 km/h, 40 km/h and 60 km/h. What is its average speed for the whole journey?","options":["43.33 km/h","45 km/h","37.5 km/h","40 km/h"],"answer":3,"explanation":"For equal distances use the harmonic mean: 3/(1/30 + 1/40 + 1/60) = 3/(9/120) = 40 km/h. 43.33 is the plain average, which would be right only for equal times.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कार किसी सड़क के तीन बराबर खंड 30 km/h, 40 km/h और 60 km/h की चाल से तय करती है। पूरी यात्रा के लिए उसकी औसत चाल क्या है?","optionsHi":["43.33 km/h","45 km/h","37.5 km/h","40 km/h"],"explanationHi":"समान दूरियों के लिए हरात्मक माध्य लें: 3/(1/30 + 1/40 + 1/60) = 3/(9/120) = 40 km/h। 43.33 साधारण औसत है, जो केवल समान समयों के लिए सही होता।","subtopic":"average-speed"},
  {"id":"quant-tsd-137","question":"A 240 m train passes a pole in 12 seconds. How long will it take to cross a 360 m train coming the other way at 54 km/h?","options":["120 s","17.14 s","30 s","10.29 s"],"answer":1,"explanation":"Speed = 20 m/s; the other train does 15 m/s, so the relative speed is 35 m/s and the distance is 240 + 360 = 600 m: 600/35 = 17.14 s. Using 20 − 15 gives 120 s; using only 360 m gives 10.29 s.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"240 m लंबी एक रेलगाड़ी एक खंभे को 12 सेकंड में पार करती है। विपरीत दिशा से 54 km/h की चाल से आती 360 m लंबी रेलगाड़ी को पार करने में उसे कितना समय लगेगा?","optionsHi":["120 s","17.14 s","30 s","10.29 s"],"explanationHi":"चाल = 20 m/s; दूसरी रेलगाड़ी 15 m/s से चलती है, इसलिए सापेक्ष चाल 35 m/s और दूरी 240 + 360 = 600 m है: 600/35 = 17.14 s। 20 − 15 लेने पर 120 s आता है; केवल 360 m लेने पर 10.29 s।","subtopic":"trains"},
  {"id":"quant-tsd-138","question":"Train P leaves A at 7 am for B, 410 km away, at 50 km/h. Train Q leaves B at 8 am for A at 70 km/h. How far from A do they meet?","options":["170.83 km","150 km","200 km","210 km"],"answer":2,"explanation":"By 8 am P has done 50 km; the remaining 360 km closes at 120 km/h in 3 hours, so P has run 4 hours: 200 km from A. Ignoring P's head start gives 170.83 km; 210 km is Q's distance.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"रेलगाड़ी P सुबह 7 बजे A से B के लिए, जो 410 km दूर है, 50 km/h की चाल से चलती है। रेलगाड़ी Q सुबह 8 बजे B से A के लिए 70 km/h की चाल से चलती है। वे A से कितनी दूरी पर मिलती हैं?","optionsHi":["170.83 km","150 km","200 km","210 km"],"explanationHi":"सुबह 8 बजे तक P 50 km चल चुकी होती है; शेष 360 km 120 km/h की दर से 3 घंटे में कम होता है, इसलिए P कुल 4 घंटे चली: A से 200 km। P की बढ़त को अनदेखा करने पर 170.83 km आता है; 210 km Q की दूरी है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-139","question":"Two ports A and B are 68 km apart on a river that flows from A to B at 4 km/h. Boat P (12 km/h in still water) leaves A for B, and 30 minutes later boat Q (18 km/h in still water) leaves B for A. How far from A do they meet?","options":["28 km","32 km","34 km","40 km"],"answer":3,"explanation":"P goes downstream at 16 km/h and Q upstream at 14 km/h. In the first 30 minutes P covers 8 km; the remaining 60 km closes at 16 + 14 = 30 km/h in 2 hours, so they meet 8 + 32 = 40 km from A. 28 km is the distance from B, 32 km ignores P's head start, and 34 km is just the midpoint.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"एक नदी पर दो बंदरगाह A और B 68 km दूर हैं, और नदी A से B की ओर 4 km/h की चाल से बहती है। नाव P (शांत जल में 12 km/h) A से B के लिए चलती है, और 30 मिनट बाद नाव Q (शांत जल में 18 km/h) B से A के लिए चलती है। वे A से कितनी दूरी पर मिलेंगी?","optionsHi":["28 km","32 km","34 km","40 km"],"explanationHi":"P धारा के अनुकूल 16 km/h और Q धारा के प्रतिकूल 14 km/h से चलती है। पहले 30 मिनट में P 8 km चलती है; शेष 60 km की दूरी 16 + 14 = 30 km/h से 2 घंटे में तय होती है, अतः वे A से 8 + 32 = 40 km पर मिलती हैं। 28 km, B से दूरी है, 32 km में P की शुरुआती बढ़त छूट गई है, और 34 km केवल मध्य बिंदु है।","subtopic":"boats-streams"},
  {"id":"quant-tsd-140","question":"Walking at 5 km/h, a boy reaches school 7 minutes late; walking at 6 km/h he is 5 minutes early. How far is the school?","options":["6 km","1 km","12 km","3 km"],"answer":0,"explanation":"The two times differ by 7 + 5 = 12 minutes = 1/5 h: d/5 − d/6 = d/30 = 1/5, so d = 6 km. Subtracting the minutes (7 − 5 = 2) gives 1 km.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"5 km/h की चाल से चलने पर एक लड़का विद्यालय 7 मिनट देर से पहुँचता है; 6 km/h की चाल से चलने पर वह 5 मिनट पहले पहुँचता है। विद्यालय कितनी दूर है?","optionsHi":["6 km","1 km","12 km","3 km"],"explanationHi":"दोनों समयों में 7 + 5 = 12 मिनट = 1/5 घंटे का अंतर है: d/5 − d/6 = d/30 = 1/5, इसलिए d = 6 km। मिनटों को घटाने (7 − 5 = 2) पर 1 km आता है।","subtopic":"late-early"},
  {"id":"quant-tsd-141","question":"Two runners start together from the same point on a circular track and run in opposite directions at 6 m/s and 4 m/s. If they keep running, at how many distinct points on the track will they meet?","options":["5","1","2","6"],"answer":0,"explanation":"With speeds in the ratio 3 : 2 (in lowest terms), runners moving in opposite directions meet at 3 + 2 = 5 distinct points. The same-direction rule (3 − 2 = 1) gives 1.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"दो धावक एक वृत्ताकार पटरी पर एक ही बिंदु से एक साथ विपरीत दिशाओं में 6 m/s और 4 m/s की चाल से दौड़ना शुरू करते हैं। यदि वे दौड़ते रहें, तो पटरी पर कितने भिन्न बिंदुओं पर मिलेंगे?","optionsHi":["5","1","2","6"],"explanationHi":"चालों का अनुपात 3 : 2 (सरलतम रूप में) होने पर विपरीत दिशाओं में दौड़ने वाले 3 + 2 = 5 भिन्न बिंदुओं पर मिलते हैं। एक ही दिशा का नियम (3 − 2 = 1) 1 देता है।","subtopic":"circular-track"},
  {"id":"quant-tsd-142","question":"In a 1,500 m race A beats B by 150 m, and in a 1,500 m race B beats C by 75 m. By how much would A beat C in a 1,500 m race?","options":["225 m","233.33 m","217.5 m","75 m"],"answer":2,"explanation":"When A finishes, B has run 1,350 m; C runs 1,425 m for every 1,500 m of B, so C has run 1,350 × 1,425/1,500 = 1,282.5 m. A wins by 217.5 m. Adding 150 + 75 ignores that B's lead over C is per 1,500 m, not 1,350 m.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"1,500 m की दौड़ में A, B को 150 m से हराता है, और 1,500 m की दौड़ में B, C को 75 m से हराता है। 1,500 m की दौड़ में A, C को कितने से हराएगा?","optionsHi":["225 m","233.33 m","217.5 m","75 m"],"explanationHi":"जब A पूरा करता है, B 1,350 m दौड़ चुका होता है; B के प्रत्येक 1,500 m पर C 1,425 m दौड़ता है, इसलिए C 1,350 × 1,425/1,500 = 1,282.5 m दौड़ा है। A 217.5 m से जीतता है। 150 + 75 जोड़ना इस बात को अनदेखा करता है कि C पर B की बढ़त प्रति 1,500 m है, 1,350 m नहीं।","subtopic":"circular-track"},
  {"id":"quant-tsd-143","question":"A walks up a moving up-escalator and takes 20 steps to reach the top. B, walking twice as fast as A, takes 32 steps. How many steps are visible on the escalator when it is stopped?","options":["52","64","80","96"],"answer":2,"explanation":"If the escalator moves e steps per step-time of A: N = 20 + 20e. B takes 32 steps in 16 of A's step-times, so N = 32 + 16e. Then e = 3 and N = 80. Adding the two counts (52) has no basis.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"A चलती हुई ऊपर जाने वाली एस्केलेटर पर चढ़ता है और ऊपर पहुँचने तक 20 सीढ़ियाँ गिनता है। B, जो A से दोगुना तेज़ चलता है, 32 सीढ़ियाँ गिनता है। एस्केलेटर बंद होने पर उसमें कितनी सीढ़ियाँ दिखाई देती हैं?","optionsHi":["52","64","80","96"],"explanationHi":"यदि A के प्रति सीढ़ी-समय में एस्केलेटर e सीढ़ियाँ चलती है: N = 20 + 20e। B 32 सीढ़ियाँ A के 16 सीढ़ी-समयों में चलता है, इसलिए N = 32 + 16e। तब e = 3 और N = 80। दोनों गिनतियों को जोड़ने (52) का कोई आधार नहीं है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-144","question":"Two trains, 180 m and 220 m long, run in the same direction on parallel tracks at 72 km/h and 54 km/h. How long does the faster train take to pass the slower one completely?","options":["11.43 s","36 s","44 s","80 s"],"answer":3,"explanation":"Relative speed = 18 km/h = 5 m/s and the distance is 180 + 220 = 400 m, so 80 s. Adding the speeds (opposite directions) gives 11.43 s; using one length only gives 36 or 44 s.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"180 m और 220 m लंबी दो रेलगाड़ियाँ समानांतर पटरियों पर एक ही दिशा में 72 km/h और 54 km/h की चाल से चल रही हैं। तेज़ रेलगाड़ी को धीमी को पूरी तरह पार करने में कितना समय लगता है?","optionsHi":["11.43 s","36 s","44 s","80 s"],"explanationHi":"सापेक्ष चाल = 18 km/h = 5 m/s और दूरी 180 + 220 = 400 m है, इसलिए 80 s। चालें जोड़ने (विपरीत दिशाओं) पर 11.43 s आता है; केवल एक लंबाई लेने पर 36 या 44 s।","subtopic":"trains"},
  {"id":"quant-tsd-145","question":"A policeman spots a thief 200 m ahead. The thief runs at 10 km/h and the policeman chases at 12 km/h. How far does the thief run before he is caught?","options":["1.2 km","1 km","90.9 m","0.2 km"],"answer":1,"explanation":"The gap closes at 2 km/h, so 0.2 km takes 0.1 h, in which the thief runs 1 km. 1.2 km is the policeman's run; adding the speeds (22 km/h) gives 90.9 m.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक पुलिसकर्मी एक चोर को 200 m आगे देखता है। चोर 10 km/h की चाल से भागता है और पुलिसकर्मी 12 km/h की चाल से पीछा करता है। पकड़े जाने से पहले चोर कितनी दूर भागता है?","optionsHi":["1.2 km","1 km","90.9 m","0.2 km"],"explanationHi":"अंतर 2 km/h की दर से कम होता है, इसलिए 0.2 km में 0.1 घंटा लगता है, जिसमें चोर 1 km भागता है। 1.2 km पुलिसकर्मी की दौड़ है; चालें जोड़ने (22 km/h) पर 90.9 m आता है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-146","question":"A man rows 60 km downstream and back in 16 hours. He can row 5 km downstream in the same time as 3 km upstream. What is his rowing speed in still water?","options":["2 km/h","10 km/h","7.5 km/h","8 km/h"],"answer":3,"explanation":"Downstream : upstream = 5 : 3, say 5k and 3k: 60/5k + 60/3k = 32/k = 16, so k = 2: speeds 10 and 6. Still water = 8 km/h, stream = 2. 7.5 is 120/16, which is not a speed in still water.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक आदमी 60 km धारा के अनुकूल जाकर वापस आने में 16 घंटे लेता है। वह धारा के अनुकूल 5 km उतने समय में नाव चला सकता है जितने में धारा के प्रतिकूल 3 km। स्थिर जल में उसकी नाव चलाने की चाल क्या है?","optionsHi":["2 km/h","10 km/h","7.5 km/h","8 km/h"],"explanationHi":"अनुकूल : प्रतिकूल = 5 : 3, मान लें 5k और 3k: 60/5k + 60/3k = 32/k = 16, इसलिए k = 2: चालें 10 और 6। स्थिर जल में = 8 km/h, धारा = 2। 7.5 = 120/16 है, जो स्थिर जल में चाल नहीं है।","subtopic":"boats-streams"},
  {"id":"quant-tsd-147","question":"Two trains start at the same time from P and Q towards each other. After they pass each other, they take 16 hours and 9 hours respectively to reach their destinations. How long after starting did they meet?","options":["12.5 hours","7 hours","25 hours","12 hours"],"answer":3,"explanation":"If they meet after t hours, t² = 16 × 9 (each train covers in t hours what the other covers after meeting), so t = 12. 12.5 is the plain average.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"दो रेलगाड़ियाँ एक ही समय P और Q से एक-दूसरे की ओर चलना शुरू करती हैं। एक-दूसरे को पार करने के बाद वे अपने गंतव्य तक पहुँचने में क्रमशः 16 घंटे और 9 घंटे लेती हैं। चलने के कितने समय बाद वे मिली थीं?","optionsHi":["12.5 घंटे","7 घंटे","25 घंटे","12 घंटे"],"explanationHi":"यदि वे t घंटे बाद मिलती हैं, तो t² = 16 × 9 (प्रत्येक रेलगाड़ी t घंटे में उतना तय करती है जितना दूसरी मिलने के बाद), इसलिए t = 12। 12.5 साधारण औसत है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-148","question":"A train passes a man walking at 6 km/h in the same direction in 18 seconds, and a man walking at 4 km/h towards it in 12 seconds. How long is the train?","options":["100 m","130 m","20 m","150 m"],"answer":0,"explanation":"(v − 6) × 18 = (v + 4) × 12 gives v = 26 km/h; length = 20 km/h × 18 s = (50/9) × 18 = 100 m. Taking both men as walking the same way gives 20 m; ignoring the man's speed gives 130 m.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक रेलगाड़ी उसी दिशा में 6 km/h की चाल से चलते एक आदमी को 18 सेकंड में और अपनी ओर 4 km/h की चाल से आते एक आदमी को 12 सेकंड में पार करती है। रेलगाड़ी कितनी लंबी है?","optionsHi":["100 m","130 m","20 m","150 m"],"explanationHi":"(v − 6) × 18 = (v + 4) × 12 से v = 26 km/h; लंबाई = 20 km/h × 18 s = (50/9) × 18 = 100 m। दोनों आदमियों को एक ही दिशा में चलता मानने पर 20 m आता है; आदमी की चाल को अनदेखा करने पर 130 m।","subtopic":"trains"},
  {"id":"quant-tsd-149","question":"Walking at 5/6 of his usual speed, a man reaches his office 12 minutes late. What is his usual time for the journey?","options":["72 minutes","120 minutes","30 minutes","60 minutes"],"answer":3,"explanation":"At 5/6 the speed the time becomes 6/5 of usual, so the extra 1/5 of the time = 12 minutes and the usual time is 60 minutes. Taking the extra as 1/6 gives 72 minutes, which is the new time, not the usual one.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"अपनी सामान्य चाल की 5/6 चाल से चलने पर एक आदमी कार्यालय 12 मिनट देर से पहुँचता है। यात्रा के लिए उसका सामान्य समय क्या है?","optionsHi":["72 मिनट","120 मिनट","30 मिनट","60 मिनट"],"explanationHi":"5/6 चाल पर समय सामान्य का 6/5 हो जाता है, इसलिए अतिरिक्त 1/5 समय = 12 मिनट और सामान्य समय 60 मिनट है। अतिरिक्त को 1/6 मानने पर 72 मिनट आता है, जो नया समय है, सामान्य नहीं।","subtopic":"late-early"},
  {"id":"quant-tsd-150","question":"A boat takes 2.5 times as long to go upstream as to go the same distance downstream. If the stream flows at 4.5 km/h, what is the boat's speed in still water?","options":["10.5 km/h","11.25 km/h","15.75 km/h","6 km/h"],"answer":0,"explanation":"Downstream speed = 2.5 × upstream: b + 4.5 = 2.5(b − 4.5), so 1.5b = 15.75 and b = 10.5 km/h. 15.75 is 1.5b, a step short; 11.25 is just 4.5 × 2.5.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक नाव को धारा के प्रतिकूल जाने में उतनी ही दूरी धारा के अनुकूल जाने से 2.5 गुना समय लगता है। यदि धारा 4.5 km/h की चाल से बहती है, तो स्थिर जल में नाव की चाल क्या है?","optionsHi":["10.5 km/h","11.25 km/h","15.75 km/h","6 km/h"],"explanationHi":"अनुकूल चाल = 2.5 × प्रतिकूल: b + 4.5 = 2.5(b − 4.5), इसलिए 1.5b = 15.75 और b = 10.5 km/h। 15.75 = 1.5b है, एक चरण पहले की स्थिति; 11.25 केवल 4.5 × 2.5 है।","subtopic":"boats-streams"},
  {"id":"quant-tsd-151","question":"A bus goes 120 km at 60 km/h, halts for 30 minutes and returns at 40 km/h. What is its average speed for the whole trip, including the halt?","options":["43.64 km/h","48 km/h","50 km/h","41.38 km/h"],"answer":0,"explanation":"Total time = 2 + 0.5 + 3 = 5.5 h for 240 km, so 43.64 km/h. 48 is the round-trip harmonic mean that ignores the halt; 50 is the plain average.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक बस 60 km/h की चाल से 120 km जाती है, 30 मिनट रुकती है और 40 km/h की चाल से लौटती है। ठहराव सहित पूरी यात्रा की औसत चाल क्या है?","optionsHi":["43.64 km/h","48 km/h","50 km/h","41.38 km/h"],"explanationHi":"कुल समय = 2 + 0.5 + 3 = 5.5 घंटे में 240 km, इसलिए 43.64 km/h। 48 आने-जाने का हरात्मक माध्य है जो ठहराव को अनदेखा करता है; 50 साधारण औसत है।","subtopic":"average-speed"},
  {"id":"quant-tsd-152","question":"Two trains of equal length run in the same direction at 60 km/h and 42 km/h. The faster train passes the slower one in 40 seconds. How long is each train?","options":["200 m","566.67 m","100 m","50 m"],"answer":2,"explanation":"Relative speed = 18 km/h = 5 m/s, so in 40 s it covers 200 m, the sum of the two lengths: each is 100 m. 200 m forgets to split; adding the speeds gives 566.67 m.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"समान लंबाई की दो रेलगाड़ियाँ एक ही दिशा में 60 km/h और 42 km/h की चाल से चलती हैं। तेज़ रेलगाड़ी धीमी को 40 सेकंड में पार करती है। प्रत्येक रेलगाड़ी कितनी लंबी है?","optionsHi":["200 m","566.67 m","100 m","50 m"],"explanationHi":"सापेक्ष चाल = 18 km/h = 5 m/s, इसलिए 40 s में वह 200 m तय करती है, जो दोनों लंबाइयों का योग है: प्रत्येक 100 m है। 200 m बाँटना भूलना है; चालें जोड़ने पर 566.67 m आता है।","subtopic":"trains"},
  {"id":"quant-tsd-153","question":"A car runs from P to Q at 60 km/h. Had it gone 20% faster, it would have arrived 25 minutes earlier. How far is Q from P?","options":["125 km","180 km","150 km","300 km"],"answer":2,"explanation":"At 1.2 times the speed the time is 5/6 of usual, so the saving T/6 = 25 min and T = 150 min = 2.5 h; distance = 150 km. Taking the saving as 20% of T gives 125 km.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कार P से Q तक 60 km/h की चाल से जाती है। यदि वह 20% तेज़ चलती, तो 25 मिनट पहले पहुँचती। Q, P से कितनी दूर है?","optionsHi":["125 km","180 km","150 km","300 km"],"explanationHi":"1.2 गुना चाल पर समय सामान्य का 5/6 होता है, इसलिए बचत T/6 = 25 मिनट और T = 150 मिनट = 2.5 घंटे; दूरी = 150 km। बचत को T का 20% मानने पर 125 km आता है।","subtopic":"late-early"},
  {"id":"quant-tsd-154","question":"After 1 hour of its journey a train has an accident and continues at 3/5 of its speed, reaching 2 hours late. Had the accident happened 50 km further on, it would have been only 40 minutes late. What was its original speed?","options":["15 km/h","37.5 km/h","25 km/h","50 km/h"],"answer":2,"explanation":"At 3/5 speed each km takes 5/3 as long, so the delay is (2/3) × (distance after the accident)/v. The 50 km shift saves 80 minutes: (2/3)(50/v) = 4/3, so v = 25 km/h. Using 2/5 instead of 2/3 for the extra time gives 15 km/h.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"यात्रा के 1 घंटे बाद एक रेलगाड़ी की दुर्घटना हो जाती है और वह अपनी चाल की 3/5 चाल से चलती है, जिससे वह 2 घंटे देर से पहुँचती है। यदि दुर्घटना 50 km और आगे होती, तो वह केवल 40 मिनट देर से पहुँचती। उसकी मूल चाल क्या थी?","optionsHi":["15 km/h","37.5 km/h","25 km/h","50 km/h"],"explanationHi":"3/5 चाल पर प्रत्येक km में 5/3 गुना समय लगता है, इसलिए देरी = (2/3) × (दुर्घटना के बाद की दूरी)/v। 50 km का खिसकना 80 मिनट बचाता है: (2/3)(50/v) = 4/3, इसलिए v = 25 km/h। अतिरिक्त समय के लिए 2/3 की जगह 2/5 लेने पर 15 km/h आता है।","subtopic":"late-early"},
  {"id":"quant-tsd-155","question":"Two cyclists start together from the same point on a 1.2 km circular track and ride in opposite directions at 18 km/h and 24 km/h. How many times do they meet in one hour, not counting the start?","options":["5","36","70","35"],"answer":3,"explanation":"Opposite directions: they close at 42 km/h, so they meet every 1.2 km of combined travel: 42/1.2 = 35 times. Same-direction thinking (6/1.2) gives 5; counting the start gives 36.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"दो साइकिल सवार 1.2 km की वृत्ताकार पटरी पर एक ही बिंदु से एक साथ विपरीत दिशाओं में 18 km/h और 24 km/h की चाल से चलना शुरू करते हैं। शुरुआत को गिने बिना, वे एक घंटे में कितनी बार मिलते हैं?","optionsHi":["5","36","70","35"],"explanationHi":"विपरीत दिशाओं में: वे 42 km/h की दर से पास आते हैं, इसलिए वे संयुक्त 1.2 km की यात्रा पर हर बार मिलते हैं: 42/1.2 = 35 बार। एक ही दिशा की सोच (6/1.2) 5 देती है; शुरुआत को गिनने पर 36।","subtopic":"circular-track"},
  {"id":"quant-tsd-156","question":"A 280 m train running at 63 km/h crosses a bridge in 32 seconds. How long is the bridge?","options":["560 m","280 m","840 m","1,736 m"],"answer":1,"explanation":"63 km/h = 17.5 m/s, so the train covers 560 m in 32 s, which is train + bridge: bridge = 280 m. 560 m forgets to subtract the train; 1,736 m skips the km/h-to-m/s conversion.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"63 km/h की चाल से चलती 280 m लंबी एक रेलगाड़ी एक पुल को 32 सेकंड में पार करती है। पुल कितना लंबा है?","optionsHi":["560 m","280 m","840 m","1,736 m"],"explanationHi":"63 km/h = 17.5 m/s, इसलिए रेलगाड़ी 32 s में 560 m चलती है, जो रेलगाड़ी + पुल है: पुल = 280 m। 560 m रेलगाड़ी की लंबाई घटाना भूलना है; 1,736 m में km/h से m/s का परिवर्तन छोड़ दिया गया है।","subtopic":"trains"},
  {"id":"quant-tsd-157","question":"A boat goes 30 km downstream in 1½ hours and returns in 2½ hours. How long would it take to row 18 km in still water?","options":["54 min","1 h 7.5 min","1 h 30 min","1 h 12 min"],"answer":1,"explanation":"Downstream 20 km/h, upstream 12 km/h, so still water = 16 km/h and 18 km takes 1.125 h = 1 h 7.5 min. 54 min uses the downstream speed and 1 h 30 min the upstream speed.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक नाव 30 km धारा के अनुकूल 1½ घंटे में जाती है और 2½ घंटे में लौटती है। स्थिर जल में 18 km नाव चलाने में उसे कितना समय लगेगा?","optionsHi":["54 मिनट","1 घंटा 7.5 मिनट","1 घंटा 30 मिनट","1 घंटा 12 मिनट"],"explanationHi":"अनुकूल 20 km/h, प्रतिकूल 12 km/h, इसलिए स्थिर जल में 16 km/h और 18 km में 1.125 घंटे = 1 घंटा 7.5 मिनट। 54 मिनट अनुकूल चाल और 1 घंटा 30 मिनट प्रतिकूल चाल लेने से आते हैं।","subtopic":"boats-streams"},
  {"id":"quant-tsd-158","question":"Two trains start at the same time from A and B towards each other at 54 km/h and 72 km/h. When they meet, the faster train has travelled 45 km more than the slower one. How far apart are A and B?","options":["315 km","135 km","180 km","270 km"],"answer":0,"explanation":"In equal time distances are in the speed ratio 3 : 4; the difference of 1 part is 45 km, so the total of 7 parts is 315 km. 135 km and 180 km are the slower and faster trains' shares.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"दो रेलगाड़ियाँ एक ही समय A और B से एक-दूसरे की ओर 54 km/h और 72 km/h की चाल से चलना शुरू करती हैं। मिलने पर तेज़ रेलगाड़ी ने धीमी से 45 km अधिक दूरी तय की होती है। A और B के बीच की दूरी कितनी है?","optionsHi":["315 km","135 km","180 km","270 km"],"explanationHi":"समान समय में दूरियाँ चालों के अनुपात 3 : 4 में होती हैं; 1 भाग का अंतर 45 km है, इसलिए कुल 7 भाग 315 km हैं। 135 km और 180 km क्रमशः धीमी और तेज़ रेलगाड़ी के हिस्से हैं।","subtopic":"relative-speed"},
  {"id":"quant-tsd-159","question":"A cyclist rides 12 km uphill at 8 km/h and comes back down the same road at 24 km/h. What is his average speed for the whole trip?","options":["12 km/h","14 km/h","16 km/h","18 km/h"],"answer":0,"explanation":"He takes 12/8 = 1.5 hours up and 12/24 = 0.5 hour down, so the average speed is 24 km ÷ 2 hours = 12 km/h, the same as 2 × 8 × 24/(8 + 24). 16 km/h is the simple average of the two speeds, which ignores the longer time spent climbing.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक साइकिल सवार 12 km की चढ़ाई 8 km/h से चढ़ता है और उसी रास्ते से 24 km/h से नीचे लौटता है। पूरी यात्रा में उसकी औसत चाल क्या है?","optionsHi":["12 km/h","14 km/h","16 km/h","18 km/h"],"explanationHi":"ऊपर जाने में 12/8 = 1.5 घंटे और नीचे आने में 12/24 = 0.5 घंटा लगता है, अतः औसत चाल = 24 km ÷ 2 घंटे = 12 km/h, जो 2 × 8 × 24/(8 + 24) के बराबर है। 16 km/h दोनों चालों का साधारण औसत है, जो चढ़ाई में लगे अधिक समय को अनदेखा करता है।","subtopic":"average-speed"},
  {"id":"quant-tsd-160","question":"A train crosses a 162 m platform in 15 seconds and a 250 m platform in 19 seconds. How long is the train?","options":["330 m","88 m","168 m","250 m"],"answer":2,"explanation":"The extra 88 m takes 4 s, so the speed is 22 m/s; in 15 s it covers 330 m = train + 162, so the train is 168 m. 330 m forgets to subtract the platform.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक रेलगाड़ी 162 m लंबे प्लेटफ़ॉर्म को 15 सेकंड में और 250 m लंबे प्लेटफ़ॉर्म को 19 सेकंड में पार करती है। रेलगाड़ी कितनी लंबी है?","optionsHi":["330 m","88 m","168 m","250 m"],"explanationHi":"अतिरिक्त 88 m में 4 s लगते हैं, इसलिए चाल 22 m/s है; 15 s में वह 330 m = रेलगाड़ी + 162 चलती है, इसलिए रेलगाड़ी 168 m है। 330 m प्लेटफ़ॉर्म घटाना भूलना है।","subtopic":"trains"},
  {"id":"quant-tsd-161","question":"A boat that rows at 8 km/h in still water makes a 24 km trip and back. How much longer does the round trip take when a 2 km/h stream flows than in still water?","options":["No extra time","48 minutes","24 minutes","36 minutes"],"answer":2,"explanation":"Still water: 48/8 = 6 h. With the stream: 24/10 + 24/6 = 6.4 h, so 24 minutes more. The gain downstream does not cancel the loss upstream, because more time is spent going slowly.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"स्थिर जल में 8 km/h की चाल से नाव चलाने वाली एक नाव 24 km जाकर वापस आती है। 2 km/h की धारा बहने पर आने-जाने की यात्रा में स्थिर जल की तुलना में कितना अधिक समय लगता है?","optionsHi":["कोई अतिरिक्त समय नहीं","48 मिनट","24 मिनट","36 मिनट"],"explanationHi":"स्थिर जल में: 48/8 = 6 घंटे। धारा के साथ: 24/10 + 24/6 = 6.4 घंटे, इसलिए 24 मिनट अधिक। धारा के अनुकूल का लाभ प्रतिकूल की हानि को निरस्त नहीं करता, क्योंकि धीमी चाल पर अधिक समय बीतता है।","subtopic":"boats-streams"},
  {"id":"quant-tsd-162","question":"A cyclist rides at 18 km/h but rests for 10 minutes after every 6 km. How long does he take to cover 30 km?","options":["2 h 30 min","1 h 40 min","2 h 40 min","2 h 20 min"],"answer":3,"explanation":"Riding takes 30/18 h = 100 minutes, and he rests after 6, 12, 18 and 24 km only (not at the finish): 40 minutes. Total 140 minutes. Counting a fifth rest at the finish gives 2 h 30 min.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक साइकिल सवार 18 km/h की चाल से चलता है, पर हर 6 km के बाद 10 मिनट आराम करता है। 30 km तय करने में उसे कितना समय लगता है?","optionsHi":["2 घंटे 30 मिनट","1 घंटा 40 मिनट","2 घंटे 40 मिनट","2 घंटे 20 मिनट"],"explanationHi":"चलने में 30/18 घंटा = 100 मिनट लगते हैं, और वह केवल 6, 12, 18 और 24 km के बाद आराम करता है (अंत में नहीं): 40 मिनट। कुल 140 मिनट। अंत में पाँचवाँ आराम गिनने पर 2 घंटे 30 मिनट आता है।","subtopic":"basic-speed"},
  {"id":"quant-tsd-163","question":"Two cars leave the same point at 9 am, one driving east at 40 km/h and the other north at 30 km/h. How far apart are they at 11:30 am?","options":["125 km","175 km","25 km","62.5 km"],"answer":0,"explanation":"In 2.5 h they go 100 km and 75 km at right angles, so the gap is √(100² + 75²) = 125 km. Adding the distances (175) treats them as going opposite ways.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"दो कारें सुबह 9 बजे एक ही बिंदु से चलती हैं, एक पूर्व की ओर 40 km/h की चाल से और दूसरी उत्तर की ओर 30 km/h की चाल से। सुबह 11:30 बजे वे एक-दूसरे से कितनी दूर हैं?","optionsHi":["125 km","175 km","25 km","62.5 km"],"explanationHi":"2.5 घंटे में वे लंब दिशाओं में 100 km और 75 km जाती हैं, इसलिए दूरी √(100² + 75²) = 125 km है। दूरियाँ जोड़ने (175) पर वे विपरीत दिशाओं में जाती मान ली जाती हैं।","subtopic":"relative-speed"},
  {"id":"quant-tsd-164","question":"A train overtakes two men walking in its direction at 4.5 km/h and 5.4 km/h in 8.4 seconds and 8.5 seconds respectively. How long is the train?","options":["189 m","178.5 m","191.25 m","172.13 m"],"answer":1,"explanation":"In m/s the men walk 1.25 and 1.5: (v − 1.25)8.4 = (v − 1.5)8.5 gives v = 22.5 m/s, so the length = 21.25 × 8.4 = 178.5 m. Ignoring the walker's speed gives 22.5 × 8.4 = 189 m.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"एक रेलगाड़ी अपनी ही दिशा में 4.5 km/h और 5.4 km/h की चाल से चलते दो आदमियों को क्रमशः 8.4 सेकंड और 8.5 सेकंड में पार करती है। रेलगाड़ी कितनी लंबी है?","optionsHi":["189 m","178.5 m","191.25 m","172.13 m"],"explanationHi":"m/s में आदमी 1.25 और 1.5 की चाल से चलते हैं: (v − 1.25)8.4 = (v − 1.5)8.5 से v = 22.5 m/s, इसलिए लंबाई = 21.25 × 8.4 = 178.5 m। चलने वाले की चाल को अनदेखा करने पर 22.5 × 8.4 = 189 m आता है।","subtopic":"trains"},
  {"id":"quant-tsd-165","question":"The speeds of A and B are in the ratio 3 : 4. A takes 20 minutes more than B to cover the same distance. How long does A take?","options":["60 minutes","80 minutes","140 minutes","26.67 minutes"],"answer":1,"explanation":"Times are in the inverse ratio 4 : 3, so the 1-part difference is 20 minutes and A takes 80 minutes. 60 minutes is B's time.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A और B की चालों का अनुपात 3 : 4 है। A को उतनी ही दूरी तय करने में B से 20 मिनट अधिक लगते हैं। A कितना समय लेता है?","optionsHi":["60 मिनट","80 मिनट","140 मिनट","26.67 मिनट"],"explanationHi":"समयों का अनुपात उलटा, 4 : 3 है, इसलिए 1 भाग का अंतर 20 मिनट है और A 80 मिनट लेता है। 60 मिनट B का समय है।","subtopic":"late-early"},
  {"id":"quant-tsd-166","question":"A train leaves Delhi at 10 am at 40 km/h. Another leaves Delhi at 2 pm on the same line in the same direction at 60 km/h. How far from Delhi will the second train catch the first?","options":["320 km","480 km","96 km","400 km"],"answer":1,"explanation":"The first train is 160 km ahead at 2 pm; the gap closes at 20 km/h in 8 hours, so they meet 60 × 8 = 480 km from Delhi. 320 km is how far the first train runs after 2 pm; adding the speeds gives 96 km.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक रेलगाड़ी दिल्ली से सुबह 10 बजे 40 km/h की चाल से चलती है। दूसरी रेलगाड़ी दिल्ली से दोपहर 2 बजे उसी लाइन पर उसी दिशा में 60 km/h की चाल से चलती है। दूसरी रेलगाड़ी पहली को दिल्ली से कितनी दूरी पर पकड़ेगी?","optionsHi":["320 km","480 km","96 km","400 km"],"explanationHi":"दोपहर 2 बजे पहली रेलगाड़ी 160 km आगे होती है; अंतर 20 km/h की दर से 8 घंटे में कम होता है, इसलिए वे दिल्ली से 60 × 8 = 480 km पर मिलती हैं। 320 km वह दूरी है जो पहली रेलगाड़ी दोपहर 2 बजे के बाद चलती है; चालें जोड़ने पर 96 km आता है।","subtopic":"relative-speed"},
  {"id":"quant-tsd-167","question":"Three runners start together from the same point of a 400 m circular track and run in the same direction at 6 m/s, 10 m/s and 13 m/s. After how long will all three be together again for the first time?","options":["1,200 seconds","200 seconds","100 seconds","400 seconds"],"answer":3,"explanation":"The first two meet every 400/4 = 100 s and the last two every 400/3 s, so we need the smallest t that is a multiple of both: 100a = (400/3)b gives a = 4, b = 3, so t = 400 s. 100 s is only the first two meeting.","difficulty":"very-hard","questionHi":"तीन धावक 400 m के एक वृत्ताकार पथ के एक ही बिंदु से साथ-साथ एक ही दिशा में क्रमशः 6 m/s, 10 m/s और 13 m/s की चाल से दौड़ना शुरू करते हैं। तीनों पहली बार दोबारा कितने समय बाद एक साथ होंगे?","optionsHi":["1,200 सेकंड","200 सेकंड","100 सेकंड","400 सेकंड"],"explanationHi":"पहले दो धावक हर 400/4 = 100 s में और अंतिम दो हर 400/3 s में मिलते हैं, इसलिए दोनों का सबसे छोटा उभयनिष्ठ गुणज चाहिए: 100a = (400/3)b से a = 4, b = 3, अतः t = 400 s। 100 s केवल पहले दो के मिलने का समय है।","subtopic":"circular-track","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-168","question":"Two persons start from the same point of a 600 m circular track and walk in opposite directions at 4 m/s and 6 m/s. How many times do they meet in 20 minutes 30 seconds, not counting the start?","options":["21","20","19","22"],"answer":1,"explanation":"In opposite directions they close at 10 m/s, so they meet every 600/10 = 60 s. In 1,230 s the number of meetings is ⌊1,230/60⌋ = 20.","difficulty":"hard","questionHi":"दो व्यक्ति 600 m के एक वृत्ताकार पथ के एक ही बिंदु से विपरीत दिशाओं में क्रमशः 4 m/s और 6 m/s की चाल से चलना शुरू करते हैं। प्रारंभ को न गिनते हुए, 20 मिनट 30 सेकंड में वे कितनी बार मिलेंगे?","optionsHi":["21","20","19","22"],"explanationHi":"विपरीत दिशाओं में वे 10 m/s की दर से पास आते हैं, इसलिए हर 600/10 = 60 s में मिलते हैं। 1,230 s में मिलनों की संख्या ⌊1,230/60⌋ = 20 है।","subtopic":"circular-track","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-169","question":"A and B run in the same direction on a 400 m circular track at 7 m/s and 4.5 m/s, starting from the same point. How many times does A overtake B in one hour?","options":["23","22","21","20"],"answer":1,"explanation":"A gains 2.5 m/s, so he overtakes B every 400/2.5 = 160 s. In 3,600 s that is 3,600/160 = 22.5, so A completes 22 overtakes.","difficulty":"hard","questionHi":"A और B एक 400 m के वृत्ताकार पथ पर एक ही बिंदु से एक ही दिशा में क्रमशः 7 m/s और 4.5 m/s की चाल से दौड़ना शुरू करते हैं। एक घंटे में A, B को कितनी बार पार करता है?","optionsHi":["23","22","21","20"],"explanationHi":"A, 2.5 m/s की दर से आगे निकलता है, इसलिए वह हर 400/2.5 = 160 s में B को पार करता है। 3,600 s में 3,600/160 = 22.5, अतः A 22 बार पार करता है।","subtopic":"circular-track","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-170","question":"Two cyclists start from the same point of a 1 km circular track in the same direction at 18 km/h and 30 km/h. After how long will they be together at the starting point for the first time?","options":["5 minutes","15 minutes","8 minutes","10 minutes"],"answer":3,"explanation":"Lap times are 1,000/5 = 200 s and 1,000/(25/3) = 120 s, and the LCM is 600 s = 10 minutes. They first meet anywhere after 1,000/(10/3) = 300 s, but not at the starting point.","difficulty":"very-hard","questionHi":"दो साइकिल सवार 1 km के एक वृत्ताकार पथ के एक ही बिंदु से एक ही दिशा में क्रमशः 18 km/h और 30 km/h की चाल से चलना शुरू करते हैं। वे पहली बार प्रारंभिक बिंदु पर एक साथ कितने समय बाद होंगे?","optionsHi":["5 मिनट","15 मिनट","8 मिनट","10 मिनट"],"explanationHi":"एक चक्कर का समय 1,000/5 = 200 s और 1,000/(25/3) = 120 s है, जिनका LCM 600 s = 10 मिनट है। वे पथ पर कहीं भी पहली बार 1,000/(10/3) = 300 s बाद मिलते हैं, पर प्रारंभिक बिंदु पर नहीं।","subtopic":"circular-track","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-171","question":"A and B start from the same point of a 720 m circular track and walk in opposite directions at 3 m/s and 5 m/s respectively. At what distance from the starting point, measured along A's path, do they meet for the first time?","options":["270 m","450 m","360 m","180 m"],"answer":0,"explanation":"They meet when together they cover 720 m: 720/8 = 90 s. In that time A walks 3 × 90 = 270 m (B walks 450 m, which is the same point measured the other way).","difficulty":"moderate","questionHi":"A और B एक 720 m के वृत्ताकार पथ के एक ही बिंदु से विपरीत दिशाओं में क्रमशः 3 m/s और 5 m/s की चाल से चलना शुरू करते हैं। A के पथ के अनुदिश मापने पर, वे पहली बार प्रारंभिक बिंदु से कितनी दूरी पर मिलते हैं?","optionsHi":["270 m","450 m","360 m","180 m"],"explanationHi":"वे तब मिलते हैं जब मिलकर 720 m चल लेते हैं: 720/8 = 90 s। इस समय में A, 3 × 90 = 270 m चलता है (B 450 m चलता है, जो दूसरी ओर से मापने पर वही बिंदु है)।","subtopic":"circular-track","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-172","question":"A runs twice as fast as B. They start together from the same point of a circular track and run in opposite directions until both are at the starting point together for the first time. How many times do they meet in all, counting the final meeting at the start but not the initial start?","options":["6","9","3","2"],"answer":2,"explanation":"Speeds are 2v and v. They are first together at the start when B has run 1 lap and A 2 laps. In opposite directions each meeting uses up one lap of combined distance, so the number of meetings is 2 + 1 = 3 (the third is at the start).","difficulty":"very-hard","questionHi":"A, B से दो गुनी चाल से दौड़ता है। वे एक वृत्ताकार पथ के एक ही बिंदु से साथ-साथ विपरीत दिशाओं में दौड़ना शुरू करते हैं और तब तक दौड़ते हैं जब तक दोनों पहली बार प्रारंभिक बिंदु पर एक साथ नहीं पहुँच जाते। प्रारंभ को न गिनकर, अंत में प्रारंभिक बिंदु पर हुए मिलन को गिनते हुए, वे कुल कितनी बार मिलते हैं?","optionsHi":["6","9","3","2"],"explanationHi":"चालें 2v और v हैं। वे प्रारंभिक बिंदु पर पहली बार तब साथ होते हैं जब B एक चक्कर और A दो चक्कर पूरे कर लेता है। विपरीत दिशा में प्रत्येक मिलन पर कुल दूरी का एक चक्कर पूरा होता है, इसलिए मिलनों की संख्या 2 + 1 = 3 है (तीसरा मिलन प्रारंभिक बिंदु पर होता है)।","subtopic":"circular-track","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-173","question":"Two runners start together from the same point of a circular track and run in the same direction with speeds in the ratio 7 : 4. Before both are together at the starting point for the first time, how many times does the faster runner overtake the slower one, counting the overtake at the starting point?","options":["4","7","3","11"],"answer":2,"explanation":"They are first together at the start when the faster has run 7 laps and the slower 4 laps. The faster gains 7 − 4 = 3 laps, and each overtake is one lap gained, so there are 3 overtakes (the last at the start).","difficulty":"hard","questionHi":"दो धावक एक वृत्ताकार पथ के एक ही बिंदु से साथ-साथ एक ही दिशा में 7 : 4 के अनुपात की चाल से दौड़ना शुरू करते हैं। दोनों के पहली बार प्रारंभिक बिंदु पर एक साथ होने तक, तेज धावक धीमे धावक को कितनी बार पार करता है, प्रारंभिक बिंदु पर पार करने को भी गिनते हुए?","optionsHi":["4","7","3","11"],"explanationHi":"वे प्रारंभिक बिंदु पर पहली बार तब साथ होते हैं जब तेज धावक 7 चक्कर और धीमा 4 चक्कर पूरे कर लेता है। तेज धावक 7 − 4 = 3 चक्कर आगे निकल जाता है और प्रत्येक बार पार करना एक चक्कर की बढ़त है, अतः 3 बार पार करता है (अंतिम प्रारंभिक बिंदु पर)।","subtopic":"circular-track","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-174","question":"A car covers three equal parts of a journey at 20 km/h, 30 km/h and 60 km/h respectively. What is its average speed for the whole journey?","options":["30 km/h","36⅔ km/h","33⅓ km/h","40 km/h"],"answer":0,"explanation":"For equal distances use the harmonic mean: 3/(1/20 + 1/30 + 1/60) = 3/(6/60) = 30 km/h. The plain average 36⅔ is the trap.","difficulty":"moderate","questionHi":"एक कार यात्रा के तीन बराबर भागों को क्रमशः 20 km/h, 30 km/h और 60 km/h की चाल से तय करती है। पूरी यात्रा में उसकी औसत चाल क्या है?","optionsHi":["30 km/h","36⅔ km/h","33⅓ km/h","40 km/h"],"explanationHi":"बराबर दूरियों के लिए हरात्मक माध्य लें: 3/(1/20 + 1/30 + 1/60) = 3/(6/60) = 30 km/h। साधारण औसत 36⅔ गलत जाल है।","subtopic":"average-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-175","question":"A man drives from P to Q at 60 km/h and returns along the same road at a speed such that his average speed for the whole round trip is 48 km/h. What is his speed on the return journey?","options":["36 km/h","42 km/h","30 km/h","40 km/h"],"answer":3,"explanation":"Average = 2xy/(x + y): 2 × 60 × y/(60 + y) = 48 gives 120y = 2,880 + 48y, so y = 40 km/h. The simple average of 60 and 36 would wrongly give 48.","difficulty":"hard","questionHi":"एक व्यक्ति P से Q तक 60 km/h की चाल से गाड़ी चलाता है और उसी मार्ग से इतनी चाल से लौटता है कि पूरी यात्रा में उसकी औसत चाल 48 km/h हो। लौटते समय उसकी चाल क्या थी?","optionsHi":["36 km/h","42 km/h","30 km/h","40 km/h"],"explanationHi":"औसत = 2xy/(x + y): 2 × 60 × y/(60 + y) = 48 से 120y = 2,880 + 48y, अतः y = 40 km/h। 60 और 36 का साधारण औसत लेने पर गलत रूप से 48 आता है।","subtopic":"average-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-176","question":"A train covers the first 3/5 of a journey at 36 km/h and the rest at 24 km/h. What is its average speed for the whole journey?","options":["31.2 km/h","30 km/h","28.8 km/h","32 km/h"],"answer":1,"explanation":"Take the journey as 1 unit: time = (3/5)/36 + (2/5)/24 = 1/60 + 1/60 = 1/30, so the average speed is 30 km/h. The distance-weighted average of speeds, 31.2, and the equal-distance harmonic mean, 28.8, are traps.","difficulty":"hard","questionHi":"एक रेलगाड़ी यात्रा का पहला 3/5 भाग 36 km/h की चाल से और शेष भाग 24 km/h की चाल से तय करती है। पूरी यात्रा में उसकी औसत चाल क्या है?","optionsHi":["31.2 km/h","30 km/h","28.8 km/h","32 km/h"],"explanationHi":"यात्रा को 1 इकाई मानें: समय = (3/5)/36 + (2/5)/24 = 1/60 + 1/60 = 1/30, अतः औसत चाल 30 km/h। चालों का दूरी-भारित औसत 31.2 और बराबर दूरी वाला हरात्मक माध्य 28.8 गलत जाल हैं।","subtopic":"average-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-177","question":"A cyclist goes up a hill at 20 km/h and comes down the same path at 30 km/h. If the round trip takes 5 hours in all, how long is the path one way?","options":["50 km","60 km","75 km","120 km"],"answer":1,"explanation":"Average speed = 2 × 20 × 30/50 = 24 km/h, so the round trip is 24 × 5 = 120 km and one way is 60 km. (Check: 60/20 + 60/30 = 3 + 2 = 5 hours.)","difficulty":"hard","questionHi":"एक साइकिल सवार किसी पहाड़ी पर 20 km/h की चाल से चढ़ता है और उसी मार्ग से 30 km/h की चाल से उतरता है। यदि पूरी यात्रा में कुल 5 घंटे लगते हैं, तो मार्ग की एक ओर की लंबाई कितनी है?","optionsHi":["50 km","60 km","75 km","120 km"],"explanationHi":"औसत चाल = 2 × 20 × 30/50 = 24 km/h, अतः पूरी यात्रा 24 × 5 = 120 km की है और एक ओर की लंबाई 60 km है। (जाँच: 60/20 + 60/30 = 3 + 2 = 5 घंटे।)","subtopic":"average-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-178","question":"A journey is made in three stages whose durations are in the ratio 1 : 2 : 3, at speeds of 10 km/h, 20 km/h and 30 km/h respectively. What is the average speed for the whole journey?","options":["20 km/h","22 km/h","18 km/h","23⅓ km/h"],"answer":3,"explanation":"For stages of unequal times, average speed = total distance/total time = (1 × 10 + 2 × 20 + 3 × 30)/(1 + 2 + 3) = 140/6 = 23⅓ km/h. The plain mean 20 ignores the time weights.","difficulty":"hard","questionHi":"एक यात्रा तीन चरणों में की जाती है, जिनकी अवधियों का अनुपात 1 : 2 : 3 है और चालें क्रमशः 10 km/h, 20 km/h और 30 km/h हैं। पूरी यात्रा की औसत चाल क्या है?","optionsHi":["20 km/h","22 km/h","18 km/h","23⅓ km/h"],"explanationHi":"असमान अवधि के चरणों के लिए औसत चाल = कुल दूरी/कुल समय = (1 × 10 + 2 × 20 + 3 × 30)/(1 + 2 + 3) = 140/6 = 23⅓ km/h। साधारण माध्य 20 समय के भारांक को छोड़ देता है।","subtopic":"average-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-179","question":"Car A covers half the distance at 40 km/h and the other half at 60 km/h. Car B travels half the time at 40 km/h and the other half at 60 km/h. Over a 240 km trip, how many minutes earlier does B arrive than A?","options":["12 minutes","6 minutes","15 minutes","10 minutes"],"answer":0,"explanation":"A's average (equal distances) = 2 × 40 × 60/100 = 48 km/h, taking 240/48 = 5 h. B's average (equal times) = (40 + 60)/2 = 50 km/h, taking 4.8 h. The difference is 0.2 h = 12 minutes.","difficulty":"very-hard","questionHi":"कार A आधी दूरी 40 km/h की चाल से और शेष आधी दूरी 60 km/h की चाल से तय करती है। कार B आधा समय 40 km/h की चाल से और शेष आधा समय 60 km/h की चाल से चलती है। 240 km की यात्रा में B, A से कितने मिनट पहले पहुँचती है?","optionsHi":["12 मिनट","6 मिनट","15 मिनट","10 मिनट"],"explanationHi":"A की औसत चाल (बराबर दूरी) = 2 × 40 × 60/100 = 48 km/h, जिसमें 240/48 = 5 घंटे लगते हैं। B की औसत चाल (बराबर समय) = (40 + 60)/2 = 50 km/h, जिसमें 4.8 घंटे लगते हैं। अंतर 0.2 घंटा = 12 मिनट है।","subtopic":"average-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-180","question":"A man drives from P to Q at 48 km/h, rests for 1 hour at Q, and returns at 72 km/h, taking 6 hours in all. What is his overall average speed for the whole trip, including the halt?","options":["57.6 km/h","60 km/h","48 km/h","50 km/h"],"answer":2,"explanation":"Driving time is 6 − 1 = 5 h: d/48 + d/72 = 5d/144 = 5 gives d = 144 km. Total distance 288 km in 6 h gives 48 km/h. The harmonic mean 57.6 ignores the halt.","difficulty":"hard","questionHi":"एक व्यक्ति P से Q तक 48 km/h की चाल से गाड़ी चलाता है, Q पर 1 घंटा विश्राम करता है और 72 km/h की चाल से लौटता है, जिसमें कुल 6 घंटे लगते हैं। विश्राम सहित पूरी यात्रा में उसकी औसत चाल क्या है?","optionsHi":["57.6 km/h","60 km/h","48 km/h","50 km/h"],"explanationHi":"गाड़ी चलाने का समय 6 − 1 = 5 घंटे: d/48 + d/72 = 5d/144 = 5 से d = 144 km। 288 km की कुल दूरी 6 घंटे में तय होने पर चाल 48 km/h। हरात्मक माध्य 57.6 में विश्राम को नहीं गिना गया है।","subtopic":"average-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-181","question":"A man walking at 6 km/h reaches his office 20 minutes late, but at 8 km/h he reaches 10 minutes early. At what speed should he walk to reach exactly on time?","options":["7 km/h","7.5 km/h","7.2 km/h","6.9 km/h"],"answer":2,"explanation":"d/6 − d/8 = 30/60 gives d = 12 km. The on-time duration is 12/6 − 1/3 = 5/3 h, so the speed is 12 ÷ 5/3 = 7.2 km/h. The mean 7 of 6 and 8 is the trap.","difficulty":"very-hard","questionHi":"एक व्यक्ति 6 km/h की चाल से चलने पर अपने कार्यालय में 20 मिनट देर से पहुँचता है, परंतु 8 km/h की चाल से चलने पर 10 मिनट पहले पहुँच जाता है। ठीक समय पर पहुँचने के लिए उसे किस चाल से चलना चाहिए?","optionsHi":["7 km/h","7.5 km/h","7.2 km/h","6.9 km/h"],"explanationHi":"d/6 − d/8 = 30/60 से d = 12 km। ठीक समय का अवधि 12/6 − 1/3 = 5/3 घंटा है, अतः चाल 12 ÷ 5/3 = 7.2 km/h। 6 और 8 का माध्य 7 गलत जाल है।","subtopic":"late-early","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-182","question":"Walking at 5/6 of his usual speed, a man reaches his destination 15 minutes late. How late will he be if he walks at 4/5 of his usual speed?","options":["18¾ minutes","20 minutes","16¼ minutes","22½ minutes"],"answer":0,"explanation":"At 5/6 speed the time is 6/5 of usual, so the extra 1/5 of the usual time is 15 min and the usual time is 75 min. At 4/5 speed the time is 5/4 of usual, so the delay is 75/4 = 18¾ minutes.","difficulty":"hard","questionHi":"अपनी सामान्य चाल की 5/6 चाल से चलने पर एक व्यक्ति अपने गंतव्य पर 15 मिनट देर से पहुँचता है। यदि वह अपनी सामान्य चाल की 4/5 चाल से चले, तो कितनी देर से पहुँचेगा?","optionsHi":["18¾ मिनट","20 मिनट","16¼ मिनट","22½ मिनट"],"explanationHi":"5/6 चाल पर समय सामान्य समय का 6/5 हो जाता है, अतः सामान्य समय का अतिरिक्त 1/5 भाग 15 मिनट है और सामान्य समय 75 मिनट है। 4/5 चाल पर समय सामान्य का 5/4 होता है, इसलिए देरी 75/4 = 18¾ मिनट है।","subtopic":"late-early","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-183","question":"A train normally covers a 300 km journey at 50 km/h. It starts 40 minutes late. At what constant speed must it run to reach on time?","options":["54 km/h","57.5 km/h","55 km/h","56.25 km/h"],"answer":3,"explanation":"Normal time = 300/50 = 6 h. With 40 min lost, the available time is 6 − 2/3 = 16/3 h, so the speed is 300 ÷ 16/3 = 56.25 km/h.","difficulty":"hard","questionHi":"एक रेलगाड़ी सामान्यतः 300 km की यात्रा 50 km/h की चाल से तय करती है। वह 40 मिनट देर से चलती है। समय पर पहुँचने के लिए उसे किस नियत चाल से चलना होगा?","optionsHi":["54 km/h","57.5 km/h","55 km/h","56.25 km/h"],"explanationHi":"सामान्य समय = 300/50 = 6 घंटे। 40 मिनट देर से चलने पर उपलब्ध समय 6 − 2/3 = 16/3 घंटे है, अतः चाल 300 ÷ 16/3 = 56.25 km/h।","subtopic":"late-early","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-184","question":"A bus covers a journey in 6 hours. If its speed were 20 km/h more, it would take 1½ hours less. How long is the journey?","options":["300 km","360 km","400 km","420 km"],"answer":1,"explanation":"With speed v: 6v = 4.5(v + 20), so 1.5v = 90 and v = 60 km/h. Distance = 60 × 6 = 360 km.","difficulty":"hard","questionHi":"एक बस कोई यात्रा 6 घंटे में तय करती है। यदि उसकी चाल 20 km/h अधिक होती, तो उसे 1½ घंटे कम लगते। यात्रा की दूरी कितनी है?","optionsHi":["300 km","360 km","400 km","420 km"],"explanationHi":"चाल v लें: 6v = 4.5(v + 20), अतः 1.5v = 90 और v = 60 km/h। दूरी = 60 × 6 = 360 km।","subtopic":"late-early","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-185","question":"A boy leaves home 10 minutes later than usual. By walking 25% faster than his usual speed he reaches school exactly on time. How long does he usually take to reach school?","options":["40 minutes","50 minutes","45 minutes","60 minutes"],"answer":1,"explanation":"At 5/4 of the speed the time is 4/5 of usual, so he saves 1/5 of the usual time, which equals the 10 minutes lost. Usual time = 10 × 5 = 50 minutes.","difficulty":"hard","questionHi":"एक लड़का घर से सामान्य से 10 मिनट देर से निकलता है। अपनी सामान्य चाल से 25% तेज चलकर वह ठीक समय पर विद्यालय पहुँच जाता है। वह सामान्यतः विद्यालय पहुँचने में कितना समय लेता है?","optionsHi":["40 मिनट","50 मिनट","45 मिनट","60 मिनट"],"explanationHi":"5/4 चाल पर समय सामान्य का 4/5 रह जाता है, अतः वह सामान्य समय का 1/5 बचाता है, जो खोए हुए 10 मिनट के बराबर है। सामान्य समय = 10 × 5 = 50 मिनट।","subtopic":"late-early","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-186","question":"A train is to cover 270 km at 45 km/h. After covering the first third of the journey at this speed it is stopped for 24 minutes. At what speed must it run the rest of the journey to reach the destination on time?","options":["45 km/h","54 km/h","60 km/h","50 km/h"],"answer":3,"explanation":"Total time = 270/45 = 6 h. The first 90 km takes 2 h and the halt 0.4 h, leaving 6 − 2 − 0.4 = 3.6 h for 180 km, so the speed is 180/3.6 = 50 km/h.","difficulty":"hard","questionHi":"एक रेलगाड़ी को 270 km की दूरी 45 km/h की चाल से तय करनी है। इसी चाल से यात्रा का पहला एक-तिहाई भाग तय करने के बाद उसे 24 मिनट के लिए रोक दिया जाता है। गंतव्य पर समय पर पहुँचने के लिए उसे शेष यात्रा किस चाल से तय करनी होगी?","optionsHi":["45 km/h","54 km/h","60 km/h","50 km/h"],"explanationHi":"कुल समय = 270/45 = 6 घंटे। पहले 90 km में 2 घंटे और रुकने में 0.4 घंटा लगा, अतः 180 km के लिए 6 − 2 − 0.4 = 3.6 घंटे बचे, इसलिए चाल 180/3.6 = 50 km/h।","subtopic":"late-early","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-187","question":"A man travels 120 km: half of it by train at 60 km/h, one-third of it by bus at 40 km/h and the remaining one-sixth on foot at 5 km/h. How long does the whole journey take?","options":["6 hours","5 hours","7 hours","4½ hours"],"answer":0,"explanation":"The parts are 60 km, 40 km and 20 km. Times: 60/60 = 1 h, 40/40 = 1 h and 20/5 = 4 h, so the total is 6 hours.","difficulty":"hard","questionHi":"एक व्यक्ति 120 km की यात्रा करता है: उसका आधा भाग रेलगाड़ी से 60 km/h की चाल से, एक-तिहाई भाग बस से 40 km/h की चाल से और शेष एक-छठा भाग पैदल 5 km/h की चाल से। पूरी यात्रा में कितना समय लगता है?","optionsHi":["6 घंटे","5 घंटे","7 घंटे","4½ घंटे"],"explanationHi":"भाग 60 km, 40 km और 20 km के हैं। समय: 60/60 = 1 घंटा, 40/40 = 1 घंटा और 20/5 = 4 घंटे, अतः कुल समय 6 घंटे।","subtopic":"basic-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-188","question":"A and B travel the same 60 km. A's speed is 5 km/h more than B's, and A takes 2 hours less than B. What is A's speed?","options":["12 km/h","20 km/h","15 km/h","10 km/h"],"answer":2,"explanation":"If B's speed is x: 60/x − 60/(x + 5) = 2 gives x(x + 5) = 150, so x = 10 km/h and A's speed is 15 km/h. Check: 6 h − 4 h = 2 h.","difficulty":"hard","questionHi":"A और B एक ही 60 km की दूरी तय करते हैं। A की चाल B की चाल से 5 km/h अधिक है और A, B से 2 घंटे कम समय लेता है। A की चाल क्या है?","optionsHi":["12 km/h","20 km/h","15 km/h","10 km/h"],"explanationHi":"यदि B की चाल x है: 60/x − 60/(x + 5) = 2 से x(x + 5) = 150, अतः x = 10 km/h और A की चाल 15 km/h। जाँच: 6 घंटे − 4 घंटे = 2 घंटे।","subtopic":"basic-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-189","question":"A man increases his speed by 5 km/h, and the time he takes for a fixed journey falls by 1/6 of the original time. What was his original speed?","options":["20 km/h","30 km/h","25 km/h","15 km/h"],"answer":2,"explanation":"The new time is 5/6 of the old, so the new speed is 6/5 of the old: v + 5 = 1.2v, hence 0.2v = 5 and v = 25 km/h.","difficulty":"hard","questionHi":"एक व्यक्ति अपनी चाल 5 km/h बढ़ा देता है और एक निश्चित यात्रा में लगने वाला समय मूल समय का 1/6 भाग कम हो जाता है। उसकी मूल चाल क्या थी?","optionsHi":["20 km/h","30 km/h","25 km/h","15 km/h"],"explanationHi":"नया समय पुराने समय का 5/6 है, अतः नई चाल पुरानी चाल की 6/5 है: v + 5 = 1.2v, इसलिए 0.2v = 5 और v = 25 km/h।","subtopic":"basic-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-190","question":"A person travels 100 km, partly by car at 50 km/h and the rest by train at 100 km/h. If the whole journey takes 1.4 hours, how far does he travel by car?","options":["40 km","60 km","50 km","30 km"],"answer":0,"explanation":"If x km is by car: x/50 + (100 − x)/100 = 1.4 gives 2x + 100 − x = 140, so x = 40 km.","difficulty":"moderate","questionHi":"एक व्यक्ति 100 km की यात्रा करता है, कुछ भाग कार से 50 km/h की चाल से और शेष रेलगाड़ी से 100 km/h की चाल से। यदि पूरी यात्रा में 1.4 घंटे लगते हैं, तो वह कार से कितनी दूरी तय करता है?","optionsHi":["40 km","60 km","50 km","30 km"],"explanationHi":"यदि x km कार से हो: x/50 + (100 − x)/100 = 1.4 से 2x + 100 − x = 140, अतः x = 40 km।","subtopic":"basic-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-191","question":"A man covers 15 km in 3 hours, walking partly at 4 km/h and partly at 6 km/h. How many kilometres does he walk at 6 km/h?","options":["6 km","7.5 km","10 km","9 km"],"answer":3,"explanation":"If x km is at 4 km/h: x/4 + (15 − x)/6 = 3 gives 3x + 30 − 2x = 36, so x = 6 km. The distance at 6 km/h is 15 − 6 = 9 km, and 6 km is the other part.","difficulty":"hard","questionHi":"एक व्यक्ति 15 km की दूरी 3 घंटे में तय करता है, कुछ भाग 4 km/h की चाल से और कुछ भाग 6 km/h की चाल से चलकर। वह 6 km/h की चाल से कितने किलोमीटर चलता है?","optionsHi":["6 km","7.5 km","10 km","9 km"],"explanationHi":"यदि x km की दूरी 4 km/h पर हो: x/4 + (15 − x)/6 = 3 से 3x + 30 − 2x = 36, अतः x = 6 km। 6 km/h पर दूरी 15 − 6 = 9 km है, और 6 km दूसरा भाग है।","subtopic":"basic-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-192","question":"A boat takes 10 hours to go 30 km upstream and 44 km downstream, and 13 hours to go 40 km upstream and 55 km downstream. What is the speed of the stream?","options":["2 km/h","3 km/h","4 km/h","5 km/h"],"answer":1,"explanation":"Let upstream and downstream speeds be u and d. Scaling the first equation by 4 and the second by 3 gives 176/d − 165/d = 40 − 39, so d = 11. Then 30/u = 10 − 4 = 6 gives u = 5, and the stream speed is (11 − 5)/2 = 3 km/h.","difficulty":"very-hard","questionHi":"एक नाव 30 km धारा के प्रतिकूल और 44 km धारा के अनुकूल जाने में 10 घंटे तथा 40 km धारा के प्रतिकूल और 55 km धारा के अनुकूल जाने में 13 घंटे लेती है। धारा की चाल क्या है?","optionsHi":["2 km/h","3 km/h","4 km/h","5 km/h"],"explanationHi":"धारा के प्रतिकूल और अनुकूल चालें u और d लें। पहले समीकरण को 4 और दूसरे को 3 से गुणा करने पर 176/d − 165/d = 40 − 39, अतः d = 11। तब 30/u = 10 − 4 = 6 से u = 5 और धारा की चाल (11 − 5)/2 = 3 km/h।","subtopic":"boats-streams","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-193","question":"A boat that goes 5 km/h in still water takes 5 hours to go 12 km upstream and return 12 km downstream. What is the speed of the stream?","options":["2 km/h","1 km/h","1.5 km/h","3 km/h"],"answer":1,"explanation":"Total time = 12/(5 − s) + 12/(5 + s) = 120/(25 − s²) = 5, so 25 − s² = 24 and s = 1 km/h. Check: 12/4 + 12/6 = 3 + 2 = 5 hours.","difficulty":"hard","questionHi":"स्थिर जल में 5 km/h की चाल से चलने वाली नाव धारा के प्रतिकूल 12 km जाने और धारा के अनुकूल 12 km लौटने में 5 घंटे लेती है। धारा की चाल क्या है?","optionsHi":["2 km/h","1 km/h","1.5 km/h","3 km/h"],"explanationHi":"कुल समय = 12/(5 − s) + 12/(5 + s) = 120/(25 − s²) = 5, अतः 25 − s² = 24 और s = 1 km/h। जाँच: 12/4 + 12/6 = 3 + 2 = 5 घंटे।","subtopic":"boats-streams","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-194","question":"A boat takes twice as long to go a certain distance upstream as downstream. If its speed in still water is 12 km/h, how long will it take to go 40 km upstream?","options":["3⅓ hours","2½ hours","4 hours","5 hours"],"answer":3,"explanation":"Downstream speed is twice the upstream speed: 12 + s = 2(12 − s), so s = 4. Upstream speed = 8 km/h, so 40 km takes 5 hours. 3⅓ h ignores the stream.","difficulty":"moderate","questionHi":"एक नाव धारा के प्रतिकूल कोई दूरी तय करने में धारा के अनुकूल की तुलना में दोगुना समय लेती है। यदि स्थिर जल में उसकी चाल 12 km/h है, तो वह धारा के प्रतिकूल 40 km जाने में कितना समय लेगी?","optionsHi":["3⅓ घंटे","2½ घंटे","4 घंटे","5 घंटे"],"explanationHi":"धारा के अनुकूल चाल प्रतिकूल चाल की दोगुनी है: 12 + s = 2(12 − s), अतः s = 4। प्रतिकूल चाल = 8 km/h, इसलिए 40 km में 5 घंटे लगेंगे। 3⅓ घंटे में धारा को नहीं गिना गया है।","subtopic":"boats-streams","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-195","question":"A man rows a certain distance and back in 8 hours. He can row 5 km with the stream in the same time as 3 km against it. If the distance each way is 30 km, what is the speed of the stream?","options":["2 km/h","1 km/h","3 km/h","4 km/h"],"answer":0,"explanation":"Downstream : upstream speeds = 5 : 3, so they are 5k and 3k, the still-water speed is 4k and the stream k. Time = 30/5k + 30/3k = 16/k = 8, so k = 2 km/h, which is the stream's speed.","difficulty":"hard","questionHi":"एक व्यक्ति नाव से कोई दूरी तय करके लौटने में कुल 8 घंटे लेता है। वह जितने समय में धारा के अनुकूल 5 km जाता है, उतने समय में धारा के प्रतिकूल 3 km जाता है। यदि एक ओर की दूरी 30 km है, तो धारा की चाल क्या है?","optionsHi":["2 km/h","1 km/h","3 km/h","4 km/h"],"explanationHi":"धारा के अनुकूल : प्रतिकूल चाल = 5 : 3, अतः वे 5k और 3k हैं, स्थिर जल में चाल 4k और धारा की चाल k है। समय = 30/5k + 30/3k = 16/k = 8, अतः k = 2 km/h, जो धारा की चाल है।","subtopic":"boats-streams","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-196","question":"A boat covers 24 km upstream in 8 hours and 36 km downstream in 4 hours. How long will it take to cover 60 km in still water?","options":["9 hours","12 hours","10 hours","8 hours"],"answer":2,"explanation":"Upstream speed = 24/8 = 3 km/h and downstream speed = 36/4 = 9 km/h, so the still-water speed is (3 + 9)/2 = 6 km/h. Then 60 km takes 60/6 = 10 hours.","difficulty":"very-hard","questionHi":"एक नाव धारा के प्रतिकूल 24 km 8 घंटे में और धारा के अनुकूल 36 km 4 घंटे में तय करती है। स्थिर जल में 60 km तय करने में उसे कितना समय लगेगा?","optionsHi":["9 घंटे","12 घंटे","10 घंटे","8 घंटे"],"explanationHi":"धारा के प्रतिकूल चाल = 24/8 = 3 km/h और धारा के अनुकूल चाल = 36/4 = 9 km/h, अतः स्थिर जल में चाल (3 + 9)/2 = 6 km/h। तब 60 km में 60/6 = 10 घंटे लगेंगे।","subtopic":"boats-streams","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-197","question":"A boat's upstream speed is 3/5 of its downstream speed. Over a 30 km stretch it takes 2 hours longer upstream than downstream. What is the boat's speed in still water?","options":["7 km/h","6 km/h","8 km/h","10 km/h"],"answer":2,"explanation":"If the downstream speed is d, upstream is 0.6d: 30/0.6d − 30/d = 2 gives 20/d = 2, so d = 10 and upstream = 6 km/h. Still-water speed = (10 + 6)/2 = 8 km/h.","difficulty":"hard","questionHi":"एक नाव की धारा के प्रतिकूल चाल उसकी धारा के अनुकूल चाल की 3/5 है। 30 km की दूरी तय करने में उसे धारा के प्रतिकूल, धारा के अनुकूल की तुलना में 2 घंटे अधिक लगते हैं। स्थिर जल में नाव की चाल क्या है?","optionsHi":["7 km/h","6 km/h","8 km/h","10 km/h"],"explanationHi":"यदि धारा के अनुकूल चाल d हो, तो प्रतिकूल चाल 0.6d है: 30/0.6d − 30/d = 2 से 20/d = 2, अतः d = 10 और प्रतिकूल चाल = 6 km/h। स्थिर जल में चाल = (10 + 6)/2 = 8 km/h।","subtopic":"boats-streams","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-198","question":"A thief is 120 m ahead of a policeman. The thief runs at 12 km/h and the policeman chases him at 15 km/h. How far must the policeman run to catch him?","options":["600 m","480 m","720 m","900 m"],"answer":0,"explanation":"The policeman gains 3 km/h = 5/6 m/s, so he needs 120 ÷ (5/6) = 144 s. In that time he runs (25/6) × 144 = 600 m. The thief runs 480 m in that time.","difficulty":"moderate","questionHi":"एक चोर किसी पुलिसकर्मी से 120 m आगे है। चोर 12 km/h की चाल से भागता है और पुलिसकर्मी 15 km/h की चाल से उसका पीछा करता है। उसे पकड़ने के लिए पुलिसकर्मी को कितनी दूरी दौड़नी होगी?","optionsHi":["600 m","480 m","720 m","900 m"],"explanationHi":"पुलिसकर्मी 3 km/h = 5/6 m/s की दर से पास आता है, इसलिए उसे 120 ÷ (5/6) = 144 s लगते हैं। इस समय में वह (25/6) × 144 = 600 m दौड़ता है। इस समय में चोर 480 m दौड़ता है।","subtopic":"relative-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-199","question":"Two towns are 240 km apart. Two cars leave them at the same time towards each other at 35 km/h and 45 km/h. A bird flies back and forth between the cars at 90 km/h until they meet. How far does the bird fly in all?","options":["240 km","180 km","360 km","270 km"],"answer":3,"explanation":"The cars meet after 240/(35 + 45) = 3 hours, and the bird flies for exactly that time: 90 × 3 = 270 km. There is no need to sum the back-and-forth trips.","difficulty":"hard","questionHi":"दो नगर 240 km दूर हैं। दो कारें एक ही समय पर उनसे एक-दूसरे की ओर क्रमशः 35 km/h और 45 km/h की चाल से चलती हैं। एक पक्षी दोनों कारों के बीच 90 km/h की चाल से आगे-पीछे उड़ता रहता है जब तक वे मिल न जाएँ। पक्षी कुल कितनी दूरी उड़ता है?","optionsHi":["240 km","180 km","360 km","270 km"],"explanationHi":"कारें 240/(35 + 45) = 3 घंटे में मिलती हैं और पक्षी ठीक उतने ही समय उड़ता है: 90 × 3 = 270 km। आगे-पीछे की यात्राओं का योग निकालने की आवश्यकता नहीं है।","subtopic":"relative-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-200","question":"In a 1,000 m race, A beats B by 40 m or by 8 seconds. What time does A take to finish the race?","options":["200 seconds","192 seconds","184 seconds","160 seconds"],"answer":1,"explanation":"B covers the last 40 m in 8 s, so B's speed is 5 m/s and B needs 1,000/5 = 200 s. A finishes 8 s earlier, in 192 seconds.","difficulty":"very-hard","questionHi":"1,000 m की दौड़ में A, B को 40 m या 8 सेकंड से हराता है। A दौड़ पूरी करने में कितना समय लेता है?","optionsHi":["200 सेकंड","192 सेकंड","184 सेकंड","160 सेकंड"],"explanationHi":"B अंतिम 40 m 8 s में तय करता है, अतः B की चाल 5 m/s है और B को 1,000/5 = 200 s लगते हैं। A उससे 8 s पहले, यानी 192 सेकंड में, दौड़ पूरी कर लेता है।","subtopic":"relative-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-201","question":"A walker leaves a town at 4 km/h. Three hours later a cyclist leaves the same town along the same road at 12 km/h. How far from the town does the cyclist overtake the walker?","options":["12 km","18 km","24 km","36 km"],"answer":1,"explanation":"The walker has a 4 × 3 = 12 km lead. The cyclist gains 12 − 4 = 8 km/h, so he catches up in 12/8 = 1.5 h, having ridden 12 × 1.5 = 18 km.","difficulty":"hard","questionHi":"एक पैदल यात्री 4 km/h की चाल से किसी नगर से निकलता है। तीन घंटे बाद एक साइकिल सवार उसी नगर से उसी सड़क पर 12 km/h की चाल से निकलता है। साइकिल सवार नगर से कितनी दूरी पर पैदल यात्री को पकड़ लेगा?","optionsHi":["12 km","18 km","24 km","36 km"],"explanationHi":"पैदल यात्री के पास 4 × 3 = 12 km की बढ़त है। साइकिल सवार 12 − 4 = 8 km/h की दर से पास आता है, इसलिए वह 12/8 = 1.5 घंटे में उसे पकड़ लेता है, तब तक वह 12 × 1.5 = 18 km चल चुका होता है।","subtopic":"relative-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-202","question":"Car A at 70 km/h and car B at 50 km/h start together from the same point in the same direction. After 3 hours A turns back and drives towards B at the same speed. How long after turning do they meet?","options":["36 minutes","1 hour","45 minutes","30 minutes"],"answer":3,"explanation":"After 3 hours A is at 210 km and B at 150 km, so the gap is 60 km. Now they approach each other at 70 + 50 = 120 km/h, so they meet in 60/120 = 0.5 h = 30 minutes.","difficulty":"hard","questionHi":"कार A (70 km/h) और कार B (50 km/h) एक ही बिंदु से एक ही दिशा में साथ-साथ चलना शुरू करती हैं। 3 घंटे बाद A मुड़कर उसी चाल से B की ओर चलने लगती है। मुड़ने के कितने समय बाद वे मिलेंगी?","optionsHi":["36 मिनट","1 घंटा","45 मिनट","30 मिनट"],"explanationHi":"3 घंटे बाद A, 210 km पर और B, 150 km पर है, अतः दोनों के बीच 60 km का अंतर है। अब वे 70 + 50 = 120 km/h की दर से एक-दूसरे के पास आती हैं, इसलिए 60/120 = 0.5 घंटा = 30 मिनट में मिलेंगी।","subtopic":"relative-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-203","question":"A man walks up a moving escalator and counts 30 steps. When he walks down the same escalator (which keeps moving up), at the same walking speed, he counts 60 steps. How many steps are visible on the escalator when it is stationary?","options":["40","45","50","36"],"answer":0,"explanation":"Let the escalator carry k steps for every step the man walks. Going up, N = 30 + 30k; going down, N = 60 − 60k. Equating gives 90k = 30, so k = 1/3 and N = 30 + 10 = 40 steps.","difficulty":"very-hard","questionHi":"एक व्यक्ति चलती हुई एस्केलेटर पर ऊपर चढ़ता है और 30 सीढ़ियाँ गिनता है। उसी चाल से उसी एस्केलेटर पर (जो ऊपर की ओर चलती रहती है) नीचे उतरता है, तो वह 60 सीढ़ियाँ गिनता है। एस्केलेटर के स्थिर होने पर उसकी कितनी सीढ़ियाँ दिखाई देती हैं?","optionsHi":["40","45","50","36"],"explanationHi":"माना एस्केलेटर आदमी के प्रत्येक कदम के साथ k सीढ़ियाँ ऊपर ले जाती है। चढ़ते समय N = 30 + 30k; उतरते समय N = 60 − 60k। बराबर करने पर 90k = 30, अतः k = 1/3 और N = 30 + 10 = 40 सीढ़ियाँ।","subtopic":"relative-speed","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-204","question":"Two trains 120 m and 180 m long run on parallel tracks. Running in opposite directions they cross each other in 9 seconds, and running in the same direction the faster crosses the slower in 45 seconds. What is the speed of the faster train?","options":["60 km/h","84 km/h","72 km/h","48 km/h"],"answer":2,"explanation":"Total length 300 m. Sum of speeds = 300/9 = 100/3 m/s = 120 km/h; difference = 300/45 = 20/3 m/s = 24 km/h. The faster speed is (120 + 24)/2 = 72 km/h (the slower is 48).","difficulty":"hard","questionHi":"120 m और 180 m लंबी दो रेलगाड़ियाँ समानांतर पटरियों पर चल रही हैं। विपरीत दिशाओं में चलने पर वे एक-दूसरे को 9 सेकंड में पार करती हैं और एक ही दिशा में चलने पर तेज गाड़ी धीमी गाड़ी को 45 सेकंड में पार करती है। तेज गाड़ी की चाल क्या है?","optionsHi":["60 km/h","84 km/h","72 km/h","48 km/h"],"explanationHi":"कुल लंबाई 300 m है। चालों का योग = 300/9 = 100/3 m/s = 120 km/h; अंतर = 300/45 = 20/3 m/s = 24 km/h। तेज गाड़ी की चाल (120 + 24)/2 = 72 km/h है (धीमी की 48 km/h)।","subtopic":"trains","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-205","question":"A 200 m long train passes a man walking at 6 km/h in the same direction in 20 seconds. What is the speed of the train?","options":["30 km/h","36 km/h","42 km/h","48 km/h"],"answer":2,"explanation":"Relative speed = 200/20 = 10 m/s = 36 km/h. The man moves in the same direction, so train speed = 36 + 6 = 42 km/h. Subtracting his speed by mistake gives 36 − 6 = 30 km/h.","difficulty":"moderate","questionHi":"200 m लंबी एक रेलगाड़ी उसी दिशा में 6 km/h की चाल से चल रहे एक आदमी को 20 सेकंड में पार करती है। रेलगाड़ी की चाल क्या है?","optionsHi":["30 km/h","36 km/h","42 km/h","48 km/h"],"explanationHi":"सापेक्ष चाल = 200/20 = 10 m/s = 36 km/h। आदमी उसी दिशा में चल रहा है, अतः रेलगाड़ी की चाल = 36 + 6 = 42 km/h। आदमी की चाल को गलती से घटा देने पर 36 − 6 = 30 km/h आता है।","subtopic":"trains","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-206","question":"Stations A and B are 400 km apart. A train leaves A for B at 40 km/h. One hour later another train leaves B for A at 50 km/h. How far from A do the trains meet?","options":["200 km","160 km","240 km","180 km"],"answer":0,"explanation":"In the first hour the first train covers 40 km, leaving 360 km. They close at 90 km/h, so they meet 4 hours after the second train starts. The first train has then run 5 hours: 40 × 5 = 200 km from A.","difficulty":"hard","questionHi":"स्टेशन A और B के बीच की दूरी 400 km है। एक रेलगाड़ी A से B के लिए 40 km/h की चाल से चलती है। एक घंटे बाद दूसरी रेलगाड़ी B से A के लिए 50 km/h की चाल से चलती है। दोनों गाड़ियाँ A से कितनी दूरी पर मिलेंगी?","optionsHi":["200 km","160 km","240 km","180 km"],"explanationHi":"पहले घंटे में पहली गाड़ी 40 km चलती है, शेष 360 km रहता है। वे 90 km/h की दर से पास आती हैं, इसलिए दूसरी गाड़ी के चलने के 4 घंटे बाद मिलती हैं। तब तक पहली गाड़ी 5 घंटे चल चुकी होती है: A से 40 × 5 = 200 km।","subtopic":"trains","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-207","question":"A train passes two men walking in the same direction as the train, at 2 km/h and 4 km/h, in 9 seconds and 10 seconds respectively. What is the length of the train?","options":["45 m","55 m","60 m","50 m"],"answer":3,"explanation":"Let the train's speed be v m/s: L = (v − 5/9) × 9 = (v − 10/9) × 10, so 9v − 5 = 10v − 100/9, giving v = 55/9 m/s (22 km/h). Then L = (55/9 − 5/9) × 9 = 50 m.","difficulty":"very-hard","questionHi":"एक रेलगाड़ी अपनी ही दिशा में चल रहे दो आदमियों को, जो क्रमशः 2 km/h और 4 km/h की चाल से चल रहे हैं, क्रमशः 9 सेकंड और 10 सेकंड में पार करती है। रेलगाड़ी की लंबाई क्या है?","optionsHi":["45 m","55 m","60 m","50 m"],"explanationHi":"रेलगाड़ी की चाल v m/s लें: L = (v − 5/9) × 9 = (v − 10/9) × 10, अतः 9v − 5 = 10v − 100/9, जिससे v = 55/9 m/s (22 km/h)। तब L = (55/9 − 5/9) × 9 = 50 m।","subtopic":"trains","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-tsd-208","question":"After running 50 km a train meets with an accident and then runs at 3/5 of its former speed, arriving 2 hours late. Had the accident occurred 50 km farther on, it would have arrived only 1 hour 20 minutes late. What was the train's original speed?","options":["40 km/h","50 km/h","60 km/h","45 km/h"],"answer":1,"explanation":"If the accident is after x km, the delay is (D − x)/(0.6v) − (D − x)/v = (2/3)(D − x)/v. For x = 50 this is 2 h; for x = 100 it is 4/3 h. Subtracting, (2/3)(50)/v = 2/3, so v = 50 km/h (and D = 200 km).","difficulty":"very-hard","questionHi":"50 km चलने के बाद एक रेलगाड़ी दुर्घटनाग्रस्त हो जाती है और फिर अपनी पूर्व चाल की 3/5 चाल से चलती है तथा 2 घंटे देर से पहुँचती है। यदि दुर्घटना 50 km और आगे हुई होती, तो वह केवल 1 घंटा 20 मिनट देर से पहुँचती। रेलगाड़ी की मूल चाल क्या थी?","optionsHi":["40 km/h","50 km/h","60 km/h","45 km/h"],"explanationHi":"यदि दुर्घटना x km बाद हो, तो देरी (D − x)/(0.6v) − (D − x)/v = (2/3)(D − x)/v होती है। x = 50 के लिए यह 2 घंटे है; x = 100 के लिए 4/3 घंटे। घटाने पर (2/3)(50)/v = 2/3, अतः v = 50 km/h (और D = 200 km)।","subtopic":"trains","source":"SSC CGL Tier 2 · IBPS PO Mains"},
];

export default questions;
